/// A question asked off the window's thread (#267): the provider's
/// requests run there, the tools the model calls cross to the window,
/// which answers them on its own thread as the AI port's are.
struct AskRun {
    question: String,
    arrives: std::sync::mpsc::Receiver<AskArrived>,
    outputs: Sender<Vec<ToolOutput>>,
    /// The AI Task waiting before it was asked.
    before: Option<String>,
    /// The AI Task its changes go into.
    task: Option<String>,
    /// The Notes its model read in full so far, for the status line
    /// (#317).
    read: Vec<String>,
}

/// What comes from the thread asking.
enum AskArrived {
    Tools(Vec<ToolCall>),
    Done(Result<ask::Answer, ask::AskError>),
}

/// A Note in a window of its own (#287): the App showing it and its
/// viewport, and whether it is to come forward.
struct NoteWindow {
    app: Box<App>,
    viewport: egui::ViewportId,
    size: egui::Vec2,
    forward: bool,
    /// Opened this frame: drawn from the next, once the dialog it may
    /// have shown in is gone.
    fresh: bool,
}

/// Makes or fills in the own Profile in a store with this computer's
/// defaults, as [`login::apply_system_defaults`] does.
pub type ProfileDefaults = Box<dyn Fn(&Store) -> oldbrainfix_core::Result<Profile>>;

/// Asks for a folder, or a file to open, with the dialog's title.
pub type FolderPicker = Box<dyn Fn(&str) -> Option<std::path::PathBuf>>;

/// Asks for a file to open, with the dialog's title and the folder it
/// starts in.
pub type FilePickerIn = Box<dyn Fn(&str, Option<&std::path::Path>) -> Option<std::path::PathBuf>>;

/// Asks for files to open, with the dialog's title; none when cancelled.
pub type FilesPicker = Box<dyn Fn(&str) -> Vec<std::path::PathBuf>>;

/// Asks where to save a file, with the dialog's title and the name it
/// proposes.
pub type FileSaver = Box<dyn Fn(&str, &str) -> Option<std::path::PathBuf>>;

/// Opens a file in another program; an error when none opened it.
pub type FileOpener = Box<dyn Fn(&std::path::Path) -> std::io::Result<()>>;

/// The name a bundle for the person `person`, whose own Profile name is
/// `name`, is proposed under on `day`: the day's bundle name with theirs
/// in it, so the bundles for several people, saved one after another,
/// never overwrite each other (the phone's `changesFileName`).
fn changes_file_name(day: chrono::NaiveDate, person: &str, name: &str) -> String {
    let part = |text: &str| {
        text.split(|c: char| !c.is_alphanumeric())
            .filter(|w| !w.is_empty())
            .collect::<Vec<_>>()
            .join("-")
    };
    let who = Some(part(name))
        .filter(|w| !w.is_empty())
        .unwrap_or_else(|| part(person));
    let short: String = who.chars().take(32).collect();
    let base = bundle::file_name(day);
    match base.rsplit_once('.') {
        Some((stem, ext)) => format!("{stem}-{short}.{ext}"),
        None => base,
    }
}

/// The dialogs' filter for bundle files, and Sent Items and Profile
/// card files to open.
fn bundle_dialog(title: &str) -> rfd::FileDialog {
    rfd::FileDialog::new().set_title(title).add_filter(
        oldbrainfix_core::APP_NAME,
        &[bundle::EXTENSION, sent::EXTENSION, cards::EXTENSION],
    )
}

/// Writes the Pack `pack` as `ticks` pick from it, with the own Profile
/// when `profile`, to the file at `path`.
fn write_pack_file(
    store: &Store,
    pack: &Pack,
    ticks: &PackTicks,
    profile: bool,
    path: &std::path::Path,
) -> std::result::Result<(), String> {
    let bytes = store
        .write_pack(pack, ticks, profile)
        .map_err(|e| e.to_string())?;
    std::fs::write(path, bytes).map_err(|e| e.to_string())
}

/// The file at `path` as far as it may be a Pack (#165): read whole when
/// it is one, as a Pack has no size limit, unless it is larger than a
/// Sent Item or a card file can be (`most`); no Pack, read only as far
/// as its first byte that is no blank, when that opens no JSON object.
fn pack_file(path: &std::path::Path, most: u64) -> PackFile {
    use std::io::Read;
    let mut head = [0u8; 64];
    let Ok(read) = std::fs::File::open(path).and_then(|mut file| file.read(&mut head)) else {
        return PackFile::No;
    };
    if !head.get(..read).is_some_and(packs::starts_like_json) {
        return PackFile::No;
    }
    if std::fs::metadata(path).is_ok_and(|m| m.len() > most) {
        return PackFile::Large;
    }
    match read_pack_file(path) {
        Some(bytes) => PackFile::Bytes(bytes),
        None => PackFile::No,
    }
}

/// The bytes of the file at `path` when it is a Pack.
fn read_pack_file(path: &std::path::Path) -> Option<Vec<u8>> {
    let bytes = std::fs::read(path).ok()?;
    packs::looks_like_pack(&bytes).then_some(bytes)
}

