/// ending (#149).
fn photo_dialog(title: &str, name: &str) -> rfd::FileDialog {
    let dialog = rfd::FileDialog::new().set_title(title).set_file_name(name);
    match std::path::Path::new(name)
        .extension()
        .and_then(|e| e.to_str())
    {
        Some(ending) => dialog.add_filter(ending.to_uppercase(), &[ending]),
        None => dialog,
    }
}

