    /// Does what the Backups card asked.
    fn backup(&mut self, asked: BackupAction) -> oldbrainfix_core::Result<()> {
        let t = self.t;
        match asked {
            BackupAction::SetUp => {
                let Some(passphrase) = self.backup_form.taken(&t) else {
                    return Ok(());
                };
                backup::set_up(
                    &self.store,
                    &passphrase,
                    backup::Kdf::STANDARD,
                    &mut backup::system_random,
                )?;
                self.backup_form = Passphrase::default();
                self.backup(BackupAction::SaveSheet)?;
            }
            BackupAction::SaveSheet => {
                let Some(pdf) = backup_view::sheet(&t, &self.store, &self.wall) else {
                    return Ok(());
                };
                let Some(mut path) = (self.sheet_saver)(
                    t.backup_sheet_save_title(),
                    "oldbrainfix-recovery-sheet.pdf",
                ) else {
                    return Ok(());
                };
                if path.extension().is_none_or(|e| e != "pdf") {
                    path.set_extension("pdf");
                }
                match std::fs::write(&path, pdf) {
                    Ok(()) => self.notice = Some(t.backup_sheet_saved().to_string()),
                    Err(e) => self.announce_failure(
                        t.backup_sheet_not_out(),
                        t.backup_sheet_not_out_title(),
                        (t.backup_sheet_failed_cause(), t.nothing_lost_fix()),
                        format!("recovery sheet: {e}"),
                    ),
                }
            }
            BackupAction::PickFolder => {
                if let Some(path) = (self.folder_picker)(t.backup_folder_pick_title()) {
                    self.store
                        .set_backup_folder(Some(&path.to_string_lossy()))?;
                    self.backup(BackupAction::Now)?;
                }
            }
            BackupAction::Weekly(on) => self.store.set_backups_weekly(on)?,
            BackupAction::OpenNotes => self.open_backup_notes()?,
            BackupAction::Now => match backups::now(&self.store) {
                // Shown as the last Backup on the card: no announcement
                // (UI laws).
                Ok(_) => {}
                Err(e) => self.announce_failure(
                    t.backup_not_written(),
                    t.backup_not_written_title(),
                    (t.backup_failed_cause(), t.backup_failed_fix()),
                    format!("backup: {e}"),
                ),
            },
        }
        Ok(())
    }

    /// Does what the first start's view asked.
    fn welcome_action(&mut self, asked: WelcomeAction) -> oldbrainfix_core::Result<()> {
        let t = self.t;
        match asked {
            WelcomeAction::New => {
                if let Some(welcome) = &mut self.welcome {
                    welcome.starter = Some(starter_set_view::all());
                }
                self.notice = None;
            }
            WelcomeAction::Plant => {
                let picked = self
                    .welcome
                    .as_ref()
                    .and_then(|w| w.starter.clone())
                    .unwrap_or_default();
                let picked: Vec<&str> = picked.iter().map(String::as_str).collect();
                // Simple or Advanced, for all of the person's own Devices
                // (#197).
                let advanced = self.welcome.as_ref().is_some_and(|w| w.advanced);
                PersonSettings::new(&self.store).set_advanced(advanced)?;
                Places::new(&self.store).plant_starter_set(&picked)?;
                self.welcomed()?;
            }
            WelcomeAction::AddDevice => {
                if let Some(welcome) = &mut self.welcome {
                    welcome.adding = true;
                }
                self.notice = None;
            }
            WelcomeAction::Synced => self.welcomed()?,
            WelcomeAction::Back => {
                // A join or a rebuild under way finishes first: what it
                // brings is kept.
                if self.sync.joining() || self.vault.running() {
                    return Ok(());
                }
                // Left after a sync went through: on, as with Continue.
                if self.welcome.as_ref().is_some_and(|w| w.adding) && self.sync.synced() {
                    return self.welcomed();
                }
                if let Some(welcome) = &mut self.welcome {
                    *welcome = Welcome::default();
                }
            }
            WelcomeAction::Pick => {
                if let Some(path) = (self.backup_opener)(t.restore_open_title()) {
                    match backup::read_header(&path) {
                        Ok(Some(header)) => {
                            if let Some(welcome) = &mut self.welcome {
                                welcome.file = Some((path, header));
                            }
                            self.notice = None;
                        }
                        Err(oldbrainfix_core::Error::Backup(backup::Problem::NeedsUpdate)) => self
                            .announce_failure(
                                t.restore_not_done(),
                                t.restore_not_done_title(),
                                (t.restore_needs_update(), t.update_open_again_fix()),
                                "backup: a Backup of a later format".into(),
                            ),
                        _ => self.announce_failure(
                            t.restore_not_done(),
                            t.restore_not_done_title(),
                            (t.restore_not_a_backup(), t.restore_pick_fix()),
                            "backup: no Backup header in the file picked".into(),
                        ),
                    }
                }
            }
            WelcomeAction::Rebuild => {
                if self.vault.running() {
                    return Ok(());
                }
                if let Some(folder) = (self.vault_picker)(t.vault_rebuild_pick_title()) {
                    let root = t.import_area_name(&folder_name(&folder));
                    self.vault.rebuild(self.store.clone(), folder, root);
                    if let Some(welcome) = &mut self.welcome {
                        welcome.rebuilding = Some((0, 0));
                    }
                    self.notice = None;
                }
            }
            WelcomeAction::Restore => {
                let Some(welcome) = &self.welcome else {
                    return Ok(());
                };
                let key = match backup_view::unlock(&t, welcome) {
                    Ok(key) => key,
                    // Said red under the field.
                    Err(backup_view::Unlocked::NotAKey) => {
                        if let Some(welcome) = &mut self.welcome {
                            welcome.code_invalid = true;
                        }
                        return Ok(());
                    }
                    Err(backup_view::Unlocked::Failed(cause, fix, details)) => {
                        self.announce_failure(
                            t.restore_not_done(),
                            t.restore_not_done_title(),
                            (cause, fix),
                            details,
                        );
                        return Ok(());
                    }
                };
                let Some((path, _)) = &welcome.file else {
                    return Ok(());
                };
                match backup::restore(&self.store, path, &key) {
                    Ok(restored) => {
                        self.welcomed()?;
                        self.announce_done(
                            t.restore_done_short(),
                            t.restore_done(restored.entries as i64),
                        );
                        self.restored_settings();
                    }
                    Err(e) => {
                        let (cause, fix) = backup_view::restore_failure(&t, &e);
                        self.announce_failure(
                            t.restore_not_done(),
                            t.restore_not_done_title(),
                            (cause, fix),
                            format!("restore: {e}"),
                        );
                    }
                }
            }
        }
        Ok(())
    }

    /// Shows the Device settings a Backup brought (obf-1098) where the
    /// window keeps them: the playback speed, the theme, the text size,
    /// Fat fingers, Show tips and the speech model to offer. The others
    /// are read where they are used. One that cannot be read stays as
    /// it was.
    fn restored_settings(&mut self) {
        let settings = DeviceSettings::new(&self.store);
        if let Ok(speed) = settings.playback_speed() {
            self.speed = speed;
            if let Some(player) = &mut self.player {
                player.set_speed(speed);
            }
        }
        if let Ok(theme) = settings.theme() {
            self.theme = theme;
            self.theme_shown = false;
        }
        if let Ok(size) = settings.text_size() {
            self.text_size = size;
        }
        self.zoom_shown = false;
        if self.spotlights.on()
            && let Ok(on) = settings.tips_on()
        {
            self.spotlights.set_tips(on);
        }
        if let Ok(offer) = settings.speech_model_offer() {
            self.speech_offer = offer;
        }
    }

    /// Keeps the choice of speech model as the model came to (obf-1098),
    /// once it is checked or fetched: the one downloaded or taken from a
    /// file, none once there is none. The offer of a restored Backup's
    /// model goes once that model is in use. Not in a Note window, which
    /// only borrows the model.
    fn keep_speech_choice(&mut self) {
        let Some(model) = &self.speech else {
            return;
        };
        if self.alone.is_some() {
            return;
        }
        let settings = DeviceSettings::new(&self.store);
        let kept = match self.speech_kept.take() {
            Some(kept) => kept,
            None => match settings.speech_model() {
                Ok(kept) => kept,
                Err(e) => {
                    eprintln!("speech model: {e}");
                    None
                }
            },
        };
        let Some(now) = model.choice(kept.as_ref()) else {
            self.speech_kept = Some(kept);
            return;
        };
        if now != kept
            && let Err(e) = settings.set_speech_model(now.as_ref())
        {
            // Not tried again each frame; the next start does.
            eprintln!("speech model: {e}");
        }
        if let (Some(offer), Some(used)) = (&self.speech_offer, &now)
            && offer.name == used.name
        {
            if let Err(e) = settings.drop_speech_model_offer() {
                eprintln!("speech model offer: {e}");
            }
            self.speech_offer = None;
        }
        self.speech_kept = Some(now);
    }

    /// The speech model offered at the top (obf-1098): once the first
    /// start's view is answered, in the main window, while the model is
    /// neither checked nor fetched, so a download that failed offers it
    /// again.
    fn speech_offer_shows(&self) -> Option<SpeechModelSource> {
        let offer = self.speech_offer.as_ref()?;
        let model = self.speech.as_ref()?;
        let idle = matches!(model.status(), SpeechStatus::Missing | SpeechStatus::Ready);
        (idle && self.welcome.is_none() && self.alone.is_none()).then_some(offer.source)
    }

    /// Does what the speech model's offer at the top asked (obf-1098):
    /// downloads the model, or takes its file again, from the dialog the
    /// Settings' "Use a file of my own" opens; the offer stays until the
    /// model is in use, also when the dialog is left. Not now turns it
    /// down for good: the Settings still fetch any model.
    fn speech_offer_action(&mut self, take: bool) -> oldbrainfix_core::Result<()> {
        let Some(offer) = self.speech_offer.clone() else {
            return Ok(());
        };
        if !take {
            self.speech_offer = None;
            return DeviceSettings::new(&self.store).drop_speech_model_offer();
        }
        let Some(model) = &self.speech else {
            return Ok(());
        };
        match offer.source {
            SpeechModelSource::Download => {
                if let Some(chosen) = speech::named(&offer.name) {
                    model.download(chosen);
                }
            }
            SpeechModelSource::File => {
                if let Some(path) = (self.model_picker)(self.t.speech_model_pick()) {
                    model.take_file(&path);
                }
            }
        }
        Ok(())
    }

    /// Announces how a vault job ended: an export written or not; a
    /// rebuild answers the first start, or goes back to its choices
    /// saying why.
    fn vault_done(&mut self, done: VaultDone) {
        let t = self.t;
        match done {
            VaultDone::Exported(Ok(exported)) => {
                self.announce_done(
                    t.vault_written(),
                    vault_view::exported_details(&t, &exported),
                );
            }
            VaultDone::Exported(Err(e)) => self.announce_failure(
                t.vault_not_written(),
                t.vault_not_written_title(),
                (t.vault_not_written_cause(), t.nothing_lost_fix()),
                format!("vault: {e}"),
            ),
            VaultDone::Rebuilt(Ok(rebuilt)) => {
                if let Err(e) = self.welcomed() {
                    eprintln!("first start: {e}");
                }
                self.announce_done(t.vault_rebuilt(), vault_view::rebuilt_details(&t, &rebuilt));
                self.refresh();
                if let Some(wake) = &self.wake {
                    drop(wake.send(Event::Wake));
                }
            }
            VaultDone::Rebuilt(Err(e)) => {
                if let Some(welcome) = &mut self.welcome {
                    welcome.rebuilding = None;
                }
                let (cause, fix) = vault_view::rebuild_failure(&t, &e);
                self.announce_failure(
                    t.vault_not_rebuilt(),
                    t.vault_not_rebuilt_title(),
                    (cause, fix),
                    format!("vault: {e}"),
                );
            }
        }
    }

    /// The first start's view is answered: new with the Starter Set
    /// planted, restored or synced. Only
    /// now is the own Profile made with this computer's defaults, so a
    /// Device being added takes the one its other Devices hold (ADR
    /// 0017); one that came with a restore or a sync stays as it is.
    fn welcomed(&mut self) -> oldbrainfix_core::Result<()> {
        backup_view::restore_answered(&self.store)?;
        self.welcome = None;
        (self.profile_defaults)(&self.store)?;
        // Right after the first start: no What's new (#180), only the
        // version recorded. When that fails the start goes on, as at
        // launch.
        if let Err(e) = self.help_due(true) {
            eprintln!("help Notes: {e}");
        }
        Ok(())
    }

    /// Makes the help Notes of `version` (#180) from now on: at once
    /// when the first start's view is not due, which is then an ordinary
    /// start and owes an update's What's new, else once it is answered.
    pub fn set_help(&mut self, version: &str) -> oldbrainfix_core::Result<()> {
        self.help_version = Some(version.to_string());
        if self.welcoming() {
            return Ok(());
        }
        self.help_due(false)
    }

    /// Switches the tips explaining each screen (obf-1043) on or off. On,
    /// it first counts, once per Device, the tips of what an earlier
    /// version had as shown, unless the first start is due; so it comes
    /// before the first start's view is answered and before the help
    /// Notes.
    pub fn set_spotlights(&mut self, on: bool) -> oldbrainfix_core::Result<()> {
        self.spotlights.set_on(on);
        if on {
            spotlight::seed(&self.store, self.welcoming())?;
            // Whether this Device shows them at all (obf-1060).
            self.spotlights
                .set_tips(DeviceSettings::new(&self.store).tips_on()?);
        }
        Ok(())
    }

    /// The id of the tip showing (obf-1043).
    pub fn spotlight_showing(&self) -> Option<&'static str> {
        self.spotlights.showing()
    }

    /// The screen whose tips may show now (obf-1043), by its manifest id,
    /// with what makes a new visit of it: the dialog on top or the list
    /// shown, none while a dialog, menu, photo or table lies over it, the
    /// window is hidden or the first start's view shows.
    fn spotlight_screen(&self, ctx: &egui::Context) -> Option<(&'static str, String)> {
        if !self.spotlights.on()
            || self.welcome.is_some()
            || self.alone.is_some()
            || self.dialog.is_some()
            || self.badge.is_some()
            || self.viewer.is_some()
            || self.table.is_some()
            || egui::Popup::is_any_open(ctx)
            || !self.drawn(ctx)
        {
            return None;
        }
        let screen = match self.top_dialog() {
            Some(TopDialog::Editor) if self.editor.is_some() => spotlight::ROUTINE_EDITOR,
            Some(TopDialog::QuickNote) => spotlight::QUICK_NOTE,
            Some(TopDialog::Page) if self.page() == Some(Page::Settings) => spotlight::SETTINGS,
            Some(TopDialog::Note) => {
                let note = self.view.detail.as_ref().map(|(p, _)| p.note.id.clone());
                return Some((spotlight::NOTE_DIALOG, note.unwrap_or_default()));
            }
            Some(_) => return None,
            None => match &self.selection {
                Selection::Agenda => spotlight::AGENDA,
                Selection::Unsorted => spotlight::UNSORTED,
                Selection::Place(id) => return Some((spotlight::LIST, id.clone())),
                _ => return None,
            },
        };
        Some((screen, String::new()))
    }

    /// The help Notes due now, once the own Profile exists; `fresh` right
    /// after the first start.
    fn help_due(&self, fresh: bool) -> oldbrainfix_core::Result<()> {
        if let Some(version) = &self.help_version {
            help_notes::make_due(&self.store, &self.t, version, fresh)?;
        }
        Ok(())
    }

