    /// Announces that no Profile card can be made yet, as before this
    /// Device synced with another of the user's; the click opens why.
    fn announce_card_not_made(&mut self) {
        let t = self.t;
        self.announce_failure(
            t.profile_card_not_made(),
            t.profile_card_not_made_title(),
            (t.profile_card_not_yet_cause(), t.profile_card_not_yet()),
            "profile card: this Device is not bound to the Profile yet".into(),
        );
    }

    /// The dialog behind the notice shown, if it was announced with one.
    fn dialog_behind_notice(&self) -> Option<&Dialog> {
        match (&self.notice, &self.notice_dialog) {
            (Some(notice), Some((said, dialog))) if notice == said => Some(dialog),
            _ => None,
        }
    }

    /// Saves a bundle for the paired Device `device`, or of everything,
    /// where the user says; nothing asked when there is nothing new.
    fn save_bundle(&mut self, device: Option<String>) -> oldbrainfix_core::Result<()> {
        let since = match &device {
            Some(id) => self.store.held_by(id)?,
            None => Default::default(),
        };
        let t = self.t;
        if self.store.entries_since(&since)?.is_empty() {
            self.notice = Some(t.bundle_nothing_to_send().to_string());
            return Ok(());
        }
        let day = (self.wall)(self.store.now()).date();
        let Some(mut path) =
            (self.bundle_saver)(self.t.bundle_save_title(), &bundle::file_name(day))
        else {
            return Ok(());
        };
        if path.extension().is_none_or(|e| e != bundle::EXTENSION) {
            path.set_extension(bundle::EXTENSION);
        }
        match bundle::write_bundle_now(&self.store, &path, device.as_deref()) {
            Ok(Some(_)) => self.notice = Some(t.bundle_saved().to_string()),
            Ok(None) => self.notice = Some(t.bundle_nothing_to_send().to_string()),
            Err(e) => self.announce_failure(
                t.bundle_not_saved(),
                t.bundle_not_saved_title(),
                (t.bundle_not_written_cause(), t.nothing_lost_fix()),
                format!("bundle: {e}"),
            ),
        }
        Ok(())
    }

    /// Opens the file at `path`: a Pack (#165) shows its tree, a Profile
    /// card file (#144) opens the person's Profile or says why nobody was
    /// added, a Sent Item shows its preview, a stranger's held and hidden
    /// until "Show" (#91); anything else is imported as a bundle. A Pack
    /// and a card file are JSON as a Sent Item is, so they are asked for
    /// first, a Pack read whole, as it has no size limit: one larger
    /// than a Sent Item or a card file can be read off the window's
    /// thread, and every Pack opened there.
    fn open_file(&mut self, path: &std::path::Path) {
        // A Markdown file shows in a viewer of its own (obf-1056).
        if oldbrainfix_core::obsidian::is_markdown(&path.to_string_lossy()) {
            self.open_viewer(path.to_path_buf());
            return;
        }
        let most = sent::MAX_BYTES.max(cards::MAX_FILE_BYTES) as u64;
        match pack_file(path, most) {
            PackFile::Bytes(bytes) => {
                self.open_pack(bytes, path.to_path_buf());
                return;
            }
            PackFile::Large => {
                let path = path.to_path_buf();
                self.pack_aside(PackWork::Opening, move |store| {
                    let opened = read_pack_file(&path).map(|bytes| store.open_pack(&bytes));
                    PackDid::Opened(opened, path)
                });
                return;
            }
            PackFile::No => {}
        }
        let small = std::fs::metadata(path).is_ok_and(|m| m.len() <= most);
        let bytes = if small {
            std::fs::read(path).unwrap_or_default()
        } else {
            Vec::new()
        };
        if cards::looks_like_profile_card(&bytes) {
            let shown = self
                .store
                .open_profile_card_file(&bytes)
                .and_then(|opened| self.card_opened(opened));
            if let Err(e) = shown {
                self.announce_card_not_added(CardTaken::Unreadable, e.to_string());
            }
            return;
        }
        if !sent::looks_like_sent_item(&bytes) {
            self.import_bundle(path);
            return;
        }
        match self.store.receive_sent_item(&bytes) {
            Ok(Ok(Received::Opened(opened))) => self.preview(opened, None),
            Ok(Ok(Received::Held(held))) => {
                self.dialog = Some(Dialog::HeldSentItem {
                    held,
                    blocking: None,
                });
            }
            Ok(Err(e)) => self.announce_not_taken(e),
            Err(e) => {
                let t = self.t;
                self.announce_failure(
                    t.sent_item_not_taken(),
                    t.sent_item_not_taken_title(),
                    (t.sent_item_unreadable(), t.sent_item_ask_again_fix()),
                    e.to_string(),
                );
            }
        }
    }

    /// Opens the Pack `bytes` of the file at `path` (#165) off the
    /// window's thread.
    fn open_pack(&mut self, bytes: Vec<u8>, path: std::path::PathBuf) {
        self.pack_aside(PackWork::Opening, move |store| {
            PackDid::Opened(Some(store.open_pack(&bytes)), path)
        });
    }

    /// Runs `work` on a Pack on a thread of its own, on a connection the
    /// Agenda's opener hands it (#207), its result taken in by
    /// [`App::pack_arrived`]; without the opener, the window runs it
    /// itself. `kind` says what it does: while it opens a Pack, the line
    /// under the menu bar shows.
    fn pack_aside(
        &mut self,
        kind: PackWork,
        work: impl FnOnce(&Store) -> PackDid + Send + 'static,
    ) {
        let Some(open) = self.agenda_reads.as_ref().map(|reads| reads.open.clone()) else {
            let done = work(&self.store);
            self.pack_done(done);
            return;
        };
        let (sent, arrives) = std::sync::mpsc::channel();
        std::thread::spawn(move || {
            let store = open();
            let before = store.current_seq().ok();
            let done = work(&store);
            let wrote = before.is_some_and(|before| store.current_seq().ok() != Some(before));
            drop(sent.send(PackDone { done, wrote }));
        });
        self.pack_work.push(PackRunning {
            arrives,
            kind,
            since: std::time::Instant::now(),
            dropped: false,
        });
    }

    /// Whether a Pack is being opened off the window's thread.
    fn pack_opening(&self) -> bool {
        self.pack_work
            .iter()
            .any(|w| w.kind == PackWork::Opening && !w.dropped)
    }

    /// Whether a Pack is being saved off the window's thread.
    fn pack_saving(&self) -> bool {
        self.pack_work.iter().any(|w| w.kind == PackWork::Saving)
    }

    /// Every job running beside the window, as the page Running lists
    /// them (obf-1078), read from where each runs.
    fn jobs(&self) -> Vec<Job> {
        let t = self.t;
        let mut jobs = Vec::new();
        if let Some(syncing) = self.syncing.as_ref().filter(|s| s.running()) {
            jobs.push(Job {
                id: JobId::Sync,
                what: t.running_sync().to_string(),
                far: None,
                since: syncing.since(),
                abort: if syncing.paused() {
                    Abort::Stopping
                } else {
                    Abort::Offered
                },
                abort_does: Some(t.running_sync_abort().to_string()),
            });
        }
        if let Some(kind) = self.import.kind() {
            jobs.push(Job {
                id: JobId::Import,
                what: self.import_what(kind),
                far: self
                    .import
                    .progress()
                    .map(|(done, of)| t.import_written(done as i64, of as i64)),
                since: self.import.since(),
                abort: if self.import.aborting() {
                    Abort::Stopping
                } else {
                    Abort::Offered
                },
                abort_does: Some(t.running_import_abort().to_string()),
            });
        }
        for (enricher, kind) in self.enrichers() {
            let Some((since, done, of)) = enricher.busy() else {
                continue;
            };
            jobs.push(Job {
                id: JobId::Reading(kind),
                what: reading_what(&t, kind).to_string(),
                far: Some(t.running_read(done as i64, of as i64)),
                since: Some(since),
                abort: if enricher.stopped() {
                    Abort::Stopping
                } else {
                    Abort::Offered
                },
                abort_does: Some(t.running_read_abort().to_string()),
            });
        }
        if let Some(model) = &self.speech
            && let speech::Status::Fetching {
                downloading,
                received,
                total,
            } = model.status()
        {
            let mb = |bytes: u64| format!("{:.0}", bytes as f64 / 1_000_000.0);
            let size = model
                .chosen()
                .unwrap_or(oldbrainfix_whisper::model::WhisperModel::Base)
                .megabytes();
            let total = total.map_or_else(|| size.to_string(), mb);
            jobs.push(Job {
                id: JobId::SpeechModel,
                what: if downloading {
                    t.running_model_download()
                } else {
                    t.running_model_copy()
                }
                .to_string(),
                far: downloading.then(|| t.speech_model_downloading(&mb(received), &total)),
                since: model.since(),
                abort: if model.cancelling() {
                    Abort::Stopping
                } else {
                    Abort::Offered
                },
                abort_does: None,
            });
        }
        for deleting in self.deletions.list() {
            jobs.push(Job {
                what: t.running_area_deletion(&self.area_called(&deleting.area_id)),
                far: deleting
                    .moved
                    .map(|(moved, of)| t.area_deleting(moved as i64, of as i64)),
                since: Some(deleting.since),
                abort: if deleting.aborting {
                    Abort::Stopping
                } else {
                    Abort::Offered
                },
                abort_does: Some(t.running_area_abort().to_string()),
                id: JobId::AreaDeletion(deleting.area_id),
            });
        }
        // One transaction, which deletes all of it or nothing: no Abort.
        if let Some(((notes, routines), since)) = self.trash_emptying.under_way() {
            jobs.push(Job {
                id: JobId::TrashEmptying,
                what: t.desk_trash_emptying().to_string(),
                far: Some(trash_counts(&t, notes, routines)),
                since: Some(since),
                abort: Abort::No,
                abort_does: None,
            });
        }
        for opening in self
            .pack_work
            .iter()
            .filter(|w| w.kind == PackWork::Opening && !w.dropped)
        {
            jobs.push(Job {
                id: JobId::PackOpening,
                what: t.pack_opening().to_string(),
                far: None,
                since: Some(opening.since),
                abort: Abort::Offered,
                abort_does: Some(t.running_pack_abort().to_string()),
            });
        }
        // The window waits for it: no Abort.
        if self.agenda_waiting() {
            jobs.push(Job {
                id: JobId::AgendaRead,
                what: t.agenda_reading().to_string(),
                far: None,
                since: None,
                abort: Abort::No,
                abort_does: None,
            });
        }
        jobs
    }

    /// The jobs Abort paused once what was under way ended (obf-1078),
    /// read from where they pause, each with Go on: the automatic syncs,
    /// and the reading of Transcripts, Photo Texts and Attachment Texts.
    fn paused_jobs(&self) -> Vec<Ended> {
        let t = self.t;
        let mut paused = Vec::new();
        if self
            .syncing
            .as_ref()
            .is_some_and(|s| s.paused() && !s.running())
        {
            paused.push(Ended {
                id: JobId::Sync,
                what: t.running_sync().to_string(),
                said: t.running_sync_paused().to_string(),
                goes_on: true,
            });
        }
        for (enricher, kind) in self.enrichers() {
            if enricher.stopped() && enricher.busy().is_none() {
                paused.push(Ended {
                    id: JobId::Reading(kind),
                    what: reading_what(&t, kind).to_string(),
                    said: t.running_read_stopped().to_string(),
                    goes_on: true,
                });
            }
        }
        paused
    }

    /// The threads reading Transcripts, Photo Texts and Attachment Texts
    /// there are, each with what it reads.
    fn enrichers(&self) -> Vec<(&Enricher, enrich::Kind)> {
        [
            (&self.transcriber, enrich::Kind::Transcripts),
            (&self.reader, enrich::Kind::PhotoTexts),
            (&self.files_reader, enrich::Kind::AttachmentTexts),
        ]
        .into_iter()
        .filter_map(|(enricher, kind)| enricher.as_ref().map(|e| (e, kind)))
        .collect()
    }

    /// What the Import `kind` is, as the page Running names it.
    fn import_what(&self, kind: &Importing) -> String {
        match kind {
            Importing::Folder(name) | Importing::Markdown(name) => self.t.running_import(name),
            Importing::Keep => self.t.running_import_keep().to_string(),
        }
    }

    /// The name the Area `area_id` shows under in the sidebar, empty
    /// once it is gone.
    fn area_called(&self, area_id: &str) -> String {
        self.view
            .areas
            .iter()
            .find(|(area, _)| area.id == area_id)
            .map(|(area, _)| area_name(&self.t, area))
            .unwrap_or_default()
    }

    /// "Since 14:32": when a job started at `at`, as this computer's
    /// clock shows it.
    fn since_text(&self, at: std::time::Instant) -> String {
        let ago = chrono::Duration::from_std(at.elapsed()).unwrap_or_default();
        let then = (self.wall)(self.store.now() - ago);
        self.t.running_since(&then.format("%H:%M").to_string())
    }

    /// Does what was clicked on the page Running (obf-1078): Abort stops
    /// a job at its next safe point, Go on starts a paused one again.
    fn running_act(&mut self, act: running::Act) {
        let t = self.t;
        match act {
            // Listed as paused once the round under way ended.
            running::Act::Abort(JobId::Sync) => {
                if let Some(syncing) = &self.syncing {
                    syncing.pause();
                }
            }
            // Said once it has stopped, with how far it came.
            running::Act::Abort(JobId::Import) => self.import.abort(),
            running::Act::Abort(JobId::AreaDeletion(id)) => self.deletions.abort(&id),
            running::Act::Abort(JobId::Reading(kind)) => {
                if let Some((enricher, _)) = self.enrichers().into_iter().find(|(_, k)| *k == kind)
                {
                    enricher.stop();
                }
            }
            running::Act::Abort(JobId::SpeechModel) => {
                if let Some(model) = &self.speech {
                    let downloading = matches!(
                        model.status(),
                        speech::Status::Fetching {
                            downloading: true,
                            ..
                        }
                    );
                    model.cancel();
                    self.stopped_jobs.push(Ended {
                        id: JobId::SpeechModel,
                        what: if downloading {
                            t.running_model_download()
                        } else {
                            t.running_model_copy()
                        }
                        .to_string(),
                        said: t.running_model_stopped().to_string(),
                        goes_on: false,
                    });
                }
            }
            running::Act::Abort(JobId::PackOpening) => {
                for opening in self
                    .pack_work
                    .iter_mut()
                    .filter(|w| w.kind == PackWork::Opening)
                {
                    opening.dropped = true;
                }
                self.stopped_jobs.push(Ended {
                    id: JobId::PackOpening,
                    what: t.pack_opening().to_string(),
                    said: t.running_pack_stopped().to_string(),
                    goes_on: false,
                });
            }
            running::Act::Abort(JobId::AgendaRead | JobId::TrashEmptying) => {}
            running::Act::GoOn(JobId::Sync) => self.sync_goes_on(),
            running::Act::GoOn(JobId::Reading(kind)) => {
                if let Some((enricher, _)) = self.enrichers().into_iter().find(|(_, k)| *k == kind)
                {
                    enricher.go_on();
                }
            }
            // Only those two pause.
            running::Act::GoOn(_) => {}
        }
    }

    /// Lists the Import `what` Abort stopped once it ended with `done` of
    /// `of` Notes written (obf-1078), and says so at the top in place of
    /// "Import finished.", what it made behind the click.
    fn import_stopped(&mut self, what: String, (done, of): (usize, usize)) {
        let t = self.t;
        let said = t.running_import_stopped(done as i64, of as i64);
        self.stopped_jobs.push(Ended {
            id: JobId::Import,
            what,
            said: said.clone(),
            goes_on: false,
        });
        match &mut self.notice_dialog {
            Some((notice, Dialog::Imported { details, .. })) => {
                *notice = t.import_stopped().to_string();
                *details = format!("{said}\n\n{details}");
                self.notice = Some(t.import_stopped().to_string());
            }
            // Stopped before its first Note: no Area to open.
            _ => self.announce_done(t.import_stopped(), said),
        }
    }

    /// Takes in what the Pack threads did once it is in; the window
    /// looks again shortly while one runs.
    fn pack_arrived(&mut self, ctx: &egui::Context) {
        if self.pack_work.is_empty() {
            return;
        }
        let mut arrived = Vec::new();
        self.pack_work
            .retain(|running| match running.arrives.try_recv() {
                Ok(done) => {
                    arrived.push((done, running.dropped));
                    false
                }
                Err(std::sync::mpsc::TryRecvError::Empty) => true,
                Err(std::sync::mpsc::TryRecvError::Disconnected) => false,
            });
        if !self.pack_work.is_empty() {
            ctx.request_repaint_after(std::time::Duration::from_millis(30));
        }
        for (PackDone { done, wrote }, dropped) in arrived {
            if wrote {
                self.store.changed_elsewhere();
            }
            if !dropped {
                self.pack_done(done);
            }
        }
    }

    /// Shows what a Pack's work did.
    fn pack_done(&mut self, done: PackDid) {
        match done {
            PackDid::Opened(Some(opened), _) => self.pack_opened(opened),
            // JSON larger than a Sent Item or a card, and no Pack.
            PackDid::Opened(None, path) => self.import_bundle(&path),
            PackDid::Saved(saved, false) => self.pack_saved(saved),
            PackDid::Saved(saved, true) => self.feedback_saved(saved),
            PackDid::BackupOpened(path, opened) => self.backup_notes_opened(&path, opened),
            PackDid::BackupAdded(added) => self.backup_notes_added(added),
        }
    }

    /// The Pack opened (#165): its tree, everything ticked, "Claim as
    /// mine" ticked; or why it did not open, behind the click.
    fn pack_opened(
        &mut self,
        opened: oldbrainfix_core::Result<std::result::Result<OpenedPack, PackError>>,
    ) {
        let t = self.t;
        let (why, details) = match opened {
            Ok(Ok(opened)) => {
                let ticks = opened.pack.all_keys();
                self.dialog = Some(Dialog::PackOpened {
                    opened: Box::new(opened),
                    ticks,
                    claim: true,
                    worked: pack_view::Worked::default(),
                });
                return;
            }
            Ok(Err(e)) => {
                let why = match e {
                    PackError::NeedsUpdate => {
                        (t.sent_item_needs_update(), t.update_open_again_fix())
                    }
                    PackError::FromBlocked => (t.pack_from_blocked(), t.blocked_fix()),
                    PackError::NotAPack => (t.pack_unreadable(), t.pack_ask_again_fix()),
                };
                (why, format!("pack: {}", e.name()))
            }
            Err(e) => (
                (t.pack_unreadable(), t.pack_ask_again_fix()),
                format!("pack: {e}"),
            ),
        };
        self.announce_failure(t.pack_not_opened(), t.pack_not_opened_title(), why, details);
    }

    /// Export as Pack… on the Area, Topic or Note `from` (#165): the tree
    /// of what it holds, ticked as an export starts. The desktop has no
    /// Area Locks, so no Area is closed.
    fn export_pack(&mut self, from: &str) -> oldbrainfix_core::Result<()> {
        let pack = self.store.pack_of(from, &HashSet::new())?;
        let ticks = pack.export_ticks();
        self.dialog = Some(Dialog::PackExport {
            pack: Box::new(pack),
            ticks,
            profile: false,
            worked: pack_view::Worked::default(),
        });
        Ok(())
    }

    /// What was asked in a Pack's dialog (#165).
    fn pack_action(&mut self, asked: PackAsk) -> oldbrainfix_core::Result<()> {
        match asked {
            PackAsk::Cancel => self.dialog = None,
            PackAsk::Save => self.save_pack(),
            PackAsk::Add => self.add_pack()?,
            PackAsk::AddPerson => self.add_pack_person()?,
        }
        Ok(())
    }

    /// What was asked on the Send feedback page (#214): Mail opens the
    /// mail link with the preview's text; the saves write it, or the
    /// Notes ticked as a Pack, where the user says and say nothing, a
    /// failure is announced; the first tick of Notes makes the Pack of
    /// everything, nothing ticked. The desktop has no Area Locks.
    fn feedback_action(&mut self, asked: FeedbackAsk) -> oldbrainfix_core::Result<()> {
        let t = self.t;
        let body = self.feedback.body(&self.feedback_facts);
        let day = Day::today(self.store.now(), &*self.wall);
        let written = match asked {
            FeedbackAsk::Notes(on) => {
                if on && self.feedback.pack.is_none() {
                    // The Areas in the person's own order (#280).
                    let shown = |a: &Area| area_name(&t, a);
                    self.feedback.pack = Some(self.store.pack_of_all_by(&HashSet::new(), shown)?);
                }
                self.feedback.notes = on;
                return Ok(());
            }
            FeedbackAsk::Mail => {
                self.open_url = Some(feedback_view::mail_url(&body));
                return Ok(());
            }
            FeedbackAsk::SaveFile => {
                let name = feedback_view::file_name(&day.to_string());
                let Some(path) = (self.feedback_saver)(t.feedback_save_title(), &name) else {
                    return Ok(());
                };
                std::fs::write(&path, body).map_err(|e| e.to_string())
            }
            FeedbackAsk::SavePack => {
                let Some(pack) = self.feedback.picked() else {
                    return Ok(());
                };
                let name = packs::file_name(day);
                let Some(mut path) = (self.pack_saver)(t.pack_save_title(), &name) else {
                    return Ok(());
                };
                if path.extension().is_none_or(|e| e != packs::EXTENSION) {
                    path.set_extension(packs::EXTENSION);
                }
                let (pack, ticks) = (pack.clone(), self.feedback.ticks.clone());
                self.pack_aside(PackWork::Saving, move |store| {
                    PackDid::Saved(write_pack_file(store, &pack, &ticks, false, &path), true)
                });
                return Ok(());
            }
        };
        self.feedback_saved(written);
        Ok(())
    }

    /// A save of Send feedback done: a failure is announced.
    fn feedback_saved(&mut self, written: std::result::Result<(), String>) {
        let t = self.t;
        if let Err(e) = written {
            self.announce_failure(
                t.feedback_not_saved(),
                t.feedback_not_saved_title(),
                (t.feedback_file_cause(), t.nothing_lost_fix()),
                format!("feedback: {e}"),
            );
        }
    }

    /// Save… in the export: the Pack as ticked, saved where the user
    /// says off the window's thread, and the dialog closed; saved says
    /// nothing, a failure is announced and the dialog stays.
    fn save_pack(&mut self) {
        let Some(Dialog::PackExport {
            pack,
            ticks,
            profile,
            ..
        }) = &self.dialog
        else {
            return;
        };
        let t = self.t;
        let day = Day::today(self.store.now(), &*self.wall);
        let Some(mut path) = (self.pack_saver)(t.pack_save_title(), &packs::file_name(day)) else {
            return;
        };
        if path.extension().is_none_or(|e| e != packs::EXTENSION) {
            path.set_extension(packs::EXTENSION);
        }
        let (pack, ticks, profile) = (pack.as_ref().clone(), ticks.clone(), *profile);
        self.pack_aside(PackWork::Saving, move |store| {
            PackDid::Saved(write_pack_file(store, &pack, &ticks, profile, &path), false)
        });
    }

    /// Save… in the export done: the dialog closed, or a failure
    /// announced and the dialog left as it is.
    fn pack_saved(&mut self, written: std::result::Result<(), String>) {
        let t = self.t;
        match written {
            Ok(()) => {
                if matches!(self.dialog, Some(Dialog::PackExport { .. })) {
                    self.dialog = None;
                }
            }
            Err(e) => self.announce_failure(
                t.pack_not_saved(),
                t.pack_not_saved_title(),
                (t.pack_not_written_cause(), t.nothing_lost_fix()),
                format!("pack: {e}"),
            ),
        }
    }

    /// Open a Backup… (#285): the file asked for in the Backups folder,
    /// then, for a Backup, its page over the Backups dialog, or alone
    /// from the File menu; a file that is none, or of a later format, is
    /// announced at the top, why behind the click.
    fn open_backup_notes(&mut self) -> oldbrainfix_core::Result<()> {
        let t = self.t;
        let folder = self
            .store
            .backup_folder()
            .ok()
            .flatten()
            .map(std::path::PathBuf::from);
        let Some(path) = (self.backup_notes_opener)(t.restore_open_title(), folder.as_deref())
        else {
            return Ok(());
        };
        let (cause, details) = match backup::read_header(&path) {
            Ok(Some(header)) => {
                self.backup_notes = Some(BackupNotes::new(path, header));
                return self.act(if self.page() == Some(Page::Backups) {
                    Action::PageInto(Page::BackupNotes)
                } else {
                    Action::OpenPage(Page::BackupNotes)
                });
            }
            Err(oldbrainfix_core::Error::Backup(backup::Problem::NeedsUpdate)) => (
                (t.restore_needs_update(), t.update_open_again_fix()),
                "backup: a Backup of a later format",
            ),
            _ => (
                (t.restore_not_a_backup(), t.restore_pick_fix()),
                "backup: no Backup header in the file picked",
            ),
        };
        self.announce_failure(
            t.backup_not_opened(),
            t.backup_not_opened_title(),
            cause,
            details.into(),
        );
        Ok(())
    }

    /// The page of a Backup opened is gone from the dialogs: so is what
    /// it held (#285).
    fn backup_notes_left(&mut self) {
        if !self.pages.contains(&Page::BackupNotes) {
            self.backup_notes = None;
        }
    }

    /// Open or Add on the page of a Backup opened (#285), off the
    /// window's thread: the passphrase's key is slow to make on purpose,
    /// and the whole file is read each time.
    fn backup_notes_action(&mut self, asked: BackupNotesAction) {
        let Some(state) = &mut self.backup_notes else {
            return;
        };
        if state.busy {
            return;
        }
        match asked {
            BackupNotesAction::Open => {
                let code = state.code.trim().to_string();
                // Said red under the field.
                if !code.is_empty() && oldbrainfix_core::recovery::decode_code(&code).is_none() {
                    state.code_invalid = true;
                    return;
                }
                let passphrase = state.passphrase.clone();
                let (path, header) = (state.path.clone(), state.header.clone());
                state.busy = true;
                let t = self.t;
                self.pack_aside(PackWork::Backup, move |store| {
                    let key = if code.is_empty() {
                        backup::unlock(&header, Some(&passphrase), None)
                    } else {
                        backup::unlock(&header, None, Some(&code))
                    };
                    // The desktop has no Area Locks: no Area is closed.
                    let opened = key.and_then(|key| {
                        key.map(|key| {
                            backup::open_notes(store, &path, &key, &HashSet::new(), |a| {
                                area_name(&t, a)
                            })
                        })
                        .transpose()
                    });
                    PackDid::BackupOpened(path, opened)
                });
            }
            BackupNotesAction::Add => {
                let Some(opened) = state.opened.as_deref().cloned() else {
                    return;
                };
                let ticks = state.ticks.clone();
                state.busy = true;
                let (t, wall) = (self.t, self.wall.clone());
                self.pack_aside(PackWork::Backup, move |store| {
                    PackDid::BackupAdded(backup::add_notes(
                        store,
                        &opened,
                        &ticks,
                        &*wall,
                        t.backup_suffix(),
                        t.backup_no_area(),
                    ))
                });
            }
        }
    }

    /// The Backup at `path` read (#285): its Notes on its page, or why it
    /// did not open, announced at the top of the page, which stays for
    /// another try. Closed meanwhile, or opened again, it shows nothing.
    fn backup_notes_opened(
        &mut self,
        path: &std::path::Path,
        opened: oldbrainfix_core::Result<Option<backup::OpenedBackup>>,
    ) {
        let t = self.t;
        let waiting = |s: &&mut BackupNotes| s.busy && s.opened.is_none() && s.path == path;
        let Some(state) = self.backup_notes.as_mut().filter(waiting) else {
            return;
        };
        let (cause, details) = match opened {
            Ok(Some(opened)) => {
                state.show(opened);
                return;
            }
            Ok(None) => (
                (t.restore_wrong(), t.restore_wrong_fix()),
                "backup: the passphrase or recovery key does not open it".to_string(),
            ),
            Err(e) => (backup_view::open_refusal(&t, &e), format!("backup: {e}")),
        };
        state.busy = false;
        self.announce_failure(
            t.backup_not_opened(),
            t.backup_not_opened_title(),
            cause,
            details,
        );
    }

    /// Add on a Backup opened done (#285): announced as a Pack's, its page
    /// closed back to the Backups dialog; a failure leaves the page open
    /// and the log as it was.
    fn backup_notes_added(&mut self, added: oldbrainfix_core::Result<oldbrainfix_core::PackAdded>) {
        let t = self.t;
        match added {
            Ok(added) => {
                // Not a page opened again meanwhile.
                let adding = self
                    .backup_notes
                    .as_ref()
                    .is_some_and(|s| s.busy && s.opened.is_some());
                if adding && self.page() == Some(Page::BackupNotes) {
                    self.pages.pop();
                }
                self.backup_notes_left();
                self.notice = Some(t.pack_added(added.notes as i64));
            }
            Err(e) => {
                if let Some(state) = &mut self.backup_notes {
                    state.busy = false;
                }
                let cause = if matches!(e, oldbrainfix_core::Error::Backup(_)) {
                    t.backup_add_damaged_cause()
                } else {
                    t.restore_failed_cause()
                };
                self.announce_failure(
                    t.backup_notes_not_added(),
                    t.backup_notes_not_added_title(),
                    (cause, t.backup_add_damaged_fix()),
                    format!("backup: {e}"),
                );
            }
        }
    }

    /// Add on a Pack opened: the ticked Notes into new Areas, the dialog
    /// closed, how many announced.
    fn add_pack(&mut self) -> oldbrainfix_core::Result<()> {
        let Some(Dialog::PackOpened {
            opened,
            ticks,
            claim,
            ..
        }) = &self.dialog
        else {
            return Ok(());
        };
        let t = self.t;
        let added = self.store.add_pack(
            opened,
            ticks,
            *claim,
            &*self.wall,
            t.pack_suffix(),
            t.pack_no_area(),
        )?;
        self.dialog = None;
        self.notice = Some(t.pack_added(added.notes as i64));
        Ok(())
    }

    /// "Add … to People" on a Pack opened: its Profile card taken in, the
    /// dialog kept with the person in People now; a card that adds
    /// nobody says why.
    fn add_pack_person(&mut self) -> oldbrainfix_core::Result<()> {
        let Some(Dialog::PackOpened { opened, .. }) = &self.dialog else {
            return Ok(());
        };
        let (Some(card), Some(from)) = (opened.pack.card.clone(), opened.from.clone()) else {
            return Ok(());
        };
        let taken = self.store.open_profile_card(&card, false)?.taken;
        if !matches!(
            taken,
            CardTaken::Added | CardTaken::Updated | CardTaken::Unchanged
        ) {
            self.announce_card_not_added(taken, format!("pack card: {}", taken.name()));
            return Ok(());
        }
        if let Some(Dialog::PackOpened { opened, .. }) = &mut self.dialog {
            opened.from_kept = true;
        }
        let t = self.t;
        let name = profile_view::display_name(&t, &from.name);
        self.notice = Some(t.pack_person_added(name));
        Ok(())
    }

    /// Shows what opening a Profile card file came to: the person's
    /// Profile when they are in People now, offering "Send yours back"
    /// when the card asks for it, else that nobody was added, why behind
    /// the click.
    fn card_opened(&mut self, opened: CardOpened) -> oldbrainfix_core::Result<()> {
        match (opened.taken, opened.id) {
            (CardTaken::Added | CardTaken::Updated | CardTaken::Unchanged, Some(id)) => {
                let back = if opened.offer_back {
                    SendBack::Offered
                } else {
                    SendBack::No
                };
                self.open_person(id, back)
            }
            (taken, _) => {
                self.announce_card_not_added(taken, format!("profile card: {}", taken.name()));
                Ok(())
            }
        }
    }

    /// Announces that a Profile card file added nobody, as `taken` says;
    /// the click opens why and what to do.
    fn announce_card_not_added(&mut self, taken: CardTaken, details: String) {
        let t = self.t;
        let why = match taken {
            CardTaken::Own => (t.card_own(), t.card_own_fix()),
            CardTaken::Blocked => (t.card_blocked(), t.blocked_fix()),
            CardTaken::Refused => (t.card_refused(), t.card_refused_fix()),
            CardTaken::NeedsUpdate => (t.sent_item_needs_update(), t.update_open_again_fix()),
            CardTaken::Added
            | CardTaken::Updated
            | CardTaken::Unchanged
            | CardTaken::Unreadable => (t.card_unreadable_cause(), t.card_ask_again_fix()),
        };
        self.announce_failure(t.card_not_added(), t.card_not_added_title(), why, details);
    }

    /// Saves the own Profile card as a file where the user says (#144),
    /// answering a card the user opened when `back`; true once saved.
    /// Nothing asked when no card can be made yet, which is announced.
    fn save_card(&mut self, back: bool) -> oldbrainfix_core::Result<bool> {
        let Some(bytes) = self.store.profile_card_file(back)? else {
            self.announce_card_not_made();
            return Ok(false);
        };
        let t = self.t;
        let name = OwnProfile::new(&self.store)
            .get()?
            .map(|p| p.name)
            .unwrap_or_default();
        let file = cards::file_name(profile_view::display_name(&t, &name));
        let Some(mut path) = (self.card_saver)(t.profile_card_save_title(), &file) else {
            return Ok(false);
        };
        if path.extension().is_none_or(|e| e != cards::EXTENSION) {
            path.set_extension(cards::EXTENSION);
        }
        match std::fs::write(&path, bytes) {
            Ok(()) => Ok(true),
            Err(e) => {
                self.announce_failure(
                    t.profile_card_not_sent(),
                    t.profile_card_not_sent_title(),
                    (t.profile_card_not_written_cause(), t.nothing_lost_fix()),
                    format!("profile card: {e}"),
                );
                Ok(false)
            }
        }
    }

    /// "Send yours back" on the person's Profile the dialog shows: the
    /// own card file, answering theirs; once saved, what to do with it
    /// shows instead.
    fn send_back(&mut self) -> oldbrainfix_core::Result<()> {
        if self.save_card(true)?
            && let Some(Dialog::Person { back, .. }) = &mut self.dialog
        {
            *back = SendBack::Saved;
        }
        Ok(())
    }

    /// Shows the preview of `opened`, held as the pending set `held` when
    /// a stranger's item was shown with "Show".
    fn preview(&mut self, opened: Box<Opened>, held: Option<String>) {
        let may_block = matches!(self.store.is_own_person(&opened.sender.id), Ok(false));
        self.dialog = Some(Dialog::SentItem {
            opened,
            compared: Compared::Not,
            may_block,
            blocking: None,
            held,
        });
    }

    /// "Show" on the stranger's Sent Item the dialog holds back: its
    /// preview, Compare codes included. Not remembered: opened again, it
    /// is hidden again.
    fn show_held(&mut self) -> oldbrainfix_core::Result<()> {
        let Some(Dialog::HeldSentItem { held, .. }) = &self.dialog else {
            return Ok(());
        };
        let id = held.id.clone();
        match self.store.show_held_sent_item(&id)? {
            Some(Ok(opened)) => self.preview(Box::new(opened), Some(id)),
            Some(Err(e)) => {
                self.dialog = None;
                self.announce_not_taken(e);
            }
            None => {
                self.dialog = None;
                self.notice = Some(self.t.sent_item_gone().to_string());
            }
        }
        Ok(())
    }

    /// Opens the stranger's Sent Item held as `id`, hidden until "Show".
    fn open_held(&mut self, id: &str) -> oldbrainfix_core::Result<()> {
        match self.store.held_sent_item(id)? {
            Some(held) => {
                self.dialog = Some(Dialog::HeldSentItem {
                    held,
                    blocking: None,
                });
            }
            None => self.notice = Some(self.t.sent_item_gone().to_string()),
        }
        Ok(())
    }

    /// Accepts the stranger's Sent Item held as `id`, shown or not,
    /// `verified` when the codes were compared, judged against the log
    /// now; announces what came of it. One gone meanwhile, or refused
    /// now, as from a person blocked since, is announced, not failed.
    fn accept_held(&mut self, id: &str, verified: bool) -> oldbrainfix_core::Result<()> {
        let t = self.t;
        let state = match self.store.show_held_sent_item(id)? {
            Some(Ok(opened)) => opened.state,
            Some(Err(e)) => {
                self.announce_not_taken(e);
                return Ok(());
            }
            None => {
                self.notice = Some(t.sent_item_gone().to_string());
                return Ok(());
            }
        };
        let said = match self.store.accept_held_sent_item(id, verified) {
            Ok(None) => t.sent_item_nothing_to_cancel(),
            Ok(Some(_)) => match state {
                SentItemState::Update => t.sent_item_applied(),
                SentItemState::Cancel => t.sent_item_trashed(),
                _ => t.sent_item_accepted(),
            },
            Err(oldbrainfix_core::Error::FromBlocked) => {
                self.announce_not_taken(OpenError::FromBlocked);
                return Ok(());
            }
            // Decided meanwhile.
            Err(oldbrainfix_core::Error::Invalid(_)) => t.sent_item_gone(),
            Err(e) => return Err(e),
        };
        self.notice = Some(said.to_string());
        Ok(())
    }

    /// Saves the Note of the send dialog as a Sent Item where the user
    /// says: encrypted to the person picked, else signed only; nothing
    /// while nobody is picked, the dialog stays.
    fn send_note(&mut self) -> oldbrainfix_core::Result<()> {
        if matches!(
            self.dialog,
            Some(Dialog::Send {
                picked: SendTo::Nobody,
                ..
            })
        ) {
            return Ok(());
        }
        let Some(Dialog::Send {
            note,
            recipients,
            picked,
            cancel,
            ..
        }) = self.dialog.take()
        else {
            return Ok(());
        };
        let day = (self.wall)(self.store.now()).date().format("%Y-%m-%d");
        let Some(mut path) =
            (self.item_saver)(self.t.send_save_title(), &sent::file_name(&day.to_string()))
        else {
            return Ok(());
        };
        if path.extension().is_none_or(|e| e != sent::EXTENSION) {
            path.set_extension(sent::EXTENSION);
        }
        let to = match picked {
            SendTo::Person(i) => recipients.get(i),
            SendTo::Nobody | SendTo::Anyone => None,
        };
        let bytes = match self.store.send_note(&note, to, cancel) {
            // Marked on another Device meanwhile.
            Err(oldbrainfix_core::Error::HiddenFromAi(marks)) => {
                self.ask_hidden(marks, None, Action::StartSend(note));
                return Ok(());
            }
            sent => sent?,
        };
        let t = self.t;
        match std::fs::write(&path, bytes) {
            Ok(()) => self.notice = Some(t.sent_saved().to_string()),
            Err(e) => self.announce_failure(
                t.sent_item_not_sent(),
                t.sent_item_not_sent_title(),
                (t.sent_item_not_written_cause(), t.nothing_lost_fix()),
                format!("sent item: {e}"),
            ),
        }
        Ok(())
    }

    /// The People an Area can go to from afar (#108): not blocked, with a
    /// Device whose key is known here; by the name the user sees.
    fn afar_people(&self) -> oldbrainfix_core::Result<Vec<AfarPerson>> {
        let mut out = Vec::new();
        for person in self.store.kept_people()? {
            if self.store.is_blocked(&person.id)?
                || self.store.offer_devices(&person.id)?.is_empty()
            {
                continue;
            }
            out.push(AfarPerson {
                shown: self.store.person_shown(&person.id)?,
                verified: self.store.person_verified(&person.id)?,
                id: person.id,
            });
        }
        let t = self.t;
        out.sort_by_cached_key(|p| profile_view::display_name(&t, &p.shown.name).to_lowercase());
        Ok(out)
    }

    /// Shares the Area of the dialog with the person picked from afar
    /// (#108): the shared folder first when changes travel by one and
    /// none is chosen, then where the offer is saved. Only then is
    /// anything written, so backing out of a dialog changes nothing. A
    /// Starter Set Area goes on under fresh ids, which the selection
    /// follows.
    fn share_afar(&mut self) -> oldbrainfix_core::Result<()> {
        let Some(Dialog::ShareAfar {
            area,
            role,
            person: Some(person),
            transport,
            ..
        }) = self.dialog.take()
        else {
            return Ok(());
        };
        let t = self.t;
        let transport = self.store.transport_with(&person)?.unwrap_or(transport);
        let mut folder = None;
        if transport == Transport::Folder && self.store.sync_folder()?.is_none() {
            let Some(path) = (self.folder_picker)(t.folder_pick_title()) else {
                return Ok(());
            };
            folder = Some(path);
        }
        let day = (self.wall)(self.store.now()).date();
        let Some(mut path) =
            (self.bundle_saver)(t.share_afar_save_title(), &bundle::file_name(day))
        else {
            return Ok(());
        };
        if path.extension().is_none_or(|e| e != bundle::EXTENSION) {
            path.set_extension(bundle::EXTENSION);
        }
        if let Some(folder) = &folder {
            self.store.choose_sync_folder(&folder.to_string_lossy())?;
        }
        let shared = match self.store.share_area_with(&area, &person, role, transport) {
            Ok(shared) => shared,
            Err(oldbrainfix_core::Error::HiddenFromAi(marks)) => {
                self.ask_hidden(marks, Some(&area), Action::Share(area.clone()));
                return Ok(());
            }
            Err(e) => {
                self.announce_afar_failed(&e);
                return Ok(());
            }
        };
        let (old, new) = (
            Selection::Place(area.clone()),
            Selection::Place(shared.clone()),
        );
        if self.selection == old {
            self.selection = new.clone();
        }
        self.nav.replace(&old, &new);
        match bundle::write_area_offer_now(&self.store, &path, &shared, &person) {
            Ok(_) => self.notice = Some(t.sent_saved().to_string()),
            Err(e) => self.announce_afar_failed(&e),
        }
        // The Area goes into the folder as well.
        if transport == Transport::Folder {
            self.folder_now()?;
        }
        Ok(())
    }

    /// Announces that sharing from afar failed as `error` says; the click
    /// opens the cause, the fix and the full text.
    fn announce_afar_failed(&mut self, error: &oldbrainfix_core::Error) {
        let t = self.t;
        self.announce_failure(
            t.share_afar_failed(),
            t.share_afar_failed_title(),
            (t.share_afar_failed_cause(), t.share_afar_failed_fix()),
            format!("share from afar: {error}"),
        );
    }

    /// Accepts the Area shared from afar the dialog shows (#108), the
    /// sharer verified when the codes matched; asks for the shared folder
    /// when its changes travel by one and none is chosen here. One
    /// decided meanwhile, or refused now, is announced, not failed.
    fn accept_offer(&mut self) -> oldbrainfix_core::Result<()> {
        let Some(Dialog::AreaOffer { held, compared, .. }) = self.dialog.take() else {
            return Ok(());
        };
        let t = self.t;
        match self
            .store
            .accept_area_offer(&held.id, compared == Compared::Match)
        {
            Ok(_) => {}
            Err(oldbrainfix_core::Error::Offer(e)) => {
                self.announce_offer_not_taken(e);
                return Ok(());
            }
            // Decided meanwhile; a block drops it too.
            Err(oldbrainfix_core::Error::Invalid(_)) => {
                if self.store.is_blocked(&held.sender.id)? {
                    self.announce_offer_not_taken(OfferError::FromBlocked);
                } else {
                    self.notice = Some(t.area_offer_gone().to_string());
                }
                return Ok(());
            }
            Err(e) => return Err(e),
        }
        self.notice = Some(t.area_offer_accepted().to_string());
        // The alerts plan the Area's Routines.
        if let Some(wake) = &self.wake {
            drop(wake.send(Event::Wake));
        }
        if held.transport == Transport::Folder && self.store.sync_folder()?.is_none() {
            self.dialog = Some(Dialog::OfferFolder {
                area: offer_area(&t, &held),
            });
        } else if held.transport == Transport::Folder {
            self.folder_now()?;
        }
        Ok(())
    }

    /// "Send changes to Ann" on the person's Profile the dialog shows
    /// (#108): saves a bundle of what is new in the Areas shared with
    /// them, for all of their Devices at once, where the user says;
    /// nothing asked when nothing is new for them.
    fn send_changes(&mut self) -> oldbrainfix_core::Result<()> {
        let Some(Dialog::Person { id, .. }) = &self.dialog else {
            return Ok(());
        };
        let id = id.clone();
        let title = self.t.person_send_changes_title().to_string();
        if let Some(sent) = self.send_changes_to(&id, &title)? {
            self.announce_changes(&[sent]);
        }
        Ok(())
    }

    /// After a click on the Changes Nudge (#109): a save dialog for each
    /// person waiting, one after another, in the order the Changes Nudge
    /// names them. A dialog cancelled skips that person, who keeps the
    /// Changes Nudge.
    fn send_waiting_changes(&mut self) -> oldbrainfix_core::Result<()> {
        let Some(planned) = Alarms::new(&self.store).changes_nudge(&*self.wall)? else {
            return Ok(());
        };
        let mut sent = Vec::new();
        for id in &planned.people {
            let shown = self.store.person_shown(id)?;
            let name = profile_view::display_name(&self.t, &shown.name).to_string();
            let title = self.t.changes_save_title(&name);
            if let Some(one) = self.send_changes_to(id, &title)? {
                sent.push(one);
            }
        }
        self.announce_changes(&sent);
        Ok(())
    }

    /// Announces what came of saving the changes `sent` for one person or
    /// more, once (UI laws, "Announcements"): a failure whose click opens
    /// each one's full text, else that they are saved, else that nothing
    /// was new; nothing when every dialog was cancelled.
    fn announce_changes(&mut self, sent: &[ChangesSent]) {
        let t = self.t;
        let failed: Vec<&str> = sent
            .iter()
            .filter_map(|s| match s {
                ChangesSent::Failed(details) => Some(details.as_str()),
                _ => None,
            })
            .collect();
        if !failed.is_empty() {
            self.announce_failure(
                t.changes_not_saved(),
                t.changes_not_saved_title(),
                (t.changes_not_saved_cause(), t.changes_not_saved_fix()),
                failed.join("\n"),
            );
        } else if sent.contains(&ChangesSent::Saved) {
            self.notice = Some(t.sent_saved().to_string());
        } else if !sent.is_empty() {
            self.notice = Some(t.changes_nothing_new().to_string());
        }
    }

    /// Saves a bundle of what is new for the person `id` where the save
    /// dialog titled `title` says, and only once it is saved counts the
    /// changes up to the log's mark, read before writing, as sent to them
    /// (#109). What came of it; `None` when the dialog was cancelled.
    fn send_changes_to(
        &mut self,
        id: &str,
        title: &str,
    ) -> oldbrainfix_core::Result<Option<ChangesSent>> {
        if self.store.entries_for_person(id)?.is_empty() {
            return Ok(Some(ChangesSent::NothingNew));
        }
        let day = (self.wall)(self.store.now()).date();
        let theirs = self.store.person_theirs(id)?.name;
        let Some(mut path) = (self.bundle_saver)(title, &changes_file_name(day, id, &theirs))
        else {
            return Ok(None);
        };
        if path.extension().is_none_or(|e| e != bundle::EXTENSION) {
            path.set_extension(bundle::EXTENSION);
        }
        let seq = self.store.current_seq()?;
        Ok(Some(
            match bundle::write_person_bundle_now(&self.store, &path, id) {
                Ok(Some(_)) => {
                    self.store.note_changes_sent(id, seq)?;
                    ChangesSent::Saved
                }
                Ok(None) => ChangesSent::NothingNew,
                Err(e) => {
                    let name =
                        profile_view::display_name(&self.t, &self.store.person_shown(id)?.name)
                            .to_string();
                    ChangesSent::Failed(format!("{name}: {e}"))
                }
            },
        ))
    }

    /// Imports the bundle at `path` and announces what came in; one
    /// offering an Area shared from afar (#108) shows its preview instead.
    fn import_bundle(&mut self, path: &std::path::Path) {
        match import_bundle_result(&self.store, path) {
            Ok(result) => match result.offer {
                Some(held) => {
                    self.dialog = Some(Dialog::AreaOffer {
                        held,
                        compared: Compared::Not,
                        blocking: None,
                    });
                }
                None => self.announce_imported(&result),
            },
            Err(oldbrainfix_core::Error::Offer(e)) => self.announce_offer_not_taken(e),
            Err(e) => {
                let t = self.t;
                self.announce_failure(
                    t.bundle_not_imported(),
                    t.bundle_not_imported_title(),
                    bundle_import_why(&t, &e),
                    format!("bundle: {e}"),
                );
            }
        }
        self.refresh();
        // The alerts plan again: a Done in the bundle closes its alarm.
        if let Some(wake) = &self.wake {
            drop(wake.send(Event::Wake));
        }
    }

    /// Announces what the bundle import `result` brought (UI laws,
    /// "Announcements"): that it came in, how much behind the click; that
    /// changes were refused, why behind the click; or that nothing could
    /// be read, as from a Device not paired with this one.
    fn announce_imported(&mut self, result: &BundleResult) {
        let t = self.t;
        if result.needs_pairing() {
            self.announce_failure(
                t.bundle_not_imported(),
                t.bundle_not_imported_title(),
                (t.bundle_pair_first_cause(), t.bundle_pair_first_fix()),
                "bundle: from a Device not paired with this one".into(),
            );
            return;
        }
        let refused = result.report.refused_count() as i64;
        if refused > 0 {
            self.announce_failure(
                &t.host_refused(refused),
                t.host_refused_title(),
                (&t.sync_refused(refused), t.host_refused_fix()),
                bundle_result_text(&t, result),
            );
        } else {
            self.announce_done(t.bundle_imported(), bundle_result_text(&t, result));
        }
    }

    /// Announces how the Import of the folder `name` ended (UI laws,
    /// "Announcements"): that it finished, what went where behind the
    /// click with a way into the new Area; that nothing in it was
    /// usable; or that it failed, each with the cause and the fix.
    fn announce_folder_imported(&mut self, name: &str, imported: Imported) {
        let t = self.t;
        let summary = match imported {
            Ok(summary) => summary,
            Err(details) => {
                self.announce_failure(
                    t.import_failed(),
                    t.import_failed_title(),
                    (t.import_failed_cause(), t.import_failed_fix()),
                    details,
                );
                return;
            }
        };
        let skipped =
            t.import_skipped_details(name, summary.not_text as i64, summary.too_large as i64);
        let Some(area) = summary.area_id.clone() else {
            self.announce_failure(
                t.import_nothing(),
                t.import_nothing_title(),
                (t.import_nothing_cause(), t.import_nothing_fix()),
                skipped,
            );
            return;
        };
        // The Area just made, by the name it shows under; the name asked
        // for should it not be read.
        let shown = match Places::new(&self.store).area_by_id(&area) {
            Ok(Some(made)) => area_name(&t, &made),
            _ => t.import_area_name(name),
        };
        let mut details = t.import_finished_notes(summary.notes as i64, &shown);
        if summary.skipped() > 0 {
            details.push_str("\n\n");
            details.push_str(&t.import_finished_skipped(summary.skipped() as i64));
            details.push('\n');
            details.push_str(&skipped);
        }
        self.notice = Some(t.import_finished().to_string());
        self.notice_dialog = Some((
            t.import_finished().to_string(),
            Dialog::Imported { details, area },
        ));
    }

    /// Announces how the Import of the Markdown file `name` from its viewer
    /// ended (obf-1056), as [`App::announce_folder_imported`] does for a
    /// folder: that it finished, what went where behind the click with a
    /// way into the new Area; that the file was too large to take; or
    /// that it failed.
    fn announce_markdown_imported(&mut self, name: &str, imported: Imported) {
        let t = self.t;
        let summary = match imported {
            Ok(summary) => summary,
            Err(details) => {
                self.announce_failure(
                    t.desk_markdown_import_failed(),
                    t.import_failed_title(),
                    (
                        t.desk_markdown_import_failed_cause(),
                        t.desk_markdown_import_failed_fix(),
                    ),
                    details,
                );
                return;
            }
        };
        let skipped =
            t.desk_markdown_import_skipped(name, summary.not_text as i64, summary.too_large as i64);
        let Some(area) = summary.area_id.clone() else {
            self.announce_failure(
                t.desk_markdown_import_nothing(),
                t.import_nothing_title(),
                (
                    t.desk_markdown_import_nothing_cause(),
                    t.desk_markdown_import_nothing_fix(),
                ),
                skipped,
            );
            return;
        };
        let shown = match Places::new(&self.store).area_by_id(&area) {
            Ok(Some(made)) => area_name(&t, &made),
            _ => t.import_area_name(name),
        };
        let mut details = t.import_finished_notes(summary.notes as i64, &shown);
        if summary.photos > 0 {
            details.push('\n');
            details.push_str(&t.import_keep_photos(summary.photos as i64));
        }
        if summary.skipped() > 0 {
            details.push_str("\n\n");
            details.push_str(&t.import_finished_skipped(summary.skipped() as i64));
            details.push('\n');
            details.push_str(&skipped);
        }
        self.notice = Some(t.import_finished().to_string());
        self.notice_dialog = Some((
            t.import_finished().to_string(),
            Dialog::Imported { details, area },
        ));
    }

    /// Announces how the import from Google Keep ended, as
    /// [`App::announce_folder_imported`] does: what went where behind the
    /// click, the Checklists and photos among it and what was skipped
    /// and why, in the phone's order; that the export held no note to
    /// take; or that it failed.
    fn announce_keep_imported(&mut self, imported: Imported) {
        let t = self.t;
        let summary = match imported {
            Ok(summary) => summary,
            Err(details) => {
                self.announce_failure(
                    t.import_keep_failed(),
                    t.import_failed_title(),
                    (t.import_keep_failed_cause(), t.import_keep_failed_fix()),
                    details,
                );
                return;
            }
        };
        let skipped = t.import_keep_skipped_details(
            summary.trashed as i64,
            summary.missing as i64,
            summary.not_photo as i64,
            summary.too_large as i64,
            summary.not_text as i64,
        );
        let Some(area) = summary.area_id.clone() else {
            self.announce_failure(
                t.import_keep_nothing(),
                t.import_nothing_title(),
                (t.import_keep_nothing_cause(), t.import_keep_nothing_fix()),
                skipped,
            );
            return;
        };
        let shown = match Places::new(&self.store).area_by_id(&area) {
            Ok(Some(made)) => area_name(&t, &made),
            _ => t.import_keep_area_name().to_string(),
        };
        let mut details = vec![t.import_finished_notes(summary.notes as i64, &shown)];
        if summary.checklists > 0 {
            details.push(t.import_keep_checklists(summary.checklists as i64));
        }
        if summary.photos > 0 {
            details.push(t.import_keep_photos(summary.photos as i64));
        }
        if summary.skipped() > 0 {
            details.push(String::new());
            details.push(t.import_keep_skipped(summary.skipped() as i64));
            details.push(skipped);
        }
        self.notice = Some(t.import_finished().to_string());
        self.notice_dialog = Some((
            t.import_finished().to_string(),
            Dialog::Imported {
                details: details.join("\n"),
                area,
            },
        ));
    }

    /// Leaves folder syncs to the thread that `wanted` wakes.
    pub fn set_folder_wanted(&mut self, wanted: Arc<AtomicBool>) {
        self.folder_wanted = Some(wanted);
    }

    /// Shows the line under the menu bar while `syncing` runs (#225).
    pub fn set_syncing(&mut self, syncing: Syncing) {
        self.syncing = Some(syncing);
    }

    /// Reads the Agenda on a thread of its own from now on (#207), on the
    /// store `open` hands it each time: a connection of its own to the
    /// window's database. The window draws on meanwhile, the rows read
    /// last showing; a read the log has changed since is dropped and read
    /// again.
    pub fn set_agenda_store(&mut self, open: impl Fn() -> Arc<Store> + Send + Sync + 'static) {
        self.agenda_reads = Some(AgendaReads {
            open: Arc::new(open),
            shown: self.view.agenda.clone(),
            shown_seq: None,
            running: None,
            again: false,
            held: false,
        });
    }

    /// Starts a read of the Agenda on its thread while it shows, or one
    /// more after the read running.
    fn read_agenda_aside(&mut self) {
        if self.agenda_reads.is_none() || self.selection != Selection::Agenda {
            return;
        }
        let system = match self.unit_system() {
            Ok(system) => system,
            Err(e) => {
                self.error = Some(e.to_string());
                return;
            }
        };
        let (t, wall) = (self.t, self.wall.clone());
        let Some(reads) = &mut self.agenda_reads else {
            return;
        };
        if reads.running.is_some() || reads.held {
            reads.again = true;
            return;
        }
        let (sent, arrives) = std::sync::mpsc::channel();
        let open = reads.open.clone();
        std::thread::spawn(move || {
            let store = open();
            let before = store.current_seq().ok();
            let read = read_agenda(&store, &t, &*wall, system);
            // Today's picks written there, also by a read that failed
            // after them; a read that failed writing nothing wrote nothing.
            let wrote = before.is_some_and(|before| store.current_seq().ok() != Some(before));
            drop(sent.send((read, wrote)));
        });
        reads.running = Some(arrives);
    }

    /// Reads All Notes' most used tags (obf-1074) while it shows, where
    /// the log changed since they were read: on a thread with the
    /// Agenda's opener, else here. The desktop has no Area Locks, so
    /// nothing is closed.
    fn read_tags(&mut self) {
        if self.selection != Selection::All || self.alone.is_some() {
            return;
        }
        // Its end looks at the log again. An Import or an Area being
        // deleted writes a Note after another: read again at its end.
        if self.tag_row.running.is_some() || self.import.running() || self.deletions.running() {
            return;
        }
        let Ok(seq) = self.store.current_seq() else {
            return;
        };
        if self.tag_row.seq == Some(seq) {
            return;
        }
        fn read(store: &Store) -> TagsRead {
            let seq = store.current_seq().unwrap_or_default();
            let tags = TagTree::new(store)
                .tree(&HashSet::new())
                .map(|tree| tag_tree_view::most_used(&tree, tag_tree_view::MOST_USED));
            (seq, tags)
        }
        match self.agenda_reads.as_ref().map(|reads| reads.open.clone()) {
            Some(open) => {
                let (sent, arrives) = std::sync::mpsc::channel();
                let spawned = std::thread::Builder::new()
                    .name(TAGS_THREAD.to_string())
                    .spawn(move || drop(sent.send(read(&open()))));
                match spawned {
                    Ok(_) => self.tag_row.running = Some(arrives),
                    // No thread to be had: read here.
                    Err(_) => self.tags_read(read(&self.store)),
                }
            }
            None => self.tags_read(read(&self.store)),
        }
    }

    /// Keeps the most used tags `read`; one that failed says so and is
    /// read again at the log's next mark.
    fn tags_read(&mut self, (seq, tags): TagsRead) {
        self.tag_row.seq = Some(seq);
        match tags {
            Ok(tags) => self.tag_row.tags = tags,
            Err(e) => self.error = Some(e.to_string()),
        }
    }

    /// Shows the most used tags from their thread once they are in, and
    /// reads them again where the log changed meanwhile. The window looks
    /// again shortly while the read runs.
    fn tags_arrived(&mut self, ctx: &egui::Context) {
        let Some(running) = &self.tag_row.running else {
            return;
        };
        match running.try_recv() {
            Ok(read) => {
                self.tag_row.running = None;
                self.tags_read(read);
                self.read_tags();
                ctx.request_repaint();
            }
            Err(std::sync::mpsc::TryRecvError::Empty) => {
                ctx.request_repaint_after(std::time::Duration::from_millis(30));
            }
            Err(std::sync::mpsc::TryRecvError::Disconnected) => self.tag_row.running = None,
        }
    }

    /// Counts what "Empty the trash now" deletes (obf-1095) while the
    /// Trash shows, where the log changed since they were counted: on a
    /// thread with the Agenda's opener, as reading them reads every Note,
    /// else here. Not while the trash is being emptied: its end counts
    /// again.
    fn count_trash(&mut self) {
        if self.selection != Selection::Trash {
            return;
        }
        let Ok(seq) = self.store.current_seq() else {
            return;
        };
        if !self.trash_emptying.wants_read(seq) {
            return;
        }
        if let Some(open) = self.agenda_reads.as_ref().map(|reads| reads.open.clone())
            && self
                .trash_emptying
                .read_aside(seq, Box::new(move || open()))
        {
            return;
        }
        let read = trash_emptying::count(&self.store);
        self.trash_counted(seq, read);
    }

    /// Keeps the counts `read` at the log's mark `seq`; one that failed
    /// says so.
    fn trash_counted(&mut self, seq: i64, read: Result<trash_emptying::Counted, String>) {
        if let Err(e) = self.trash_emptying.read_in(seq, read) {
            self.error = Some(e);
        }
    }

    /// Takes in the counts from their thread once they are in, and
    /// counts again where the log changed meanwhile. The window looks
    /// again shortly while they are counted.
    fn trash_counts_arrived(&mut self, ctx: &egui::Context) {
        if !self.trash_emptying.reading() {
            return;
        }
        match self.trash_emptying.read_arrived() {
            Some((seq, read)) => {
                self.trash_counted(seq, read);
                // A question open shows the counts as they are now, and
                // goes where nothing is left to delete.
                if let Some(Dialog::EmptyTrash { notes, routines }) = &mut self.dialog {
                    match self.trash_emptying.counted() {
                        Some(counted) if self.trash_emptying.offered() => {
                            (*notes, *routines) = counted;
                        }
                        _ => self.dialog = None,
                    }
                }
                self.count_trash();
                ctx.request_repaint();
            }
            None => ctx.request_repaint_after(std::time::Duration::from_millis(30)),
        }
    }

    /// Empties the trash, `counted` being what the question named
    /// (obf-1095): beside the window on a connection of its own where
    /// there is the Import's opener, as deleting an Area, else at once.
    fn empty_trash(&mut self, counted: trash_emptying::Counted) {
        if self.trash_emptying.running() {
            return;
        }
        if self.import_open.is_some() {
            let open = self.import_store();
            self.trash_emptying.start(open, counted);
        } else {
            let emptied = trash_emptying::empty(&self.store);
            self.trash_emptied(emptied);
        }
    }

    /// Once the trash was emptied: a failure is announced at the top with
    /// what went wrong; the alarms plan anew, as Routines and Reminders
    /// went with their Notes.
    fn trash_emptied(&mut self, emptied: trash_emptying::Emptied) {
        let t = self.t;
        if let Err(details) = emptied {
            self.announce_failure(
                t.desk_trash_empty_failed(),
                t.desk_trash_empty_failed_title(),
                (
                    t.desk_trash_empty_failed_cause(),
                    t.desk_trash_empty_failed_fix(),
                ),
                details,
            );
        }
        if let Some(wake) = &self.wake {
            drop(wake.send(Event::Wake));
        }
    }

    /// Shows the Agenda's read from its thread once it is in, unless the
    /// log changed since it was read: then it reads again (#207). The
    /// window looks again shortly while it runs.
    fn agenda_arrived(&mut self, ctx: &egui::Context) {
        // The first frame: the read held since the window opened starts.
        if let Some(reads) = &mut self.agenda_reads
            && std::mem::take(&mut reads.held)
            && std::mem::take(&mut reads.again)
        {
            self.read_agenda_aside();
        }
        // An Import writes a Note after another meanwhile (obf-1061): the
        // read shows as it is, and its end reads again.
        // So does deleting an Area (obf-1093), a Note after another.
        let importing = self.import.running() || self.deletions.running();
        let Some(reads) = &mut self.agenda_reads else {
            return;
        };
        let Some(running) = &reads.running else {
            return;
        };
        let (read, wrote) = match running.try_recv() {
            Ok(arrived) => arrived,
            Err(std::sync::mpsc::TryRecvError::Empty) => {
                ctx.request_repaint_after(std::time::Duration::from_millis(30));
                return;
            }
            Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                reads.running = None;
                return;
            }
        };
        reads.running = None;
        // Today's picks written there: this connection reads them anew,
        // which is no reason to read the Agenda again.
        if wrote {
            self.store.changed_elsewhere();
        }
        match read {
            Ok((view, seq)) if importing || self.store.current_seq().ok() == Some(seq) => {
                if self.selection == Selection::Agenda {
                    self.view.agenda = Some(view.clone());
                }
                reads.shown = Some(view);
                reads.shown_seq = Some(seq);
            }
            Ok(_) => reads.again = true,
            Err(e) => self.error = Some(e.to_string()),
        }
        let again = std::mem::take(&mut reads.again);
        if again {
            self.read_agenda_aside();
        }
        ctx.request_repaint();
    }

    /// Places the Occurrence a click on its notification asked for
    /// (obf-1039) once the Agenda is read at the click's mark or later:
    /// marked, and scrolled into view once, where the Agenda lists it;
    /// where it lists it nowhere, as one Done or skipped meanwhile, the
    /// top says so. One still open that no day of the Agenda shows, as a
    /// weekly one of yesterday, not Missed until its next, opens its Note
    /// dialog over the Agenda, whose Due line answers it. Each goes into
    /// the trace of the clicks; the mark goes once the Agenda is left.
    fn place_notified(&mut self) {
        let Some(notified) = &mut self.notified else {
            return;
        };
        if self.selection != Selection::Agenda {
            self.notified = None;
            return;
        }
        if notified.place.is_some() {
            return;
        }
        let Some(agenda) = &self.view.agenda else {
            return;
        };
        // On its thread the Agenda shows the rows read last a while.
        let read = self.agenda_reads.as_ref().is_none_or(|reads| {
            reads
                .shown_seq
                .is_some_and(|seq| notified.seq.is_none_or(|at| seq >= at))
        });
        if !read {
            return;
        }
        let key = crate::alerts::occurrence_key(&notified.routine, &notified.occurrence);
        if let Some(place) = agenda_place(agenda, &notified.routine, &notified.occurrence) {
            notified.place = Some(place);
            notified.scroll = true;
            self.click_trace.went(&key, &place.traced());
            return;
        }
        let occurrence = notified.occurrence;
        let routines = Routines::new(&self.store);
        let routine = routines.by_id(&notified.routine).ok().flatten();
        let note = routine
            .as_ref()
            .filter(|r| !r.is_trashed())
            .and_then(|r| routines.note(r).ok().flatten())
            .filter(|n| !n.is_trashed());
        self.notified = None;
        let t = self.t;
        let (said, went) = match (routine, note) {
            (Some(r), _) if r.done_at(&occurrence).is_some() => {
                (Some(t.notification_already_done()), "Agenda, already done")
            }
            (Some(r), _) if r.skipped_at(&occurrence).is_some() => {
                (Some(t.occurrence_skipped()), "Agenda, skipped")
            }
            (Some(_), Some(note)) => {
                // A Routine editor or Tally form open keeps its draft, over
                // the Note dialog.
                let (editor, tally_form) = (self.editor.take(), self.tally_form.take());
                self.apply(Action::SelectNote(note.id));
                self.editor = editor;
                self.tally_form = tally_form;
                (None, "Note dialog, not on the Agenda")
            }
            (Some(_), None) => (None, "Agenda, not listed"),
            (None, _) => (None, "Agenda, Routine gone"),
        };
        if let Some(said) = said {
            self.notice = Some(said.to_string());
        }
        self.click_trace.went(&key, went);
    }

    /// The searches typed into (obf-1068): each runs on a thread of its
    /// own once typing stopped for a moment, on a connection the Agenda's
    /// opener hands it, and what it found shows once it is in, unless
    /// what was typed, the list or the log changed since. Without the
    /// opener the window searches at every letter itself.
    fn search_arrived(&mut self, ctx: &egui::Context) {
        let Some(open) = self.agenda_reads.as_ref().map(|reads| reads.open.clone()) else {
            return;
        };
        // What the connection worked out from the log, the rights among
        // it, forgotten once the window wrote since its last search.
        let (window, mark) = (self.store.clone(), self.search_mark.clone());
        let open: StoreOpener = Arc::new(move || {
            let store = open();
            let now = store.current_seq().unwrap_or_default();
            if !Arc::ptr_eq(&store, &window) && mark.swap(now, Ordering::SeqCst) != now {
                store.changed_elsewhere();
            }
            store
        });
        self.list_search_arrived(ctx, &open);
        self.dialog_search_arrived(ctx, &open);
    }

    /// The list's search: its cards read on the thread with the Notes
    /// found, shown by the next read of the rest.
    fn list_search_arrived(&mut self, ctx: &egui::Context, open: &StoreOpener) {
        let mut searching = std::mem::take(&mut self.searching);
        let arrived = searching.frame(ctx, &self.query, |query| {
            let mut key = self.cards_key_now()?;
            key.query = query.to_string();
            let ask = self.cards_ask(query, &self.view.areas);
            let open = open.clone();
            let work: Work<CardsArrived> = Box::new(move || (key, read_cards(&open(), &ask)));
            Some(work)
        });
        self.searching = searching;
        let Some((_, (key, read))) = arrived else {
            return;
        };
        let mut now = self.cards_key_now();
        if let Some(now) = &mut now {
            now.query = key.query.clone();
        }
        // Read before the log or the list changed: searched again.
        if now.as_ref() != Some(&key) {
            return;
        }
        self.searching.set_searched(&key.query);
        match read {
            Ok(cards) => self.cards_arrived.set(Some((key, cards))),
            // Read here again, which says what failed.
            Err(_) => self.cards_arrived.set(None),
        }
        self.refresh();
        self.cards_arrived.set(None);
    }

    /// The cards the list's search brought, where they are still those
    /// of the list as it is now.
    fn arrived_cards(&self) -> Option<CardsRead> {
        let (key, cards) = self.cards_arrived.take()?;
        (self.cards_key_now().as_ref() == Some(&key)).then_some(cards)
    }

    /// The search of Merge into… or Add to Note…, whichever shows: the
    /// Notes it offers, found on the thread.
    fn dialog_search_arrived(&mut self, ctx: &egui::Context, open: &StoreOpener) {
        // Merge into… offers what the Notes merged may go into, Add to
        // Note… what the Note added alone may be added to.
        let (query, merging, alone) = match &self.dialog {
            Some(Dialog::Merge { notes, query, .. }) => (query.clone(), Some(notes.clone()), None),
            Some(Dialog::AddToNote { picker, .. }) => (
                picker.query().to_string(),
                None,
                picker.alone().map(str::to_string),
            ),
            // Another dialog, or none: the next starts on its own.
            _ => {
                self.dialog_searching = Searching::default();
                return;
            }
        };
        let t = self.t;
        // Enter picks the first Note found for what is typed now: one
        // typed since the last search is searched here at once.
        let enter = ctx.input(|i| i.key_pressed(egui::Key::Enter));
        let arrived = if enter && query != self.dialog_searching.searched() {
            let found = match &merging {
                Some(merging) => merge_candidates(&self.store, &t, &query, merging),
                None => add_to_note::offered(&self.store, &t, &query, alone.as_deref()),
            };
            Some((query, found))
        } else {
            let open = open.clone();
            let start = |query: &str| -> Option<Work<DialogFound>> {
                let query = query.to_string();
                Some(match merging {
                    Some(merging) => {
                        Box::new(move || merge_candidates(&open(), &t, &query, &merging))
                    }
                    None => Box::new(move || {
                        add_to_note::offered(&open(), &t, &query, alone.as_deref())
                    }),
                })
            };
            self.dialog_searching.frame(ctx, &query, start)
        };
        let Some((asked, found)) = arrived else {
            return;
        };
        self.dialog_searching.set_searched(&asked);
        let found = match found {
            Ok(found) => found,
            Err(e) => {
                self.error = Some(e.to_string());
                return;
            }
        };
        match &mut self.dialog {
            Some(Dialog::Merge { others, .. }) => *others = found,
            Some(Dialog::AddToNote { picker, .. }) => picker.set_found(found),
            _ => {}
        }
    }

