    /// Syncs through the shared folder now: on the folder thread, or here
    /// when there is none.
    fn folder_now(&mut self) -> oldbrainfix_core::Result<()> {
        self.sync_goes_on();
        match &self.folder_wanted {
            Some(wanted) => wanted.store(true, Ordering::SeqCst),
            None => {
                folder_sync::round(&self.store)?;
            }
        }
        Ok(())
    }

    /// Ends a pause of the automatic syncs Abort began on the page
    /// Running (obf-1078): syncing now by hand syncs on from then.
    fn sync_goes_on(&self) {
        if let Some(syncing) = self.syncing.as_ref().filter(|s| s.paused()) {
            syncing.go_on();
        }
    }

    /// The AI port while it is open (#112).
    pub fn ai_port(&self) -> Option<&AiPort> {
        self.ai_port.as_ref()
    }

    /// Shows the review of the AI Task that waits, if one does; one that
    /// changed nothing is declined without asking.
    fn review_ai(&mut self) -> oldbrainfix_core::Result<()> {
        let Some(task) = self.store.ai_task()? else {
            return Ok(());
        };
        if self.store.ai_review(&task)?.is_empty() {
            self.store.decline_pending(&task)?;
            if self.selection == Selection::AiReview {
                self.go(Selection::Agenda);
            }
        } else {
            // In the list, the dialogs over it closed.
            self.pages.clear();
            self.go(Selection::AiReview);
        }
        Ok(())
    }

    /// What was asked of the AI port's card or of the review (#112).
    fn ai_action(&mut self, asked: AiAction) -> oldbrainfix_core::Result<()> {
        let t = self.t;
        match asked {
            AiAction::Open => {
                if self.ai_port.is_none() {
                    let opened = match &self.redraw {
                        Some(redraw) => AiPort::open_waking(&self.store, redraw.clone()),
                        None => AiPort::open(&self.store),
                    };
                    match opened {
                        Ok(port) => self.ai_port = Some(port),
                        // The card says so; nothing opened.
                        Err(oldbrainfix_core::Error::NoDockerBridge) => return Ok(()),
                        Err(e) => return Err(e),
                    }
                    self.ai_copied = None;
                }
                // The review waits again until "Done, review".
                if self.selection == Selection::AiReview {
                    self.go(Selection::Agenda);
                }
            }
            AiAction::Reach(reach) => {
                if self.ai_port.is_none() {
                    self.store.set_ai_reach(reach)?;
                }
            }
            AiAction::Copy(client) => {
                if let Some(port) = &self.ai_port {
                    self.copy = Some(ai_view::client_text(client, &port.url(), port.token()));
                    self.ai_copied = Some(client);
                }
            }
            AiAction::Done => {
                if let Some(mut port) = self.ai_port.take() {
                    // What the client asked before "Done" still counts.
                    port.answer_waiting(&self.store, &*self.wall);
                    port.close();
                }
                self.ai_copied = None;
                self.review_ai()?;
            }
            AiAction::Review => {
                // Always the review page (obf-1077): one that changed
                // nothing, with the port closed, is declined as at
                // "Done, review", and the page says "No changes yet".
                if self.ai_port.is_none()
                    && let Some(task) = self.store.ai_task()?
                    && self.store.ai_review(&task)?.is_empty()
                {
                    self.store.decline_pending(&task)?;
                }
                // In the list, the dialogs over it closed.
                self.pages.clear();
                self.go(Selection::AiReview);
            }
            AiAction::Accept => {
                if self.ai_port.is_some() {
                    return Ok(());
                }
                if let Some(task) = self.store.ai_task()? {
                    self.store.accept_pending(&task)?;
                    self.notice = Some(t.ai_accepted().to_string());
                }
                self.go(Selection::Agenda);
            }
            AiAction::AskReject => self.dialog = Some(Dialog::RejectAi),
            AiAction::Reject => {
                self.dialog = None;
                if self.ai_port.is_some() {
                    return Ok(());
                }
                if let Some(task) = self.store.ai_task()? {
                    self.store.decline_pending(&task)?;
                    self.notice = Some(t.ai_rejected().to_string());
                }
                self.go(Selection::Agenda);
            }
        }
        Ok(())
    }

    /// The AI Task's review (#112), "No changes yet" without one, and
    /// while the port is open the changes so far (obf-1077).
    fn ai_review_pane(&mut self, ui: &mut Ui, tones: Tones, actions: &mut Vec<Action>) {
        let t = self.t;
        let none = ReviewShown::default();
        let shown = self.view.ai_review.as_ref().unwrap_or(&none);
        let open = self.ai_port.is_some();
        let mut asked = None;
        if let Some(note) = ai_view::review_page(ui, &t, tones, shown, open, &mut asked) {
            actions.push(Action::SelectNote(note));
        }
        if let Some(asked) = asked {
            actions.push(Action::Ai(asked));
        }
    }

    /// The Ask panel (#267): its provider, the question field and the
    /// answers.
    fn ask_pane(&mut self, ui: &mut Ui, tones: Tones, actions: &mut Vec<Action>) {
        let Some(provider) = &self.view.ask_provider else {
            return;
        };
        let shown = ask_view::PanelShown {
            provider,
            task_waits: self.view.ai_task.is_some(),
            reviews: self.ai_port.is_none(),
        };
        let mut asked = Vec::new();
        ask_view::page(ui, &self.t, tones, &mut self.ask, shown, &mut asked);
        actions.extend(asked.into_iter().map(Action::Ask));
    }

    /// Lets the Ask panel's requests go through `transport`, as the tests
    /// fake a provider (#267).
    pub fn set_ask_transport(&mut self, transport: Arc<dyn ask::Transport>) {
        self.ask_transport = transport;
    }

    /// The Ask panel's questions and answers (#267).
    pub fn ask_panel(&self) -> &AskPanel {
        &self.ask
    }

    /// What was asked of the Ask panel (#267).
    fn ask_asked(&mut self, asked: AskAsked) -> oldbrainfix_core::Result<()> {
        match asked {
            AskAsked::Ask => self.ask_question()?,
            AskAsked::Stop => {
                // What was asked goes back into the field.
                if let Some(question) = self.ask_stop()? {
                    self.ask.question = question;
                }
                self.ask.focus = true;
            }
            AskAsked::StartOver => {
                self.ask_stop()?;
                self.ask.exchanges.clear();
                self.ask.failed = None;
                self.ask.focus = true;
            }
            AskAsked::Keep(at) => {
                let Some(asked) = self.ask.exchanges.get(at) else {
                    return Ok(());
                };
                if asked.kept.is_some() {
                    return Ok(());
                }
                let text = ask_view::kept_text(asked);
                let note = Notes::new(&self.store).capture_as(
                    &text,
                    oldbrainfix_core::text_format::MARKDOWN,
                    None,
                    None,
                )?;
                if let Some(asked) = self.ask.exchanges.get_mut(at) {
                    asked.kept = Some(note.id);
                }
            }
            AskAsked::Copy(at) => {
                if let Some(asked) = self.ask.exchanges.get(at) {
                    let share = ask_view::answer_share(&asked.answer.text);
                    self.copy_share(share);
                }
            }
            AskAsked::AddToNote(at) => {
                if self.ask.exchanges.get(at).is_some() {
                    let picker = NotePicker::read(&self.store, &self.t, &[])?;
                    self.dialog = Some(Dialog::AddToNote {
                        adding: Filing::Answer(at),
                        picker: Box::new(picker),
                    });
                }
            }
            AskAsked::Save(at) => {
                if let Some(asked) = self.ask.exchanges.get(at) {
                    let share = ask_view::answer_share(&asked.answer.text);
                    let name = share_note::file_name(&asked.question);
                    self.save_share(&share, &name)?;
                }
            }
            // The question goes into the field to be asked again; its
            // place in the thread stays (#315).
            AskAsked::Edit(at) => {
                if self.ask_run.is_none()
                    && let Some(question) = self.ask.exchanges.get(at).map(|a| a.question.clone())
                {
                    self.ask.put(&question);
                }
            }
            AskAsked::OpenNote(id) => self.act(Action::SelectNote(id))?,
            AskAsked::Review => self.act(Action::Ai(AiAction::Review))?,
            AskAsked::Settings => self.act(Action::OpenAiSettings(Some(ASK_SECTION)))?,
            AskAsked::Details => {
                if let Some(failed) = &self.ask.failed {
                    self.dialog = Some(Dialog::Failure {
                        title: self.t.ask_failed_title().into(),
                        cause: failed.cause.clone(),
                        fix: failed.fix.clone(),
                        details: failed.details.clone(),
                    });
                }
            }
        }
        Ok(())
    }

    /// Asks the question typed in the Ask panel, after those answered: off
    /// the window's thread when it can be woken, else here and at once,
    /// as in the tests.
    fn ask_question(&mut self) -> oldbrainfix_core::Result<()> {
        let question = self.ask.question.trim().to_string();
        let provider = self.store.ask_provider()?;
        if question.is_empty()
            || self.ask_run.is_some()
            || self.store.ask_unready(&provider)?.is_some()
        {
            return Ok(());
        }
        let now = (self.wall)(self.store.now())
            .format("%Y-%m-%d %H:%M, %A")
            .to_string();
        let mut conversation = Conversation::new(provider, &self.ask.earlier(), &question, &now);
        self.ask.question.clear();
        // Asked again, the failure before goes (#317).
        self.ask.failed = None;
        self.ask.read = 0;
        // The thread shows the question asked at its end (#315).
        self.ask.scroll = true;
        let Some(redraw) = self.redraw.clone() else {
            let asked = self
                .store
                .ask(&mut conversation, &*self.ask_transport, &*self.wall);
            self.ask_answered(question, asked.map(|a| a.answer));
            return Ok(());
        };
        let (to_window, arrives) = std::sync::mpsc::channel();
        let (outputs, from_window) = std::sync::mpsc::channel::<Vec<ToolOutput>>();
        let transport = self.ask_transport.clone();
        std::thread::spawn(move || {
            let done = ask::run(&mut conversation, &*transport, |calls| {
                to_window.send(AskArrived::Tools(calls.to_vec())).ok()?;
                redraw();
                from_window.recv().ok()
            });
            drop(to_window.send(AskArrived::Done(done)));
            redraw();
        });
        let before = self.store.ai_task()?;
        self.ask.asking = Some(question.clone());
        self.ask_run = Some(AskRun {
            question,
            arrives,
            outputs,
            task: before.clone(),
            before,
            read: Vec::new(),
        });
        Ok(())
    }

    /// Answers the tools the thread asking waits for, on this thread as
    /// the AI as the store sees it, and takes in its answer once it is in;
    /// the window looks again shortly while it runs.
    fn ask_arrived(&mut self, ctx: &egui::Context) {
        let Some(run) = &mut self.ask_run else {
            return;
        };
        let mut done = None;
        let mut answered = false;
        loop {
            match run.arrives.try_recv() {
                Ok(AskArrived::Tools(calls)) => {
                    let outputs = self.store.ask_calls(&calls, &*self.wall, &mut run.task);
                    for (call, output) in calls.iter().zip(&outputs) {
                        if let Some(id) = ask::note_read(call, output)
                            && !run.read.iter().any(|r| r == id)
                        {
                            run.read.push(id.to_string());
                        }
                    }
                    self.ask.read = run.read.len();
                    drop(run.outputs.send(outputs));
                    answered = true;
                }
                Ok(AskArrived::Done(answer)) => {
                    done = Some(answer);
                    break;
                }
                Err(std::sync::mpsc::TryRecvError::Empty) => break,
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    done = Some(Err(ask::AskError::Stopped));
                    break;
                }
            }
        }
        if let Some(done) = done {
            let question = run.question.clone();
            self.ask_finished();
            self.ask_answered(question, done);
            self.refresh();
        } else {
            if answered {
                self.refresh();
            }
            ctx.request_repaint_after(std::time::Duration::from_millis(50));
        }
    }

    /// Ends the question asked off the window's thread: an AI Task it
    /// opened and left without a change is declined, so sync goes on.
    /// Its question, if one was asked.
    fn ask_finished(&mut self) -> Option<String> {
        let run = self.ask_run.take()?;
        self.ask.asking = None;
        if run.before.is_none()
            && self.ai_port.is_none()
            && let Some(task) = &run.task
            && let Err(e) = self.store.drop_empty_ai_task(task)
        {
            self.error = Some(e.to_string());
        }
        Some(run.question)
    }

    /// Stops waiting for the answer; the thread asking hears it with its
    /// next tools, and what it then brings is dropped. The question
    /// stopped.
    fn ask_stop(&mut self) -> oldbrainfix_core::Result<Option<String>> {
        let question = self.ask_finished();
        self.refresh();
        Ok(question)
    }

    /// Shows the answer to `question` in the Ask panel, with the Notes it
    /// links that are here, by their titles. A question not answered goes
    /// back into the field, and why stays under it with the fix until the
    /// next is asked (#317), but for one stopped.
    fn ask_answered(&mut self, question: String, done: Result<ask::Answer, ask::AskError>) {
        self.ask.focus = true;
        // The thread shows what came back (#315).
        self.ask.scroll = true;
        let answer = match done {
            Ok(answer) => answer,
            Err(why) => {
                let t = self.t;
                let provider = self
                    .store
                    .ask_provider()
                    .map(|p| p.name())
                    .unwrap_or_default();
                if let Some((cause, fix, details)) = ask_view::failure(&t, &provider, &why) {
                    self.ask.failed = Some(ask_view::AskFailed {
                        question: question.clone(),
                        cause,
                        fix,
                        details,
                    });
                }
                if self.ask.question.trim().is_empty() {
                    self.ask.question = question;
                }
                return;
            }
        };
        let notes = Notes::new(&self.store);
        // The Notes here by id with their titles: not one in the trash.
        let titled = |ids: &[String]| -> Vec<(String, String)> {
            let mut out = Vec::new();
            for id in ids {
                if let Ok(Some(note)) = notes.by_id(id)
                    && !note.is_trashed()
                {
                    let title = row_title(&self.t, Some(&note));
                    let first = title.lines().next().unwrap_or_default().to_string();
                    out.push((id.clone(), first));
                }
            }
            out
        };
        let sources = titled(&answer.notes);
        let also_read = titled(&answer.also_read());
        self.ask.exchanges.push(ask_view::Asked {
            question,
            answer,
            sources,
            also_read,
            kept: None,
            added: None,
        });
    }

    /// The list left the Ask panel: its question stops and its answers
    /// go, but what was kept as a Note.
    fn ask_left(&mut self) {
        self.ask_finished();
        self.ask = AskPanel::default();
    }

