/// The setting that keeps the description of the Note `note` unfolded on
/// its card.
fn description_unfolded_setting(note: &str) -> String {
    format!("{DESCRIPTION_UNFOLDED}{note}")
}

/// The setting of this Device that keeps the Notes of the list `key`
/// whose card shows the view the list does not start in, joined by commas
/// (#189).
fn switched_setting(key: &str) -> String {
    format!("switchedNotes:{key}")
}

/// The setting of this Device that keeps the Note list `key` compact
/// (#114), the phone's; none while it shows in full, the default.
fn compact_setting(key: &str) -> String {
    format!("compactNotes:{key}")
}

/// The Notes the Notes `merging` can be merged into that the core's
/// search finds for `query`, by id and the title they show under: a
/// single one is not offered itself, several are, as one of them picked
/// takes the others in (#273).
fn merge_candidates(
    store: &Store,
    t: &L10n,
    query: &str,
    merging: &[String],
) -> oldbrainfix_core::Result<Vec<(String, String)>> {
    let alone = match merging {
        [one] => Some(one.as_str()),
        _ => None,
    };
    Ok(Search::new(store)
        .notes(query, None)?
        .into_iter()
        .filter(|n| Some(n.id.as_str()) != alone)
        .map(|n| (n.id.clone(), row_title(t, Some(&n))))
        .collect())
}

/// Whether the cards of the list kept under `key` show compact, and
/// those switched to the other view.
fn card_view(
    store: &Store,
    key: Option<String>,
) -> oldbrainfix_core::Result<(bool, HashSet<String>)> {
    Ok(match key {
        Some(key) => (
            store.local_setting(&compact_setting(&key))?.as_deref() == Some("true"),
            store
                .local_setting(&switched_setting(&key))?
                .unwrap_or_default()
                .split(',')
                .filter(|id| !id.is_empty())
                .map(str::to_string)
                .collect(),
        ),
        None => (false, HashSet::new()),
    })
}

/// The cards of a list and what they show, read anew (obf-1069) as
/// `ask` says, on the window's thread or on the search's own (obf-1068):
/// the list's Notes found, whose each is and what this Device may do to
/// it, their Sections, links, today's Occurrences, lists, Tallies and
/// Sessions and their view.
fn read_cards(store: &Store, ask: &CardsAsk) -> oldbrainfix_core::Result<CardsRead> {
    let notes = Notes::new(store);
    let units = DeviceSettings::new(store).unit_system(ask.region.as_deref())?;
    let places = Places::new(store);
    let routines = Routines::new(store);
    let search = Search::new(store);
    let shown = match &ask.selection {
        // A Note window shows its Note alone (#287).
        _ if ask.alone => Vec::new(),
        Selection::Agenda
        | Selection::SentItemsWaiting
        | Selection::AreaOffersWaiting
        | Selection::AiReview
        | Selection::Frogs
        | Selection::AllRoutines
        | Selection::Tags
        | Selection::Ask
        | Selection::History(_) => Vec::new(),
        Selection::All => store.notes_by(search.notes(&ask.query, None)?, &ask.people)?,
        Selection::Unsorted => {
            // Its search (#274) keeps the list's order, oldest first.
            let mut unsorted = notes.unsorted()?;
            if !ask.query.trim().is_empty() {
                let found: HashSet<String> = search
                    .notes(&ask.query, None)?
                    .into_iter()
                    .map(|n| n.id)
                    .collect();
                unsorted.retain(|n| found.contains(&n.id));
            }
            store.notes_by(unsorted, &ask.people)?
        }
        Selection::Place(id) => {
            let found = search.notes(&ask.query, Some(id))?;
            // A Topic's Notes show inside the Topic; a search in its
            // Area still finds them, their cards naming the Topic.
            let area = ask.areas.iter().any(|(a, _)| a.id == *id);
            let found = if ask.query.trim().is_empty() && area {
                found
                    .into_iter()
                    .filter(|n| n.place.as_deref() == Some(id.as_str()))
                    .collect()
            } else {
                found
            };
            store.notes_by(found, &ask.people)?
        }
        // Its search (#274) keeps the trash's order.
        Selection::Trash => search.among(&ask.query, notes.trashed()?)?,
    };
    // Whose each card is and whether this Device may change it, read
    // for all of them at once (obf-1069).
    let (placed, changes) = place_notes(store, &places, shown)?;
    // Once per read for every card, never per frame.
    let listed: Vec<String> = placed.iter().map(|p| p.note.id.clone()).collect();
    let sections = if listed.is_empty() {
        BTreeMap::new()
    } else {
        notes.sections_of(&listed)?
    };
    // From what the core keeps until the log changes (obf-1035); the
    // desktop has no Area Locks, so nothing is closed. A card in the
    // trash shows none, as on the phone.
    let backlinks = Backlinks::new(store);
    let mut linked_from = BTreeMap::new();
    let linked = listed.iter().filter(|_| ask.selection != Selection::Trash);
    for id in linked {
        let linking = backlinks.to(id, &HashSet::new())?;
        if !linking.is_empty() {
            linked_from.insert(id.clone(), linking);
        }
    }
    // A Note in the trash ticks nothing.
    let card_today = if listed.is_empty() || ask.selection == Selection::Trash {
        HashMap::new()
    } else {
        let today = routines.today_by_note(&*ask.wall)?;
        card_occurrences::read(store, today, &listed)?
    };
    let lists = Checklists::new(store);
    let mut checklists = BTreeMap::new();
    if !listed.is_empty() {
        for (id, list) in lists.of_notes_now(&listed, &*ask.wall)? {
            let checks = checklist_view::may_check_shown(store, &list)?;
            checklists.insert(id, (list, checks));
        }
    }
    let shopping = ShoppingLists::new(store);
    let mut shopping_lists = BTreeMap::new();
    if !listed.is_empty() {
        for (id, list) in shopping.of_notes(&listed, &*ask.wall)? {
            let checks = shopping.may_check(&id)?;
            shopping_lists.insert(id, (list, checks));
        }
    }
    // A Tally wins over a list (ADR 0030).
    let mut tallies = HashSet::new();
    let tally_notes = Tallies::new(store);
    for id in &listed {
        if tally_notes.is_tally(id)? {
            tallies.insert(id.clone());
        }
    }
    // A Tally wins over a Session too (ADR 0039).
    let session_notes = Sessions::new(store);
    let mut sessions = HashSet::new();
    for id in listed.iter().filter(|id| !tallies.contains(*id)) {
        if session_notes.is_session_note(id)? {
            sessions.insert(id.clone());
        }
    }
    let mut card_changes = HashSet::new();
    let mut card_may = HashSet::new();
    for p in &placed {
        let note = &p.note;
        if !changes.contains(&note.id) {
            continue;
        }
        card_may.insert(note.id.clone());
        if !note.is_trashed() && note.text_editable {
            card_changes.insert(note.id.clone());
        }
    }
    let is_area = matches!(&ask.selection, Selection::Place(id) if ask.areas.iter().any(|(a, _)| a.id == *id));
    let (compact, switched) = card_view(store, cards_key(&ask.selection, &ask.people, is_area))?;
    let glances = card_glance::read(store, &ask.t, &*ask.wall, units, &listed)?;
    // The Tallies on a detailed card, with their chart and entries
    // (#190).
    let mut card_tallies = HashMap::new();
    for id in listed.iter().filter(|id| tallies.contains(*id)) {
        if compact != switched.contains(id) {
            continue;
        }
        let whose = ask.tally_whose.get(id);
        if let Some(shown) = tally_view::read(store, id, whose, units, &*ask.wall)? {
            card_tallies.insert(id.clone(), shown);
        }
    }
    // The Sessions on a detailed card, with their pool, today's picks
    // and last weeks (#191); today's picks as the Agenda shows them,
    // written there, not here.
    let detailed: Vec<&String> = listed
        .iter()
        .filter(|id| sessions.contains(*id) && compact == switched.contains(*id))
        .collect();
    let mut card_sessions = HashMap::new();
    if !detailed.is_empty() {
        let mut today = session_notes.today(&*ask.wall)?;
        for id in detailed {
            let Some(setup) = session_notes.setup_of(id)? else {
                continue;
            };
            let (own, rest) = today.into_iter().partition(|o| o.session.note_id() == *id);
            today = rest;
            let wall: &oldbrainfix_core::WallClock = &*ask.wall;
            let shown = (units, wall);
            let card = SessionCardShown::read(store, &ask.t, &setup, own, shown)?;
            card_sessions.insert(id.clone(), card);
        }
    }
    Ok(CardsRead {
        notes: placed,
        sections,
        linked_from,
        card_today,
        checklists,
        shopping_lists,
        tallies,
        sessions,
        card_changes,
        card_may,
        compact,
        switched,
        glances,
        card_tallies,
        card_sessions,
    })
}

/// Which Note list `selection` shows, by the phone's names, each keeping
/// its own compact/detailed choice (#114): all Notes, or a person's while
/// `people` keeps only some, Unsorted, an Area (`area`) or a Topic. A
/// search inside one follows its choice; the trash has none.
fn cards_key(selection: &Selection, people: &PersonFilter, area: bool) -> Option<String> {
    Some(match selection {
        Selection::All if people.is_everyone() => "allNotes".to_string(),
        Selection::All => "personNotes".to_string(),
        Selection::Unsorted => "unsorted".to_string(),
        Selection::Place(id) if area => format!("area:{id}"),
        Selection::Place(id) => format!("topic:{id}"),
        _ => return None,
    })
}

/// A person in People: their picture and name, either opening their
/// Profile.
fn people_row(
    ui: &mut Ui,
    t: &L10n,
    pictures: &mut profile_view::Pictures,
    (person, newer): (&Profile, bool),
    asked: &mut Vec<String>,
) {
    let text = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    let name = profile_view::display_name(t, &person.name).to_string();
    ui.horizontal(|ui| {
        let open = t.person_open(&name);
        let picture = profile_view::person_button(ui, pictures, person, 32.0, &open);
        let line = ui.add(egui::Button::new(RichText::new(&name).color(text)).frame(false));
        if picture.clicked() || line.clicked() {
            asked.push(person.id.clone());
        }
        // Saved by a newer version of the app (ADR 0034).
        if newer {
            ui.label(RichText::new(t.newer_version_needed()).small().color(weak));
        }
    });
}

/// The names of the Areas `ids` as shown, separated by commas.
fn area_names(t: &L10n, view: &View, ids: &[String]) -> String {
    ids.iter()
        .filter_map(|id| view.area(id))
        .map(|a| area_name(t, a))
        .collect::<Vec<_>>()
        .join(", ")
}

/// Whether to block the person shown as `name` (#90, ADR 0021), as the
/// phone asks: when they manage Shared Areas this Device is in, `areas`
/// names them, and blocking leaves them.
fn block_form(ui: &mut Ui, t: &L10n, name: &str, areas: &str, actions: &mut Vec<Action>) {
    let text = ui.visuals().text_color();
    title(ui, &t.person_block_question(name));
    let (detail, verb) = if areas.is_empty() {
        (t.person_block_detail(name), t.person_block())
    } else {
        (
            t.person_block_leave_detail(name, areas),
            t.person_block_leave(),
        )
    };
    ui.label(RichText::new(detail).color(text));
    ui.horizontal(|ui| {
        if ui.button(RichText::new(t.cancel()).color(text)).clicked() {
            actions.push(Action::CancelBlock);
        }
        if destructive(ui, verb) {
            actions.push(Action::Block);
        }
    });
}

/// Whether to end the block of the person shown as `name` (#90).
fn unblock_form(ui: &mut Ui, t: &L10n, name: &str, actions: &mut Vec<Action>) {
    let text = ui.visuals().text_color();
    title(ui, &t.person_unblock_question(name));
    ui.label(RichText::new(t.person_unblock_detail()).color(text));
    ui.horizontal(|ui| {
        if ui.button(RichText::new(t.cancel()).color(text)).clicked() {
            actions.push(Action::CancelBlock);
        }
        if ui
            .button(RichText::new(t.person_unblock()).color(text))
            .clicked()
        {
            actions.push(Action::Unblock);
        }
    });
}

/// "128 Notes and 4 Routines": what emptying the trash deletes
/// (obf-1095), a count of none left out.
fn trash_counts(t: &L10n, notes: usize, routines: usize) -> String {
    let (notes, routines) = (notes as i64, routines as i64);
    match (notes, routines) {
        (_, 0) => t.desk_trash_notes(notes),
        (0, _) => t.desk_trash_routines(routines),
        _ => t.desk_trash_notes_and_routines(
            &t.desk_trash_notes(notes),
            &t.desk_trash_routines(routines),
        ),
    }
}

/// A confirm button for a destructive step: its verb on the error
/// colour (UI laws, #218).
fn destructive(ui: &mut Ui, label: &str) -> bool {
    theme::destructive(ui, true, label).clicked()
}

/// Asks for a name: `(title, verb, done)` say what for. Enter takes it.
fn name_form(
    ui: &mut Ui,
    t: &L10n,
    (heading, verb, done): (&str, &str, Action),
    (name, focus): (&mut String, bool),
    actions: &mut Vec<Action>,
) {
    title(ui, heading);
    let field = focused_field(ui, t, (&mut *name, focus), "name", t.name_hint());
    let ready = !name.trim().is_empty();
    if ready && field.lost_focus() && ui.input(|i| i.key_pressed(Key::Enter)) {
        actions.push(done.clone());
    }
    ui.horizontal(|ui| {
        cancel(ui, t, actions);
        if theme::main_action(ui, ready, verb) {
            actions.push(done);
        }
    });
}

/// Asks for the address of a link (#127): one already there is filled
/// in, `linked`, and taken off when left empty. Enter takes it.
fn link_form(
    ui: &mut Ui,
    t: &L10n,
    (address, focus): (&mut String, bool),
    linked: bool,
    actions: &mut Vec<Action>,
) {
    title(ui, t.format_link());
    let field = focused_field(ui, t, (&mut *address, focus), "link", t.link_address());
    if linked {
        let weak = ui.visuals().weak_text_color();
        ui.label(RichText::new(t.link_remove_hint()).small().color(weak));
    }
    let ready = linked || !address.trim().is_empty();
    if ready && field.lost_focus() && ui.input(|i| i.key_pressed(Key::Enter)) {
        actions.push(Action::SetLink);
    }
    ui.horizontal(|ui| {
        cancel(ui, t, actions);
        if theme::main_action(ui, ready, t.link_set()) {
            actions.push(Action::SetLink);
        }
    });
}

/// The custom Heads-up `count` `unit`s make in minutes, `None` while they
/// make none (obf-1087).
fn custom_heads_up(count: &str, unit: HeadsUpUnit, all_day: bool) -> Option<i64> {
    let count = count.parse::<i64>().ok()?;
    heads_up_keys::minutes_of(count, unit, all_day)
}

/// The custom Heads-up's dialog (obf-1087): a number, the numbers its
/// unit takes under it, the units as chips, minutes, hours, days and
/// weeks, days and weeks only for an all-day schedule; Add, or Enter in
/// the number, while they make a Heads-up.
fn custom_heads_up_form(
    ui: &mut Ui,
    t: &L10n,
    (count, focus): (&mut String, bool),
    (unit, all_day): (&mut HeadsUpUnit, bool),
    actions: &mut Vec<Action>,
) {
    let text = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    title(ui, t.heads_up_custom_title());
    let label = ui.label(RichText::new(t.heads_up_custom_count()).color(text));
    let field = ui
        .add(
            TextEdit::singleline(count)
                .id(Id::new("custom heads-up"))
                .char_limit(5)
                .text_color(text)
                .desired_width(120.0),
        )
        .labelled_by(label.id);
    // Digits only, as the phone's field takes.
    count.retain(|c| c.is_ascii_digit());
    if focus {
        field.request_focus();
    }
    ui.label(
        RichText::new(t.heads_up_custom_range(unit.most()))
            .small()
            .color(weak),
    );
    // The units' words agree with the number typed.
    let typed = count.parse::<i64>().unwrap_or(0);
    let units = heads_up_keys::units(all_day).iter().map(|u| {
        let words = match u {
            HeadsUpUnit::Minutes => t.unit_minutes(typed),
            HeadsUpUnit::Hours => t.unit_hours(typed),
            HeadsUpUnit::Days => t.unit_days(typed),
            HeadsUpUnit::Weeks => t.unit_weeks(typed),
        };
        (*u, words)
    });
    chip_row(ui, unit, units);
    let ready = custom_heads_up(count, *unit, all_day).is_some();
    if ready && field.lost_focus() && ui.input(|i| i.key_pressed(Key::Enter)) {
        actions.push(Action::AddCustomHeadsUp);
    }
    ui.horizontal(|ui| {
        cancel(ui, t, actions);
        if theme::main_action(ui, ready, t.add()) {
            actions.push(Action::AddCustomHeadsUp);
        }
    });
}

/// How an Area is shared: the role, and the button that shows the
/// invite's code. Nobody types a name: the other person's Profile shows
/// when their phone joins, to confirm (ADR 0017). Below, "Share with…"
/// gives it with the same role to a person in People who is not nearby
/// (#108), when there is anybody it can go to.
fn share_form(
    ui: &mut Ui,
    t: &L10n,
    (role, afar, advanced): (&mut AreaRole, bool, bool),
    actions: &mut Vec<Action>,
) {
    let text = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    ui.label(RichText::new(t.share_host_intro()).color(weak));
    // Roles are chosen only in Advanced (#197); in Simple the person
    // joins as a Member.
    if advanced {
        ui.label(RichText::new(t.role_heading()).strong().color(text));
        for (choice, label, detail) in [
            (AreaRole::Member, t.role_member(), t.role_member_detail()),
            (AreaRole::Manager, t.role_manager(), t.role_manager_detail()),
        ] {
            ui.radio_value(role, choice, RichText::new(label).color(text));
            ui.label(RichText::new(detail).small().color(weak));
        }
    } else {
        *role = AreaRole::Member;
    }
    ui.horizontal(|ui| {
        cancel(ui, t, actions);
        if ui
            .button(RichText::new(t.share_show_code()).color(text))
            .clicked()
        {
            actions.push(Action::StartInvite);
        }
    });
    ui.separator();
    ui.label(RichText::new(t.share_afar_heading()).strong().color(text));
    let intro = if afar {
        t.share_afar_intro()
    } else {
        t.share_afar_nobody()
    };
    ui.label(RichText::new(intro).color(weak));
    if afar
        && ui
            .button(RichText::new(t.share_afar_pick()).color(text))
            .clicked()
    {
        actions.push(Action::ShareAfar);
    }
}

/// "Share Household with…" (#108): the People the Area can go to from
/// afar, each with their picture and name as the user sees them and "Not
/// verified" under those whose code was never compared in person; a
/// click picks them.
fn share_person_form(
    ui: &mut Ui,
    t: &L10n,
    tones: Tones,
    (area, people): (&str, &[AfarPerson]),
    pictures: &mut profile_view::Pictures,
    actions: &mut Vec<Action>,
) {
    let text = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    title(ui, &t.share_with_title(area));
    egui::ScrollArea::vertical()
        .id_salt("share with")
        .max_height(420.0)
        .show(ui, |ui| {
            for person in people {
                let name = profile_view::display_name(t, &person.shown.name);
                let id = Id::new(("share to", &person.id));
                let clicked = clickable_card(ui, tones, (id, name), |ui| {
                    ui.horizontal(|ui| {
                        profile_view::person_picture(ui, pictures, &person.shown, 40.0, name);
                        ui.add_space(8.0);
                        ui.vertical(|ui| {
                            ui.label(RichText::new(name).color(text));
                            if !person.verified {
                                ui.label(RichText::new(t.share_not_verified()).small().color(weak));
                            }
                        });
                    });
                });
                if clicked {
                    actions.push(Action::ShareTo(person.id.clone()));
                }
            }
        });
    cancel(ui, t, actions);
}

/// "How do changes travel with Ann?" (#108), asked once per person: a
/// shared folder both reach, or files through a messenger.
fn transport_form(
    ui: &mut Ui,
    t: &L10n,
    name: &str,
    transport: &mut Transport,
    actions: &mut Vec<Action>,
) {
    let text = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    title(ui, &t.transport_title(name));
    for (choice, label, detail) in [
        (
            Transport::Folder,
            t.transport_folder(),
            t.transport_folder_detail(),
        ),
        (
            Transport::Bundle,
            t.transport_bundle(),
            t.transport_bundle_detail(),
        ),
    ] {
        ui.radio_value(transport, choice, RichText::new(label).color(text));
        ui.label(RichText::new(detail).small().color(weak));
    }
    ui.horizontal(|ui| {
        cancel(ui, t, actions);
        if ui
            .button(RichText::new(t.invite_confirm_share()).strong().color(text))
            .clicked()
        {
            actions.push(Action::ShareAfarNow);
        }
    });
}

/// The name of the Area `held` offers as the user reads it, or "an
/// Area" when the roles left the name out.
fn offer_area(t: &L10n, held: &HeldAreaOffer) -> String {
    let area = offered_area_name(t, held.area_starter.as_deref(), &held.area_name);
    if area.is_empty() {
        t.area_offer_no_name().to_string()
    } else {
        area
    }
}

/// "Ann shares Household with you as Member" for the offer `held`.
fn offer_line(t: &L10n, held: &HeldAreaOffer) -> String {
    let role = match held.role {
        AreaRole::Manager => t.role_manager(),
        AreaRole::Member => t.role_member(),
    };
    t.area_offer_text(
        profile_view::display_name(t, &held.sender.name),
        &offer_area(t, held),
        role,
    )
}

/// The preview of an Area shared with the user from afar (#108, ADR
/// 0023): who shares it, with their picture, verified or not with its
/// short code, the Area and the role it comes with, and how changes
/// travel; nothing of it is kept before Accept. "Compare codes" marks the
/// sharer verified on Accept, as for a Sent Item (#51). Leaving decides
/// nothing: the offer waits behind the Agenda's "x shared Areas waiting".
fn area_offer_form(
    ui: &mut Ui,
    t: &L10n,
    (held, compared): (&HeldAreaOffer, Compared),
    pictures: &mut profile_view::Pictures,
    actions: &mut Vec<Action>,
) {
    let text = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    let name = profile_view::display_name(t, &held.sender.name).to_string();
    let line = offer_line(t, held);
    ui.horizontal(|ui| {
        // A sharer kept here opens their Profile (#52); one not kept yet
        // has nothing to open until accepted.
        if held.trust == SenderTrust::Unknown {
            profile_view::person_picture(ui, pictures, &held.sender, 40.0, &name);
        } else if profile_view::person_button(
            ui,
            pictures,
            &held.sender,
            40.0,
            &t.person_open(&name),
        )
        .clicked()
        {
            actions.push(Action::OpenPerson(held.sender.id.clone()));
        }
        ui.add_space(8.0);
        ui.add(egui::Label::new(RichText::new(&line).strong().size(18.0).color(text)).wrap());
    });
    let code = &held.code;
    let trust = if compared == Compared::Match {
        SenderTrust::Verified
    } else {
        held.trust
    };
    let said = match trust {
        SenderTrust::Verified => t.sent_item_verified(code),
        SenderTrust::Known => t.sent_item_known(code),
        SenderTrust::Unknown => t.sent_item_unknown(code),
    };
    ui.label(RichText::new(said).color(text));
    match compared {
        Compared::Match if held.trust != SenderTrust::Verified => {
            ui.label(
                RichText::new(t.sent_item_verified_on_accept())
                    .small()
                    .color(weak),
            );
        }
        Compared::Differ => {
            ui.label(
                RichText::new(t.sent_item_codes_differed()).color(ui.visuals().hyperlink_color),
            );
        }
        Compared::Asking => {
            ui.label(RichText::new(t.sent_item_compare_hint(&name, code)).color(text));
            ui.horizontal(|ui| {
                if ui
                    .button(RichText::new(t.sent_item_codes_match()).color(text))
                    .clicked()
                {
                    actions.push(Action::CodesCompared(true));
                }
                if ui
                    .button(RichText::new(t.sent_item_codes_differ()).color(text))
                    .clicked()
                {
                    actions.push(Action::CodesCompared(false));
                }
            });
        }
        _ => {}
    }
    if trust != SenderTrust::Verified
        && compared != Compared::Asking
        && ui
            .button(RichText::new(t.sent_item_compare()).color(text))
            .clicked()
    {
        actions.push(Action::CompareCodes);
    }
    let travel = match held.transport {
        Transport::Folder => t.area_offer_by_folder(),
        Transport::Bundle => t.area_offer_by_bundle(),
    };
    ui.label(RichText::new(travel).color(text));
    ui.label(
        RichText::new(t.area_offer_keeps_nothing())
            .small()
            .color(weak),
    );
    ui.horizontal(|ui| {
        if ui
            .button(RichText::new(t.sent_item_accept()).strong().color(text))
            .clicked()
        {
            actions.push(Action::AcceptOffer);
        }
        if ui
            .button(RichText::new(t.sent_item_decline()).color(text))
            .clicked()
        {
            actions.push(Action::DeclineOffer);
        }
    });
    if ui
        .button(RichText::new(t.sent_item_block()).color(text))
        .clicked()
    {
        actions.push(Action::AskBlockSender);
    }
}

/// Asks whom a Note is sent to: one of the people whose keys are known
/// here, encrypted to them, or anyone, signed only, with a hint that
/// whoever holds the file can read it. Send waits for a pick (#288).
fn send_form(
    ui: &mut Ui,
    t: &L10n,
    recipients: &[Recipient],
    (picked, update, cancelling): (&mut SendTo, bool, &mut bool),
    actions: &mut Vec<Action>,
) {
    let text = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    title(
        ui,
        if update {
            t.send_update()
        } else {
            t.send_title()
        },
    );
    ui.label(RichText::new(t.send_who()).color(text));
    for (i, r) in recipients.iter().enumerate() {
        ui.radio_value(
            picked,
            SendTo::Person(i),
            RichText::new(t.send_encrypted(profile_view::display_name(t, &r.name))).color(text),
        );
    }
    ui.radio_value(
        picked,
        SendTo::Anyone,
        RichText::new(t.send_anyone()).color(text),
    );
    if *picked == SendTo::Anyone {
        ui.label(RichText::new(t.send_plain_hint()).color(text));
    }
    if update {
        theme::checkbox(ui, cancelling, RichText::new(t.send_cancel()).color(text));
        ui.label(RichText::new(t.send_cancel_hint()).small().color(weak));
    }
    ui.label(RichText::new(t.send_what()).small().color(weak));
    ui.horizontal(|ui| {
        cancel(ui, t, actions);
        if theme::main_action(ui, *picked != SendTo::Nobody, t.send_action()) {
            actions.push(Action::SendNote);
        }
    });
}

/// Why a Sent Item was refused as `error` says, and what to do, as the
/// phone's `_refused`.
fn refused(t: &L10n, error: OpenError) -> (&'static str, &'static str) {
    match error {
        OpenError::NotForUs => (t.sent_item_not_for_us(), t.sent_item_ask_again_fix()),
        OpenError::NotASentItem => (t.sent_item_unreadable(), t.sent_item_ask_again_fix()),
        OpenError::NeedsUpdate => (t.sent_item_needs_update(), t.update_open_again_fix()),
        OpenError::NotFromSender => (t.sent_item_not_from_sender(), t.sent_item_ask_again_fix()),
        OpenError::FromBlocked => (t.sent_item_from_blocked(), t.blocked_fix()),
    }
}

/// Whether accepting a Sent Item in `state` does anything: a new one,
/// an update or a cancellation.
fn acceptable(state: SentItemState) -> bool {
    matches!(
        state,
        SentItemState::Fresh | SentItemState::Update | SentItemState::Cancel
    )
}

/// The preview of a Sent Item: who sent it, with their Profile's picture
/// and name, verified or not with its short code, whether it came
/// encrypted, its text, Routines and Reminders with their times and
/// Sections; Accept or Decline. "Compare codes" asks the user to compare
/// the code with the sender in person; a match marks the Profile verified
/// on accept (ADR 0017, #51). An update shows what changes, "Tue 10:00 →
/// Wed 14:00", and Apply; a cancellation what it cancels; one already up
/// to date or with nothing to cancel only closes.
fn sent_item_form(
    ui: &mut Ui,
    t: &L10n,
    tones: Tones,
    ((opened, compared, may_block), pictures): (
        (&Opened, Compared, bool),
        &mut profile_view::Pictures,
    ),
    actions: &mut Vec<Action>,
) {
    let text = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    let item = &opened.item;
    let name = profile_view::display_name(t, &opened.sender.name).to_string();
    ui.horizontal(|ui| {
        // A sender kept here opens their Profile (#52); one not kept has
        // nothing to open until the item is accepted.
        if opened.trust == SenderTrust::Unknown {
            profile_view::person_picture(ui, pictures, &opened.sender, 40.0, &name);
        } else if profile_view::person_button(
            ui,
            pictures,
            &opened.sender,
            40.0,
            &t.person_open(&name),
        )
        .clicked()
        {
            actions.push(Action::OpenPerson(opened.sender.id.clone()));
        }
        ui.add_space(8.0);
        title(ui, &t.sent_item_from(&name));
    });
    let code = &opened.code;
    let trust = if compared == Compared::Match {
        SenderTrust::Verified
    } else {
        opened.trust
    };
    let said = match trust {
        SenderTrust::Verified => t.sent_item_verified(code),
        SenderTrust::Known => t.sent_item_known(code),
        SenderTrust::Unknown => t.sent_item_unknown(code),
    };
    ui.label(RichText::new(said).color(text));
    let acceptable = acceptable(opened.state);
    match compared {
        Compared::Match if opened.trust != SenderTrust::Verified => {
            ui.label(
                RichText::new(t.sent_item_verified_on_accept())
                    .small()
                    .color(weak),
            );
        }
        Compared::Differ => {
            ui.label(
                RichText::new(t.sent_item_codes_differed()).color(ui.visuals().hyperlink_color),
            );
        }
        Compared::Asking => {
            ui.label(RichText::new(t.sent_item_compare_hint(&name, code)).color(text));
            ui.horizontal(|ui| {
                if ui
                    .button(RichText::new(t.sent_item_codes_match()).color(text))
                    .clicked()
                {
                    actions.push(Action::CodesCompared(true));
                }
                if ui
                    .button(RichText::new(t.sent_item_codes_differ()).color(text))
                    .clicked()
                {
                    actions.push(Action::CodesCompared(false));
                }
            });
        }
        _ => {}
    }
    if acceptable
        && trust != SenderTrust::Verified
        && compared != Compared::Asking
        && ui
            .button(RichText::new(t.sent_item_compare()).color(text))
            .clicked()
    {
        actions.push(Action::CompareCodes);
    }
    let sealed = if opened.encrypted {
        t.sent_item_encrypted()
    } else {
        t.sent_item_plain()
    };
    ui.label(RichText::new(sealed).small().color(weak));
    match opened.state {
        SentItemState::Fresh => {}
        SentItemState::Update => {
            ui.label(RichText::new(t.sent_item_update()).color(ui.visuals().hyperlink_color));
        }
        SentItemState::Cancel => {
            ui.label(
                RichText::new(
                    t.sent_item_cancelled(&text_format::visible(&item.text_format, &item.text)),
                )
                .strong()
                .color(ui.visuals().hyperlink_color),
            );
            ui.label(RichText::new(t.sent_item_cancel_detail()).color(text));
        }
        SentItemState::UpToDate => {
            ui.label(RichText::new(t.sent_item_already()).color(ui.visuals().hyperlink_color));
        }
        SentItemState::NothingToCancel => {
            ui.label(
                RichText::new(t.sent_item_nothing_to_cancel()).color(ui.visuals().hyperlink_color),
            );
        }
    }
    let accept = match opened.state {
        SentItemState::Fresh => Some(t.sent_item_accept()),
        SentItemState::Update => Some(t.sent_item_apply()),
        SentItemState::Cancel => Some(t.sent_item_accept_cancel()),
        SentItemState::UpToDate | SentItemState::NothingToCancel => None,
    };
    ui.horizontal(|ui| {
        if let Some(accept) = accept
            && ui
                .button(RichText::new(accept).strong().color(text))
                .clicked()
        {
            actions.push(Action::AcceptSent);
        }
        let decline = if accept.is_some() {
            t.sent_item_decline()
        } else {
            t.close()
        };
        if ui.button(RichText::new(decline).color(text)).clicked() {
            actions.push(Action::DeclineSent);
        }
    });
    if may_block
        && ui
            .button(RichText::new(t.sent_item_block()).color(text))
            .clicked()
    {
        actions.push(Action::AskBlockSender);
    }
    let full = matches!(opened.state, SentItemState::Fresh | SentItemState::Update);
    egui::ScrollArea::vertical()
        .id_salt("sent item")
        .max_height(360.0)
        .show(ui, |ui| {
            if let Some(changes) = &opened.changes {
                ui.label(RichText::new(t.sent_item_changes()).strong().color(text));
                let mut line = |said: String| {
                    ui.label(RichText::new(said).color(text));
                };
                if changes.restores {
                    line(t.sent_item_restores().to_string());
                }
                if let Some(before) = &changes.text_before {
                    line(t.sent_item_text_was(before));
                    line(
                        t.sent_item_text_now(&text_format::visible(&item.text_format, &item.text)),
                    );
                    if changes.text_edited {
                        line(t.sent_item_text_yours().to_string());
                    }
                }
                if changes.makes_checklist {
                    line(t.sent_item_makes_checklist().to_string());
                }
                if changes.makes_shopping_list {
                    line(t.sent_item_makes_shopping_list().to_string());
                }
                if changes.makes_plain {
                    line(t.sent_item_makes_plain().to_string());
                }
                for l in &changes.lines_added {
                    line(t.sent_item_line_added(&l.text));
                }
                for r in &changes.lines_renamed {
                    line(t.sent_item_line_renamed(&r.before, &r.after));
                }
                for l in &changes.lines_removed {
                    line(t.sent_item_line_removed(&l.text));
                }
                for s in &changes.sections_added {
                    line(t.sent_item_section_added(&text_format::visible(&s.format, &s.text)));
                }
                for r in &changes.rescheduled {
                    line(t.sent_item_rescheduled(
                        &schedule_text(t, &r.before),
                        &schedule_text(t, &r.after),
                    ));
                }
                for r in &changes.routines_added {
                    line(t.sent_item_routine_added(&schedule_text(t, &r.schedule)));
                }
                for r in &changes.routines_removed {
                    line(t.sent_item_routine_removed(&schedule_text(t, &r.schedule)));
                }
                if changes.is_empty() {
                    line(t.sent_item_no_changes().to_string());
                }
                ui.label(RichText::new(t.sent_item_keeps()).small().color(weak));
                ui.separator();
            }
            // Formatted as it reads; its tags are not followed before it
            // is taken, its links open (#127).
            let shown = (0, item.text.len());
            // Its boxes as the sender left them, never ticked here.
            let unticked = BoxLook::default();
            let spots = text_marks_view::formatted_label(
                ui,
                (&item.text, &item.text_format, &unticked),
                shown,
                (None, text),
                false,
            );
            let of = Id::new("sent text");
            if let Some((at, act)) = text_marks_view::table_clicks(ui, t, of, &spots.tables, false)
            {
                actions.extend(table_action(
                    act,
                    Opening {
                        note: None,
                        text: item.text.clone(),
                        at,
                        cell: None,
                        tags: false,
                        boxes: None,
                    },
                    &unticked,
                ));
            }
            text_marks_view::link_clicks(ui, of, &spots.links);
            if !full {
                return;
            }
            // The Lines of a Checklist or a Shopping List, to look at,
            // not to check; a Shopping List's with its reappear time.
            if let Some(lines) = &item.lines {
                checklist_view::preview(ui, (t, tones), lines);
            }
            if !item.routines.is_empty() {
                ui.label(RichText::new(t.routines_heading()).strong().color(text));
                for r in &item.routines {
                    ui.label(RichText::new(schedule_text(t, &r.schedule)).color(text));
                }
            }
            for (i, section) in item.sections.iter().enumerate() {
                ui.separator();
                let shown = (0, section.text.len());
                let spots = text_marks_view::formatted_label(
                    ui,
                    (&section.text, &section.format, &unticked),
                    shown,
                    (None, text),
                    false,
                );
                let of = Id::new(("sent section", i));
                if let Some((at, act)) =
                    text_marks_view::table_clicks(ui, t, of, &spots.tables, false)
                {
                    actions.extend(table_action(
                        act,
                        Opening {
                            note: None,
                            text: section.text.clone(),
                            at,
                            cell: None,
                            tags: false,
                            boxes: None,
                        },
                        &unticked,
                    ));
                }
                text_marks_view::link_clicks(ui, of, &spots.links);
            }
        });
}

/// A card with `icon` and `said` on the Agenda, "x Unsorted" or "x Sent
/// Items waiting"; whether it was clicked.
fn count_banner(ui: &mut Ui, tones: Tones, (id, icon): (Id, char), said: &str) -> bool {
    let text = ui.visuals().text_color();
    clickable_card(ui, tones, (id, said), |ui| {
        ui.horizontal(|ui| {
            icons::show(ui, icon, 20.0, tones.accent);
            ui.label(RichText::new(said).color(text));
        });
    })
}

/// The quiet day's line on top of the Agenda (obf-1044), a card as "x
/// Sent Items waiting" but not clicked as a whole: "Quiet day until
/// midnight" and End, which ends it now.
fn quiet_day_line(ui: &mut Ui, t: &L10n, tones: Tones, actions: &mut Vec<Action>) {
    let text = ui.visuals().text_color();
    embossed(ui, tones, false, None, |ui| {
        ui.horizontal(|ui| {
            icons::show(ui, icons::NOTIFICATIONS_OFF, 20.0, tones.accent);
            ui.label(RichText::new(t.quiet_day_line()).color(text));
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                if ui
                    .button(RichText::new(t.quiet_day_end()).color(text))
                    .clicked()
                {
                    actions.push(Action::EndQuietDay);
                }
            });
        });
    });
}

/// An embossed card holding `content` that is clicked as a whole, a
/// button with `id` labelled `label`; whether it was clicked.
pub(crate) fn clickable_card(
    ui: &mut Ui,
    tones: Tones,
    (id, label): (Id, &str),
    content: impl FnOnce(&mut Ui),
) -> bool {
    banded_clickable_card(ui, tones, (id, label), None, content)
}

/// A [`clickable_card`] with an Area's colour `band` down its left side,
/// as an Agenda row has it.
pub(crate) fn banded_clickable_card(
    ui: &mut Ui,
    tones: Tones,
    (id, label): (Id, &str),
    band: Option<Color32>,
    content: impl FnOnce(&mut Ui),
) -> bool {
    let card = embossed(ui, tones, false, band, content);
    let card = ui.interact(card.rect, id, Sense::click());
    card.widget_info(|| WidgetInfo::labeled(WidgetType::Button, true, label));
    card.on_hover_cursor(egui::CursorIcon::PointingHand)
        .clicked()
}

/// The preview of a stranger's Sent Item held until "Show" (#91, ADR
/// 0015, 0022): only who it is from and that they are unknown here, not
/// their picture or short code, nothing of what it holds. "Show" opens
/// the preview as for anybody else; Accept, Decline and "Decline and
/// block" work before it too. Leaving decides nothing: the item waits
/// behind the Agenda's "x Sent Items waiting".
fn held_sent_item_form(ui: &mut Ui, t: &L10n, held: &HeldSentItem, actions: &mut Vec<Action>) {
    let text = ui.visuals().text_color();
    let name = profile_view::display_name(t, &held.sender.name);
    title(ui, &t.sent_item_from(name));
    ui.label(RichText::new(t.sent_item_stranger()).color(ui.visuals().hyperlink_color));
    ui.label(RichText::new(t.sent_item_hidden()).color(text));
    let wide = |ui: &mut Ui, label: RichText| {
        ui.add_sized([ui.available_width(), 32.0], egui::Button::new(label))
            .clicked()
    };
    if wide(ui, RichText::new(t.sent_item_show()).strong().color(text)) {
        actions.push(Action::ShowSent);
    }
    ui.horizontal(|ui| {
        if ui
            .button(RichText::new(t.sent_item_accept()).color(text))
            .clicked()
        {
            actions.push(Action::AcceptSent);
        }
        if ui
            .button(RichText::new(t.sent_item_decline()).color(text))
            .clicked()
        {
            actions.push(Action::DeclineSent);
        }
    });
    if ui
        .button(RichText::new(t.sent_item_block()).color(text))
        .clicked()
    {
        actions.push(Action::AskBlockSender);
    }
}

/// The people of a Shared Area with their roles, on its Share with
/// people… page (obf-1014); a Manager changes them and takes them out
/// here.
fn people_form(
    ui: &mut Ui,
    t: &L10n,
    area: &str,
    (people, names, mine): (
        &[Person],
        &std::collections::HashMap<String, String>,
        Option<&str>,
    ),
    (shown, pictures): (
        &std::collections::HashMap<String, Profile>,
        &mut profile_view::Pictures,
    ),
    (manages, advanced): (bool, bool),
    actions: &mut Vec<Action>,
) {
    let text = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    ui.label(RichText::new(t.people_title()).strong().color(text));
    ui.label(RichText::new(t.people_intro()).small().color(weak));
    for person in people {
        let own = Some(person.id.as_str()) == mine;
        let name = person_name(t, names, person);
        let name = if own { t.people_you(&name) } else { name };
        // A role a newer version of the app gave is kept as it is, and
        // nothing here changes it (ADR 0034).
        let role = match person.role {
            Some(AreaRole::Manager) => t.role_manager(),
            Some(AreaRole::Member) => t.role_member(),
            None => t.newer_version_needed(),
        };
        ui.horizontal(|ui| {
            // Another person's picture opens their Profile (#52).
            if let Some(profile) = shown.get(&person.id) {
                if own {
                    profile_view::person_picture(ui, pictures, profile, 32.0, &name);
                } else if profile_view::person_button(
                    ui,
                    pictures,
                    profile,
                    32.0,
                    &t.person_open(&name),
                )
                .clicked()
                {
                    actions.push(Action::OpenPerson(person.id.clone()));
                }
            }
            ui.label(RichText::new(&name).color(text));
            ui.label(RichText::new(role).small().color(weak));
            let (label, next) = match person.role {
                _ if !manages || own => return,
                Some(AreaRole::Member) => (t.make_manager(), AreaRole::Manager),
                Some(AreaRole::Manager) => (t.make_member(), AreaRole::Member),
                None => return,
            };
            // Roles are changed only in Advanced (#197).
            if advanced && ui.button(RichText::new(label).color(text)).clicked() {
                actions.push(Action::SetRole {
                    area: area.to_string(),
                    person: person.id.clone(),
                    role: next,
                });
            }
            if theme::destructive(ui, true, t.remove_person()).clicked() {
                actions.push(Action::AskRemovePerson {
                    area: area.to_string(),
                    person: person.id.clone(),
                });
            }
        });
    }
}

/// An Area's name, colour and icon in one dialog (obf-1014): its name
/// over the colours and icons, each marked as it is picked and kept with
/// Save, or Enter in the name; Cancel keeps none of them.
fn area_look_form(
    ui: &mut Ui,
    t: &L10n,
    (name, focus): (&mut String, bool),
    look: &mut AreaLook,
    actions: &mut Vec<Action>,
) {
    let text = ui.visuals().text_color();
    title(ui, t.desk_area_look_title());
    let field = focused_field(ui, t, (&mut *name, focus), "name", t.name_hint());
    let ready = !name.trim().is_empty();
    if ready && field.lost_focus() && ui.input(|i| i.key_pressed(Key::Enter)) {
        actions.push(Action::SaveName);
    }
    ui.add_space(8.0);
    ui.label(RichText::new(t.colour_heading()).strong().color(text));
    ui.horizontal_wrapped(|ui| {
        let none = look.colour.is_none();
        if ui
            .add(egui::Button::selectable(
                none,
                RichText::new(t.no_colour()).color(text),
            ))
            .clicked()
        {
            look.colour = None;
        }
        for hex in AREA_PALETTE {
            let on = look.colour.as_deref() == Some(hex);
            let colour = area_colour(Some(hex)).unwrap_or(text);
            if swatch(ui, hex, on, |painter, rect| {
                painter.circle_filled(rect.center(), rect.width() / 2.0 - 3.0, colour);
            })
            .clicked()
            {
                look.colour = Some(hex.to_string());
            }
        }
    });
    ui.label(RichText::new(t.icon_heading()).strong().color(text));
    ui.horizontal_wrapped(|ui| {
        let none = look.icon.is_none();
        if ui
            .add(egui::Button::selectable(
                none,
                RichText::new(t.no_icon()).color(text),
            ))
            .clicked()
        {
            look.icon = None;
        }
        for key in AREA_ICONS {
            let Some(glyph) = icons::area_icon(Some(key)) else {
                continue;
            };
            let on = look.icon.as_deref() == Some(key);
            if swatch(ui, key, on, |painter, rect| {
                icons::paint(painter, rect.shrink(5.0), glyph, text);
            })
            .clicked()
            {
                look.icon = Some(key.to_string());
            }
        }
    });
    ui.add_space(8.0);
    ui.horizontal(|ui| {
        cancel(ui, t, actions);
        if theme::main_action(ui, ready, t.save()) {
            actions.push(Action::SaveName);
        }
    });
}

/// A round choice called `label`, ringed while it is `on`.
fn swatch(
    ui: &mut Ui,
    label: &str,
    on: bool,
    paint: impl FnOnce(&egui::Painter, egui::Rect),
) -> egui::Response {
    let (rect, resp) = ui.allocate_exact_size(egui::vec2(32.0, 32.0), Sense::click());
    resp.widget_info(|| WidgetInfo::selected(WidgetType::Button, true, on, label));
    paint(ui.painter(), rect);
    if on || resp.hovered() {
        let ring = if on {
            ui.visuals().text_color()
        } else {
            ui.visuals().weak_text_color()
        };
        ui.painter().circle_stroke(
            rect.center(),
            rect.width() / 2.0 - 1.0,
            egui::Stroke::new(2.0, ring),
        );
    }
    resp
}

/// Asks once whether to delete an Area or Topic and, with Notes inside,
/// where they go: Unsorted, the Topic's Area or the trash.
fn delete_form(ui: &mut Ui, t: &L10n, deleting: &Deleting, actions: &mut Vec<Action>) {
    let text = ui.visuals().text_color();
    title(ui, &deleting.question);
    for line in &deleting.lines {
        ui.label(RichText::new(line).color(text));
    }
    ui.horizontal_wrapped(|ui| {
        cancel(ui, t, actions);
        if !deleting.has_notes {
            if destructive(ui, t.delete()) {
                actions.push(Action::DeletePlace(NotesGo::Unsorted));
            }
            return;
        }
        if destructive(ui, t.move_to_unsorted()) {
            actions.push(Action::DeletePlace(NotesGo::Unsorted));
        }
        if let Some(area) = &deleting.area
            && destructive(ui, &t.move_to_area(area))
        {
            actions.push(Action::DeletePlace(NotesGo::Area));
        }
        if destructive(ui, t.trash_them()) {
            actions.push(Action::DeletePlace(NotesGo::Trash));
        }
    });
}

/// Picks the Note to merge the selected one into, from every other Note,
/// newest first, narrowed by what their text holds.
fn merge_form(
    ui: &mut Ui,
    t: &L10n,
    tones: Tones,
    (query, focus): (&mut String, bool),
    others: &[(String, String)],
    actions: &mut Vec<Action>,
) {
    let weak = ui.visuals().weak_text_color();
    title(ui, t.merge_into());
    // On its band, so the Notes scroll under its line (obf-1088).
    let field = theme::search_band(ui, |ui| {
        focused_field(
            ui,
            t,
            (&mut *query, focus),
            "merge query",
            t.search_all_hint(),
        )
    });
    if field.changed() {
        actions.push(Action::MergeQuery);
    }
    // Ctrl+Enter merges into the first Note found, once something is
    // typed to find it by (#277).
    if !query.trim().is_empty()
        && let Some((id, _)) = others.first()
        && theme::ctrl_enter(ui)
    {
        actions.push(Action::Merge(id.clone()));
    }
    // The core's search, as on the phone: Transcripts, Photo Texts and
    // Sections count too.
    let mut shown = others.iter().peekable();
    if shown.peek().is_none() {
        let empty = if query.trim().is_empty() {
            t.no_other_notes()
        } else {
            t.nothing_found()
        };
        ui.add_space(4.0);
        ui.label(RichText::new(empty).color(weak));
    }
    egui::ScrollArea::vertical()
        .id_salt("merge")
        .max_height(320.0)
        .show(ui, |ui| {
            // Room under the band's line, inside, so the list is cut there.
            ui.add_space(4.0);
            for (id, text) in shown {
                if merge_row(ui, tones, text).clicked() {
                    actions.push(Action::Merge(id.clone()));
                }
            }
        });
    cancel(ui, t, actions);
}
/// How much tomorrow and the days after are faded on the Agenda (the
/// phone's `tomorrowOpacity`).
pub const TOMORROW_OPACITY: f32 = 0.55;

/// How many days the Agenda shows, today included (the phone's
/// `AgendaScreen.days`).
const AGENDA_DAYS: usize = 7;

/// The name `person`'s Profile shows (`names`, by Profile id), or "No
/// name".
fn person_name(
    t: &L10n,
    names: &std::collections::HashMap<String, String>,
    person: &Person,
) -> String {
    let name = names.get(&person.id).map_or("", String::as_str);
    profile_view::display_name(t, name).to_string()
}

/// Whether the Settings record the hotkey from the keys pressed (#283),
/// and whether its button was drawn since the keys were last read.
#[derive(Debug, Default)]
struct HotkeyRecording {
    on: bool,
    drawn: bool,
}

/// The Settings' card on the capture popup's hotkey and the
/// `oldbrainfix capture` command: the chord as typed, Record keys, which
/// records it from the keys pressed (#283), and how the hotkey stands on
/// this desktop.
fn quick_capture_card(
    ui: &mut Ui,
    t: &L10n,
    (typed, recording): (&mut String, &mut HotkeyRecording),
    (stored, status): (&str, Option<hotkey::Status>),
    actions: &mut Vec<Action>,
) {
    let text = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    ui.label(
        RichText::new(t.quick_capture_heading())
            .strong()
            .color(text),
    );
    let mut chord = None;
    ui.horizontal(|ui| {
        ui.label(RichText::new(t.hotkey_label()).color(text));
        let field = ui.add(
            TextEdit::singleline(typed)
                .id(Id::new("hotkey"))
                .hint_text(oldbrainfix_core::settings::DEFAULT_CAPTURE_HOTKEY)
                .text_color(text)
                .desired_width(180.0),
        );
        text_menu::show(ui, t, &field, typed);
        chord = typed.parse::<Chord>().ok();
        // Kept once typed out, so no key on the way is grabbed.
        if field.lost_focus()
            && let Some(chord) = chord
            && chord.to_string() != stored
        {
            actions.push(Action::Setting(Setting::Hotkey(chord.to_string())));
        }
        recording.drawn = true;
        let label = if recording.on {
            t.hotkey_recording()
        } else {
            t.hotkey_record()
        };
        let mut button = egui::Button::new(RichText::new(label).color(text));
        if recording.on {
            let ring = ui.visuals().selection.stroke.color;
            button = button.stroke(egui::Stroke::new(2.0, ring));
        }
        let record = ui.add(button);
        if record.clicked() {
            actions.push(Action::RecordHotkey(!recording.on));
        } else if recording.on && ui.input(|i| i.pointer.any_pressed()) && !record.hovered() {
            // A click elsewhere stops it, as it leaves a field.
            actions.push(Action::RecordHotkey(false));
        }
    });
    if recording.on {
        ui.label(RichText::new(t.hotkey_recording_hint()).small().color(weak));
    }
    let line = match (chord, status) {
        (None, _) => {
            ui.label(RichText::new(t.hotkey_invalid()).color(ui.visuals().error_fg_color));
            None
        }
        (Some(_), None) => None,
        (Some(_), Some(hotkey::Status::Active)) => Some(t.hotkey_active().to_string()),
        (Some(_), Some(hotkey::Status::Waiting)) => Some(t.hotkey_waiting().to_string()),
        (Some(_), Some(hotkey::Status::Desktop(key))) => Some(match key {
            Some(key) => format!("{} {}", t.hotkey_desktop(), t.hotkey_desktop_key(&key)),
            None => t.hotkey_desktop().to_string(),
        }),
        (Some(_), Some(hotkey::Status::Taken)) => Some(t.hotkey_taken().to_string()),
        (Some(_), Some(hotkey::Status::Unavailable)) => Some(t.hotkey_unavailable().to_string()),
    };
    if let Some(line) = line {
        ui.label(RichText::new(line).small().color(weak));
    }
    ui.label(RichText::new(t.capture_command()).small().color(weak));
}

/// Which rows of the quick note's card the search `query` shows (#282):
/// its detail line and the Nudge buttons, in order.
fn quick_note_shows(query: &str, t: &L10n) -> [bool; 2] {
    let whole = settings_search::heading_matches(query, Some(t.settings_quick_note()));
    let shows = |words: &[&str]| whole || settings_search::matches(words, query);
    [
        shows(&[t.settings_quick_note_detail_device()]),
        shows(&[
            t.quick_note_nudge_buttons(),
            t.quick_note_nudge_buttons_detail(),
        ]),
    ]
}

/// The Settings' card on what the quick note, its dialog in the window
/// and the popup, shows besides its text and Open in the editor (#142,
/// #352): the Nudge buttons, on until switched off; of it the rows
/// `shows` (#282). The switches for File into…, the Frog and Session, Add to a Shopping
/// List, the Importance and the format bar went with those controls
/// into the Note dialog; what they stored stays, unused.
fn quick_note_card(
    ui: &mut Ui,
    t: &L10n,
    (quick, shows): (&QuickNote, &[bool; 2]),
    actions: &mut Vec<Action>,
) {
    let text = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    ui.label(RichText::new(t.settings_quick_note()).strong().color(text));
    if shows[0] {
        ui.label(
            RichText::new(t.settings_quick_note_detail_device())
                .small()
                .color(weak),
        );
    }
    if !shows[1] {
        return;
    }
    let mut on = quick.nudge_buttons;
    if theme::checkbox(
        ui,
        &mut on,
        RichText::new(t.quick_note_nudge_buttons()).color(text),
    )
    .changed()
    {
        actions.push(Action::Setting(Setting::QuickNoteNudgeButtons(on)));
    }
    ui.label(
        RichText::new(t.quick_note_nudge_buttons_detail())
            .small()
            .color(weak),
    );
}

/// The Settings' Quiet Hours (`on` and the hours): their switch and,
/// while on, their From and Until as `typed`, each kept once it reads as
/// a time.
fn quiet_hours(
    ui: &mut Ui,
    t: &L10n,
    (on, quiet): (bool, QuietHours),
    typed: &mut (String, String),
    actions: &mut Vec<Action>,
) {
    let text = ui.visuals().text_color();
    let mut switched = on;
    if theme::checkbox(
        ui,
        &mut switched,
        RichText::new(t.quiet_hours()).color(text),
    )
    .changed()
    {
        actions.push(Action::Setting(Setting::QuietOn(switched)));
    }
    if !on {
        return;
    }
    let mut changed_to = None;
    ui.horizontal(|ui| {
        for (label, value, id, start) in [
            (t.quiet_from(), &mut typed.0, "quiet from", true),
            (t.quiet_until(), &mut typed.1, "quiet until", false),
        ] {
            ui.label(RichText::new(label).color(text));
            let field = ui.add(
                TextEdit::singleline(value)
                    .id(Id::new(id))
                    .hint_text(t.time_hint())
                    .text_color(text)
                    .desired_width(60.0),
            );
            text_menu::show(ui, t, &field, value);
            if field.changed()
                && let Some(time) = ClockTime::parse(value.trim())
            {
                changed_to = Some((start, time));
            }
        }
    });
    if let Some((start, time)) = changed_to {
        let changed = if start {
            QuietHours {
                start: time,
                ..quiet
            }
        } else {
            QuietHours { end: time, ..quiet }
        };
        if changed != quiet {
            actions.push(Action::Setting(Setting::Quiet(changed)));
        }
    }
    let unreadable = [&typed.0, &typed.1]
        .iter()
        .any(|v| ClockTime::parse(v.trim()).is_none());
    if unreadable {
        ui.label(RichText::new(t.time_invalid()).color(ui.visuals().error_fg_color));
    }
}

/// The Settings' alarm sound (#102): the own chime or the file chosen,
/// by its name, and whether that file plays (`rung`), with the choice of
/// another file and the way back to the own chime.
fn alarm_sound_choice(
    ui: &mut Ui,
    t: &L10n,
    sound: Option<&str>,
    rung: Option<Rung>,
    actions: &mut Vec<Action>,
) {
    let text = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    ui.label(RichText::new(t.alarm_sound()).color(text));
    match sound {
        None => {
            ui.label(RichText::new(t.alarm_sound_own()).color(text));
        }
        Some(path) => {
            let name = std::path::Path::new(path)
                .file_name()
                .map_or_else(|| path.into(), |n| n.to_string_lossy());
            ui.label(RichText::new(t.alarm_sound_file(&name)).color(text))
                .on_hover_text(path);
            if rung == Some(Rung::Own) {
                ui.label(
                    RichText::new(t.alarm_sound_unplayable()).color(ui.visuals().error_fg_color),
                );
            }
        }
    }
    ui.horizontal_wrapped(|ui| {
        if ui
            .button(RichText::new(t.alarm_sound_pick()).color(text))
            .clicked()
        {
            actions.push(Action::PickAlarmSound);
        }
        if sound.is_some()
            && ui
                .button(RichText::new(t.alarm_sound_use_own()).color(text))
                .clicked()
        {
            actions.push(Action::Setting(Setting::AlarmSound(None)));
        }
    });
    ui.label(RichText::new(t.alarm_sound_detail()).small().color(weak));
}

/// The Nudge repeats offered, in minutes (the phone's choices).
pub const NUDGE_REPEAT_CHOICES: [i64; 3] = [10, 30, 60];

/// `label`, and below it a row of choice chips for `minutes`;
/// `picked` gets a new one.
fn minutes_choice(
    ui: &mut Ui,
    label: &str,
    t: &L10n,
    minutes: i64,
    choices: &[i64],
    mut picked: impl FnMut(i64),
) {
    let text = ui.visuals().text_color();
    ui.label(RichText::new(label).color(text));
    let mut chosen = minutes;
    let options = choices.iter().map(|m| (*m, t.renag_minutes(*m)));
    if chip_row(ui, &mut chosen, options) && chosen != minutes {
        picked(chosen);
    }
}

/// A long or wordy single choice: one radio button per line, the
/// `current` one marked; a short one is a [`chip_row`]. True when a click
/// picked one.
pub(crate) fn radio_column<T: PartialEq + Copy>(
    ui: &mut Ui,
    current: &mut T,
    options: impl IntoIterator<Item = (T, String)>,
) -> bool {
    let text = ui.visuals().text_color();
    let mut changed = false;
    for (value, label) in options {
        changed |= ui
            .radio_value(current, value, RichText::new(label).color(text))
            .clicked();
    }
    changed
}

/// A short single choice (#226): a wrapping row of choice chips
/// ([`design::Chip`], obf-1081), the `current` one picked, as the
/// Routine editor's weekday chips look. A screen reader hears a radio group of radio buttons; Tab and the arrows move
/// between them, Space or Enter picks one. True when a click picked one.
pub(crate) fn chip_row<T: PartialEq + Copy>(
    ui: &mut Ui,
    current: &mut T,
    options: impl IntoIterator<Item = (T, String)>,
) -> bool {
    ui.horizontal_wrapped(|ui| {
        ui.ctx().accesskit_node_builder(ui.unique_id(), |node| {
            node.set_role(egui::accesskit::Role::RadioGroup);
        });
        let mut changed = false;
        for (value, label) in options {
            let on = *current == value;
            if design::Chip::new(&label).on(on).radio().show(ui).clicked() {
                *current = value;
                changed = true;
            }
        }
        changed
    })
    .inner
}

/// The box that checks an Occurrence off, called `label`.
pub(crate) fn check(ui: &mut Ui, tones: Tones, done: bool, label: &str) -> egui::Response {
    let (rect, resp) = ui.allocate_exact_size(egui::vec2(28.0, 28.0), Sense::click());
    resp.widget_info(|| WidgetInfo::selected(WidgetType::Checkbox, true, done, label));
    if resp.hovered() {
        ui.painter()
            .rect_filled(rect, 6.0, ui.visuals().widgets.hovered.weak_bg_fill);
    }
    let (icon, colour) = if done {
        (icons::CHECKED, tones.accent)
    } else {
        (icons::UNCHECKED, ui.visuals().text_color())
    };
    icons::paint(ui.painter(), rect.shrink(2.0), icon, colour);
    resp.on_hover_cursor(egui::CursorIcon::PointingHand)
}
/// The Agenda of `store` on `wall`, its targets in `system`, as the
/// window shows it, with the log's mark it was read at: today's picks
/// written first when they are new, then everything read. It runs on the
/// window's thread, or on one of its own with a connection of its own
/// (#207).
fn read_agenda(
    store: &Store,
    t: &L10n,
    wall: &oldbrainfix_core::WallClock,
    system: UnitSystem,
) -> oldbrainfix_core::Result<(AgendaView, i64)> {
    let notes = Notes::new(store);
    let places = Places::new(store);
    let routines = Routines::new(store);
    let lists = Checklists::new(store);
    let shopping = ShoppingLists::new(store);
    let frogs = Frogs::new(store);
    let place = |note: Note| place_note(store, &places, note);
    let shown_frogs = |list: Vec<Frog>| frogs_shown(store, &places, wall, list);
    // Read as the Agenda shows, never while it is drawn, and
    // before the rows read their Done: today's picks are
    // written for everyone the Session reaches when they are
    // new (ADR 0029), and reading again writes nothing.
    let sessions = Sessions::new(store);
    let picks = sessions.pick_today(wall)?;
    // Likewise today's Frog, written for the user's own Devices when it
    // is new.
    let today = frogs.pick_today(wall)?;
    // What is read from here on is of this mark (#207).
    let seq = store.current_seq()?;
    let mut picked = HashMap::new();
    for today in picks {
        let key = (today.session.id().to_string(), today.occurrence.key());
        picked.insert(key, PicksShown::read(store, t, today, system)?);
    }
    let counts: HashMap<String, _> = sessions
        .all()?
        .into_iter()
        .map(|s| (s.id().to_string(), s))
        .collect();
    let agenda = routines.agenda_over(wall, AGENDA_DAYS)?;
    // The rows' Notes that are Checklists, read in one pass so
    // only their rows read their Lines for the Occurrence.
    let row_notes: Vec<String> = agenda
        .today_rows
        .iter()
        .chain(&agenda.tomorrow_rows)
        .chain(agenda.later_rows.iter().flatten())
        .filter_map(|row| row.note.as_ref().map(|n| n.id.clone()))
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect();
    let list_notes: HashSet<String> = if row_notes.is_empty() {
        HashSet::new()
    } else {
        lists.of_notes(&row_notes)?.into_keys().collect()
    };
    // Their Lines for each Occurrence, read for all of them at once
    // (obf-1090); a Session's picks win over Lines.
    let on_lists: Vec<(RoutineOccurrence, String)> = agenda
        .today_rows
        .iter()
        .chain(&agenda.tomorrow_rows)
        .chain(agenda.later_rows.iter().flatten())
        .filter(|row| {
            let key = (row.routine.id.clone(), row.occurrence.key());
            !picked.contains_key(&key) && !counts.contains_key(&row.routine.id)
        })
        .filter_map(|row| {
            let note = row.note.as_ref().filter(|n| list_notes.contains(&n.id))?;
            let on = RoutineOccurrence {
                routine_id: row.routine.id.clone(),
                occurrence: row.occurrence,
            };
            Some((on, note.id.clone()))
        })
        .collect();
    let occurrence_lists = lists.for_occurrences(&on_lists)?;
    let row = |row: AgendaRow| -> oldbrainfix_core::Result<Row> {
        let area = match &row.note {
            Some(note) => place(note.clone())?.area,
            None => None,
        };
        let key = (row.routine.id.clone(), row.occurrence.key());
        let session = match picked.get(&key) {
            Some(shown) => Some(SessionPart::Today(Box::new(shown.clone()))),
            None => counts
                .get(&row.routine.id)
                .map(|s| SessionPart::Later(s.count_on(row.occurrence.day))),
        };
        // A Session's picks win over Lines: its rows have none read.
        let mut lines = None;
        if let Some(list) = occurrence_lists.get(&key)
            && list.count() > 0
        {
            lines = Some((list.clone(), store.may_check_off(&row.routine.id)?));
        }
        let answers = occurrence_answers::answers(store, &row.routine, &row.occurrence, wall)?;
        Ok(Row {
            row,
            area,
            session,
            lines,
            answers,
        })
    };
    // What shows as Done leaves where this Device hides it
    // (#217).
    let hides_checked = DeviceSettings::new(store).agenda_hides_checked()?;
    let rows = |rows: Vec<AgendaRow>| -> oldbrainfix_core::Result<Vec<Row>> {
        let mut shown = Vec::new();
        for placed in rows.into_iter().map(row) {
            let placed = placed?;
            if !hides_checked || !shown_done(&placed) {
                shown.push(placed);
            }
        }
        Ok(shown)
    };
    let mut later = Vec::new();
    for (i, day) in agenda.later_rows.iter().enumerate() {
        later.push((agenda.later(i), rows(day.clone())?));
    }
    let frog_rows = shown_frogs(today.shown.clone())?;
    let mut shopping_rows = Vec::new();
    // The Lines checked today stay, struck for the day, unless this
    // Device hides what is checked (#276).
    for shown in shopping.agenda_rows_with(wall, !hides_checked)? {
        let Some(note) = notes.by_id(&shown.list.note_id)? else {
            continue;
        };
        let title = match row_title(t, Some(&note)).lines().next() {
            Some(first) if !first.trim().is_empty() => first.trim().to_string(),
            _ => t.shopping_heading().to_string(),
        };
        // As this person chose for the list (#186); one kept
        // off is not among them, nor a count of none open.
        let count = shown.list.open_count() as i64;
        let (lines, text) = match shown.shows {
            ShoppingOnAgenda::Lines => (shown.lines, title),
            ShoppingOnAgenda::Count if count > 0 => {
                (Vec::new(), t.shopping_row_open(&title, count))
            }
            ShoppingOnAgenda::Count | ShoppingOnAgenda::Off => continue,
        };
        let open: HashSet<&str> = shown.list.open().iter().map(|l| l.id.as_str()).collect();
        let struck = lines
            .iter()
            .filter(|l| !open.contains(l.id.as_str()))
            .map(|l| l.id.clone())
            .collect();
        shopping_rows.push(ShoppingRow {
            area: place(note.clone())?.area,
            checks: shopping.may_check(&note.id)?,
            note_id: note.id,
            text,
            lines,
            struck,
        });
    }
    let mut checklist_rows = Vec::new();
    let day = Day::today(store.now(), wall);
    for row in lists.agenda_rows_with((!hides_checked).then_some(wall))? {
        let Some(note) = notes.by_id(&row.list.note_id)? else {
            continue;
        };
        let title = match row_title(t, Some(&note)).lines().next() {
            Some(first) if !first.trim().is_empty() => first.trim().to_string(),
            _ => t.checklist_heading().to_string(),
        };
        // As this person chose for the list (#219): every
        // open Line, or none, which leaves the count.
        let ChecklistAgendaRow { list, shows } = row;
        let lines = match shows {
            ListOnAgenda::Count => Vec::new(),
            // Its checked Lines show only on the day they were checked
            // (#143, #276).
            _ => agenda_lines(&list, hides_checked, Some((day, wall))),
        };
        // Never a count of none open.
        if lines.is_empty() && list.open_count() == 0 {
            continue;
        }
        let text = if lines.is_empty() {
            let (open, count) = (list.open_count() as i64, list.count() as i64);
            t.checklist_row_open(&title, open, count)
        } else {
            title
        };
        checklist_rows.push(ChecklistRow {
            area: place(note.clone())?.area,
            text,
            lines,
            checks: lists.may_check(&note.id)?,
            note_id: note.id,
        });
    }
    Ok((
        AgendaView {
            later,
            shopping: shopping_rows,
            checklists: checklist_rows,
            today: rows(agenda.today_rows)?,
            tomorrow: rows(agenda.tomorrow_rows)?,
            missed: Alarms::new(store).missed(wall)?,
            unsorted: notes.unsorted_count()?,
            // Counted from the pending sets, without reading each
            // held file.
            waiting: store
                .pending_sets()?
                .iter()
                .filter(|s| s.kind == sent::PENDING_KIND)
                .count(),
            offers: store
                .pending_sets()?
                .iter()
                .filter(|s| s.kind == offers::PENDING_KIND)
                .count(),
            frogs: Some(today),
            frog_rows,
            hides_checked,
            quiet: PersonSettings::new(store).quiet_until(wall)?.is_some(),
        },
        seq,
    ))
}

/// `note` with where it is filed, who wrote it and the Pack it came from.
fn place_note(store: &Store, places: &Places, note: Note) -> oldbrainfix_core::Result<Placed> {
    let author = store.author_of(&note.id)?;
    let pack_from = store.pack_from(&note.id)?;
    let Some(id) = note.place.clone() else {
        return Ok(Placed {
            note,
            area: None,
            topic: None,
            author,
            pack_from,
        });
    };
    let topic = places.topic_by_id(&id)?;
    let area_id = topic.as_ref().map_or(id, |t| t.area_id.clone());
    Ok(Placed {
        note,
        area: places.area_by_id(&area_id)?,
        topic,
        author,
        pack_from,
    })
}

/// [`place_note`] for each of `notes`, in their order, for a list, with
/// whether this Device may change each: whose they are, what it may do
/// and the Pack each came from read for all of them at once, each Area
/// and Topic once (obf-1069), as the phone's `placeNotes`.
fn place_notes(
    store: &Store,
    places: &Places,
    notes: Vec<Note>,
) -> oldbrainfix_core::Result<(Vec<Placed>, HashSet<String>)> {
    let ids: Vec<String> = notes.iter().map(|n| n.id.clone()).collect();
    let (mut access, mut packs) = if ids.is_empty() {
        (HashMap::new(), HashMap::new())
    } else {
        (store.access_of(&ids)?, store.pack_froms_of(&ids)?)
    };
    let mut topics: HashMap<String, Option<Topic>> = HashMap::new();
    let mut areas: HashMap<String, Option<Area>> = HashMap::new();
    let mut placed = Vec::with_capacity(notes.len());
    let mut changes = HashSet::new();
    for note in notes {
        let (author, may) = match access.remove(&note.id) {
            Some(a) => (a.author, a.changes),
            None => (store.author_of(&note.id)?, store.may_change(&note.id)?),
        };
        if may {
            changes.insert(note.id.clone());
        }
        let pack_from = packs.remove(&note.id);
        let Some(id) = note.place.clone() else {
            placed.push(Placed {
                note,
                area: None,
                topic: None,
                author,
                pack_from,
            });
            continue;
        };
        let topic = match topics.get(&id) {
            Some(held) => held.clone(),
            None => {
                let read = places.topic_by_id(&id)?;
                topics.insert(id.clone(), read.clone());
                read
            }
        };
        let area_id = topic.as_ref().map_or(id, |t| t.area_id.clone());
        let area = match areas.get(&area_id) {
            Some(held) => held.clone(),
            None => {
                let read = places.area_by_id(&area_id)?;
                areas.insert(area_id, read.clone());
                read
            }
        };
        placed.push(Placed {
            note,
            area,
            topic,
            author,
            pack_from,
        });
    }
    Ok((placed, changes))
}

/// The Frogs of `list` as they show, their Done on `wall`; one whose Note
/// is gone for good shows nowhere.
fn frogs_shown(
    store: &Store,
    places: &Places,
    wall: &oldbrainfix_core::WallClock,
    list: Vec<Frog>,
) -> oldbrainfix_core::Result<Vec<FrogShown>> {
    let frogs = Frogs::new(store);
    let mut out = Vec::new();
    for frog in list {
        let Some(note) = frogs.note(&frog)? else {
            continue;
        };
        let area = place_note(store, places, note.clone())?.area;
        out.push(FrogShown {
            may_check: store.may_check_off(&frog.id)?,
            manages: store.may_manage(store.area_of(&frog.id)?.as_deref())?,
            done_on: frog.done.map(|at| Day::of(wall(at))),
            frog,
            note,
            area,
        });
    }
    Ok(out)
}

/// What an Occurrence of a Routine shows as: its Note's text, else the
/// first line of its Transcript or Photo Text ([`Note::shown_name`],
/// obf-1049), what the Note holds when it has none of them, or that the
/// Note is gone.
pub(crate) fn row_title(t: &L10n, note: Option<&Note>) -> String {
    match note.map(|n| (n, n.shown_name())) {
        Some((note, name)) if name.trim().is_empty() => {
            l10n::wordless(t, note.wordless(), &note.wordless_name())
        }
        Some((_, name)) => name.trim().to_string(),
        None => t.note_gone().to_string(),
    }
}

/// How far an entry under an Agenda group's heading is indented, beside
/// the item spacing: its box stands where the heading's words begin, as
/// far in as a box and the room after it (#208).
const ENTRY_INDENT: f32 = 28.0 + 4.0;

/// How much further a Line under another Line is indented.
const ENTRY_STEP: f32 = 20.0;

/// The room above and below an Agenda row's content in its card, tighter
/// than a card's elsewhere (#208).
const AGENDA_INSIDE: i8 = 6;

/// The box of an Agenda heading that only shows Done, a Session's
/// (#208): drawn as [`check`] in its usual colours, but nothing clicks
/// it.
fn shown_check(ui: &mut Ui, tones: Tones, done: bool, label: &str) -> egui::Response {
    let (rect, resp) = ui.allocate_exact_size(egui::vec2(28.0, 28.0), Sense::hover());
    resp.widget_info(|| WidgetInfo::selected(WidgetType::Checkbox, false, done, label));
    let (icon, colour) = if done {
        (icons::CHECKED, tones.accent)
    } else {
        (icons::UNCHECKED, ui.visuals().text_color())
    };
    icons::paint(ui.painter(), rect.shrink(2.0), icon, colour);
    resp
}

/// The icon that leads an Agenda heading without a box, in a box's room.
fn heading_icon(ui: &mut Ui, icon: char) {
    let weak = ui.visuals().weak_text_color();
    let (rect, _) = ui.allocate_exact_size(egui::vec2(28.0, 28.0), Sense::hover());
    icons::paint(ui.painter(), rect.shrink(4.0), icon, weak);
}

/// What was clicked on an entry of an Agenda group.
#[derive(Debug, Clone, Copy, Default)]
struct EntryClicks {
    boxed: bool,
    words: bool,
}

/// One entry under an Agenda group's heading (#208): a Line, a Shopping
/// List's Line or a Session's pick, all alike: its box, `checked`, and its
/// words, struck through and dimmed when `struck`, indented under the
/// heading, `depth` steps further for a Line under another. The box
/// clicks while `boxes`, the words while `opens`, as a button named by
/// them; `id` keeps their click apart from every other's.
fn agenda_entry(
    ui: &mut Ui,
    tones: Tones,
    (id, words, depth): (Id, &str, usize),
    (checked, struck): (bool, bool),
    (boxes, opens): (bool, bool),
) -> EntryClicks {
    let text = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    ui.horizontal(|ui| {
        let spacing = ui.spacing().item_spacing.x;
        ui.add_space(ENTRY_INDENT + spacing + depth as f32 * ENTRY_STEP);
        let boxed = ui
            .add_enabled_ui(boxes, |ui| check(ui, tones, checked, words))
            .inner
            .clicked();
        ui.add_space(4.0);
        // The row's words at the Device's text size (#326, obf-1019).
        let mut shown = RichText::new(words)
            .size(theme::content(ui, 16.0))
            .color(text);
        if struck {
            shown = shown.strikethrough().color(weak);
        }
        let label = ui.add(egui::Label::new(shown).truncate());
        let sense = if opens {
            Sense::click()
        } else {
            Sense::hover()
        };
        let mut open = ui.interact(label.rect, id, sense);
        open.widget_info(|| WidgetInfo::labeled(WidgetType::Button, opens, words));
        if opens {
            open = open.on_hover_cursor(egui::CursorIcon::PointingHand);
        }
        EntryClicks {
            boxed,
            words: open.clicked(),
        }
    })
    .inner
}

/// What a click on an Occurrence on the Agenda opens, its heading's text
/// or a Checklist Routine's Line's words (#270): the Note dialog of its
/// Note, whose Due line answers it; the editor of its Routine while the
/// Note is gone or in the trash, the only place left to see it.
fn occurrence_opens(row: &AgendaRow) -> Action {
    match &row.note {
        Some(note) if !note.is_trashed() => Action::SelectNote(note.id.clone()),
        _ => Action::OpenRoutine(row.routine.id.clone()),
    }
}

/// One Occurrence on the Agenda as a group (#208): the heading an
/// embossed card's top, with the box to check it off, its time, its
/// Note's text, its Area's colour and icon, and its ⋮; a click on the
/// text opens its Note ([`occurrence_opens`]), a right-click on it the
/// menu of ⋮. A skipped
/// one stays struck for the day, as a Done one, saying so under its
/// text, and the one Tomorrow added says where it came from (#269).
/// Under it a Session's picks today, each with its box showing whether it has an
/// entry, its box and words opening its entry form, and "Another one"
/// under each without one; how many it picks on later days. A Session's
/// own box only shows Done: once every pick has an entry it checks
/// itself, and nothing else checks it. A Routine spawned from a
/// Checklist lists its Lines under it, checked for this Occurrence; once
/// every Line is checked, its box stays checked too (#121), a Line's
/// words opening what the heading opens. Where
/// `hides_checked` (#217), the checked Lines and the picks with an entry
/// are left out. The one a click on its notification asked for is
/// `marked` with an outline in the accent colour, and says so to a screen
/// reader (obf-1039); where the card lies.
fn agenda_row(
    ui: &mut Ui,
    t: &L10n,
    tones: Tones,
    (row, hides_checked, marked): (&Row, bool, bool),
    actions: &mut Vec<Action>,
) -> egui::Rect {
    let text = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    let routine = &row.row.routine;
    let occurrence = row.row.occurrence;
    // As clicked while its save waits (#338).
    let done = tick_saves::done(
        ui.ctx(),
        &tick_saves::occurrence_key(&routine.id, &occurrence),
        row.row.done().is_some(),
    );
    let skipped = row.row.skipped().is_some();
    let colour = row
        .area
        .as_ref()
        .and_then(|a| area_colour(a.colour.as_deref()));
    let title = row_title(t, row.row.note.as_ref());
    let time = occurrence_time(t, &occurrence);
    let card = agenda_card(ui, tones, colour, |ui| {
        // Done from the entries of every pick, or from every Line
        // checked, stays checked.
        let complete = matches!(&row.session, Some(SessionPart::Today(s)) if s.today.complete())
            || row
                .lines
                .as_ref()
                .is_some_and(|(list, _)| list.all_checked());
        ui.horizontal(|ui| {
            let label = format!("{}: {time} {title}", t.mark_done());
            if row.session.is_some() {
                // Its picks make it Done (#208).
                shown_check(ui, tones, done || complete, &label);
            } else {
                let toggled = ui
                    .add_enabled_ui(!complete, |ui| check(ui, tones, done, &label))
                    .inner;
                if toggled.clicked() {
                    actions.push(Action::Toggle(routine.id.clone(), occurrence));
                }
            }
            ui.add_space(4.0);
            let width = (ui.available_width() - 84.0).max(40.0);
            let body = ui.vertical(|ui| {
                ui.set_max_width(width);
                ui.spacing_mut().item_spacing.y = 2.0;
                ui.label(RichText::new(&time).strong().color(text));
                let mut line = RichText::new(&title)
                    .size(theme::content(ui, 16.0))
                    .color(text);
                if done || skipped {
                    line = line.strikethrough();
                }
                ui.add(egui::Label::new(line).truncate());
                if let Some(under) = answered_under(t, &row.row) {
                    ui.label(RichText::new(under).color(weak));
                }
                match &row.session {
                    Some(SessionPart::Later(count)) => {
                        ui.label(RichText::new(t.session_picks(*count)).color(text));
                    }
                    Some(SessionPart::Today(shown)) if shown.today.picks.is_empty() => {
                        ui.label(RichText::new(t.session_nothing_to_pick()).color(text));
                    }
                    _ => {}
                }
            });
            let open = body
                .response
                .interact(Sense::click())
                .on_hover_cursor(egui::CursorIcon::PointingHand);
            open.widget_info(|| WidgetInfo {
                selected: marked.then_some(true),
                ..WidgetInfo::labeled(WidgetType::Button, true, &title)
            });
            if open.clicked() {
                actions.push(occurrence_opens(&row.row));
            }
            // The same menu from a right-click and from ⋮; Done there as
            // the box checks it (obf-1039), not on a Session's, which its
            // picks make Done.
            let history = !routine.is_reminder();
            let answers = row.answers;
            let offers_done = answers.not_today && !done && !complete && row.session.is_none();
            let menu = (history, offers_done, answers);
            let mut picked = None;
            open.context_menu(|ui| picked = picked.or(occurrence_menu(ui, t, menu)));
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                let more = icon_button(ui, icons::MORE_VERT, &t.occurrence_menu(&title), weak);
                egui::Popup::menu(&more)
                    .show(|ui| picked = picked.or(occurrence_menu(ui, t, menu)));
                if let Some(icon) = row
                    .area
                    .as_ref()
                    .and_then(|a| icons::area_icon(a.icon.as_deref()))
                {
                    icons::show(ui, icon, 20.0, colour.unwrap_or(weak));
                }
                if routine.is_reminder() {
                    icons::show(ui, icons::REMINDER, 18.0, weak);
                }
            });
            match picked {
                Some(OccurrencePick::Done) => {
                    actions.push(Action::Toggle(routine.id.clone(), occurrence));
                }
                Some(OccurrencePick::Schedule) => {
                    actions.push(Action::OpenRoutine(routine.id.clone()));
                }
                Some(OccurrencePick::History) => {
                    actions.push(Action::Select(Selection::History(routine.id.clone())));
                }
                Some(OccurrencePick::Answer(answer)) => {
                    actions.push(Action::Answer(routine.id.clone(), occurrence, answer));
                }
                None => {}
            }
        });
        // The entries go under the heading, outside its click.
        if let Some(SessionPart::Today(shown)) = &row.session {
            session_picks(ui, t, tones, (shown, hides_checked), actions);
        } else if let Some((list, checks)) = &row.lines {
            // The Lines go there too, checked for this Occurrence.
            for line in agenda_lines(list, hides_checked, None) {
                let id = Id::new(("row line", &routine.id, occurrence.key(), &line.id));
                let shown = (id, line.text.as_str(), usize::from(line.in_group));
                let key = tick_saves::line_key(&line.id, list.on.as_ref());
                let checked = tick_saves::done(ui.ctx(), &key, line.checked);
                let clicks = agenda_entry(ui, tones, shown, (checked, checked), (*checks, true));
                if clicks.boxed {
                    actions.push(Action::Checklist(ChecklistAction::Check(
                        line.id.clone(),
                        !checked,
                        list.on.clone(),
                    )));
                }
                if clicks.words {
                    actions.push(occurrence_opens(&row.row));
                }
            }
        }
    });
    if marked {
        ui.painter().rect_stroke(
            card.rect,
            theme::CARD_RADIUS,
            egui::Stroke::new(3.0, tones.accent),
            egui::StrokeKind::Inside,
        );
    }
    card.rect
}

/// Today's picks of a Session under its heading (#208), in the order
/// picked, each an entry with its box, checked once it has an entry and
/// struck through; its box and its words open its entry form where this
/// Device may; "Another one" goes under each without an entry while they
/// swap (the control goes below its text). Where `hides_checked`
/// (#217), a pick with an entry is left out.
fn session_picks(
    ui: &mut Ui,
    t: &L10n,
    tones: Tones,
    (shown, hides_checked): (&PicksShown, bool),
    actions: &mut Vec<Action>,
) {
    let text = ui.visuals().text_color();
    let today = &shown.today;
    let session = today.session.id();
    let occurrence = today.occurrence;
    for (i, pick) in today.picks.iter().enumerate() {
        if hides_checked && pick.done() {
            continue;
        }
        let words = shown.texts.get(i).map(String::as_str).unwrap_or_default();
        let opens = shown.opens.get(i).copied().unwrap_or(false);
        let id = Id::new(("session pick", session, occurrence.key(), &pick.note_id));
        let clicks = agenda_entry(
            ui,
            tones,
            (id, words, 0),
            (pick.done(), pick.done()),
            (opens, opens),
        );
        if clicks.boxed || clicks.words {
            actions.push(Action::Session(SessionAction::Open {
                session: session.to_string(),
                occurrence,
                note_id: pick.note_id.clone(),
                entry: pick.entries.last().map(|e| e.id.clone()),
            }));
        }
        if shown.swaps && !pick.done() {
            let another = ui.horizontal(|ui| {
                ui.add_space(ENTRY_INDENT + ui.spacing().item_spacing.x);
                icons::show(ui, icons::SWAP, 18.0, text);
                ui.button(RichText::new(t.session_another()).color(text))
            });
            if another.inner.clicked() {
                actions.push(Action::Session(SessionAction::Another {
                    session: session.to_string(),
                    occurrence,
                    note_id: pick.note_id.clone(),
                }));
            }
        }
    }
}

/// The heading of a Shopping List's or Checklist's group: its kind's
/// icon where a box would be, its `words`, a click on which opens the
/// Note `note_id` with the keyboard in a new Line after its open ones
/// (#276), and its Area's icon.
fn list_heading(
    ui: &mut Ui,
    (icon, area, colour): (char, Option<&Area>, Option<Color32>),
    (note_id, words, salt): (&str, &str, &str),
    actions: &mut Vec<Action>,
) {
    let text = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    ui.horizontal(|ui| {
        heading_icon(ui, icon);
        ui.add_space(4.0);
        let width = (ui.available_width() - 32.0).max(40.0);
        let body = ui.vertical(|ui| {
            ui.set_max_width(width);
            let words = RichText::new(words)
                .size(theme::content(ui, 16.0))
                .color(text);
            ui.add(egui::Label::new(words).truncate());
        });
        let open = ui
            .interact(body.response.rect, Id::new((salt, note_id)), Sense::click())
            .on_hover_cursor(egui::CursorIcon::PointingHand);
        open.widget_info(|| WidgetInfo::labeled(WidgetType::Button, true, words));
        if open.clicked() {
            actions.push(Action::StartLine(note_id.to_string()));
        }
        ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
            if let Some(icon) = area.and_then(|a| icons::area_icon(a.icon.as_deref())) {
                icons::show(ui, icon, 20.0, colour.unwrap_or(weak));
            }
        });
    });
}

/// A Shopping List's group today (#123, #208): its title as the heading,
/// with the cart and no box, and its open Lines under it, then those
/// checked today struck for the day (#276), each with its box, which
/// checks or brings it back; or, as chosen for it, the heading alone with
/// how many are open. A click on a Line's words opens the Note, on the
/// heading's in a new Line (#276).
fn shopping_row(ui: &mut Ui, tones: Tones, row: &ShoppingRow, actions: &mut Vec<Action>) {
    let colour = row
        .area
        .as_ref()
        .and_then(|a| area_colour(a.colour.as_deref()));
    agenda_card(ui, tones, colour, |ui| {
        let icon = (icons::SHOPPING_CART, row.area.as_ref(), colour);
        list_heading(ui, icon, (&row.note_id, &row.text, "shopping row"), actions);
        for line in &row.lines {
            let id = Id::new(("shopping line", line.id.as_str()));
            let key = tick_saves::line_key(&line.id, None);
            let struck = tick_saves::done(ui.ctx(), &key, row.struck.contains(&line.id));
            let clicks = agenda_entry(
                ui,
                tones,
                (id, &line.text, 0),
                (struck, struck),
                (row.checks, true),
            );
            if clicks.boxed {
                let check = ShoppingAction::Check(line.id.clone(), !struck);
                actions.push(Action::Shopping(check));
            }
            if clicks.words {
                actions.push(Action::SelectNote(row.note_id.clone()));
            }
        }
    });
}

/// A Checklist's group today (#143, #208): its title as the heading,
/// with the list's icon and no box, and its open Lines under it with
/// those checked today struck for the day (#276), each with its box,
/// which checks or unchecks it. A click on a Line's words opens the
/// Note, on the heading's in a new Line (#276).
fn checklist_row(ui: &mut Ui, tones: Tones, row: &ChecklistRow, actions: &mut Vec<Action>) {
    let colour = row
        .area
        .as_ref()
        .and_then(|a| area_colour(a.colour.as_deref()));
    agenda_card(ui, tones, colour, |ui| {
        let icon = (icons::CHECKLIST, row.area.as_ref(), colour);
        list_heading(
            ui,
            icon,
            (&row.note_id, &row.text, "checklist row"),
            actions,
        );
        for line in &row.lines {
            let id = Id::new(("checklist line", line.id.as_str()));
            let shown = (id, line.text.as_str(), usize::from(line.in_group));
            let key = tick_saves::line_key(&line.id, None);
            let checked = tick_saves::done(ui.ctx(), &key, line.checked);
            let clicks = agenda_entry(ui, tones, shown, (checked, checked), (row.checks, true));
            if clicks.boxed {
                let check = ChecklistAction::Check(line.id.clone(), !checked, None);
                actions.push(Action::Checklist(check));
            }
            if clicks.words {
                actions.push(Action::SelectNote(row.note_id.clone()));
            }
        }
    });
}

/// What shows under the text of an Agenda row Not today answered
/// (#269): that it was skipped, or comes the day after instead, while it
/// is not Done; on the one Tomorrow added, that it came from the day
/// before.
fn answered_under(t: &L10n, row: &AgendaRow) -> Option<&'static str> {
    if row.skipped().is_some() && row.done().is_none() {
        return Some(if row.routine.tomorrow.contains(&row.occurrence.key()) {
            t.occurrence_tomorrow_instead()
        } else {
            t.occurrence_skipped()
        });
    }
    row.moved().then(|| t.occurrence_from_day_before())
}

/// What was picked in an Occurrence's menu.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum OccurrencePick {
    Done,
    Schedule,
    History,
    Answer(Answer),
}

/// An Occurrence's menu, from a right-click on it or its ⋮: Done where
/// it is offered (`done`, obf-1039), as its box checks it, then as the
/// phone's Snooze and Not today as far as `answers` allows (#269), each
/// under its heading, then Edit schedule, which opens its Routine or
/// Reminder editor (#270), and History for a Routine (`history`); no
/// calendar file (obf-1014). What was picked.
fn occurrence_menu(
    ui: &mut Ui,
    t: &L10n,
    (history, done, answers): (bool, bool, Answers),
) -> Option<OccurrencePick> {
    let text = ui.visuals().text_color();
    let mut picked = None;
    if done
        && ui
            .button(RichText::new(t.mark_done()).color(text))
            .clicked()
    {
        picked = Some(OccurrencePick::Done);
    }
    if done && answers.any() {
        ui.separator();
    }
    picked = picked.or(occurrence_answers::entries(ui, t, answers).map(OccurrencePick::Answer));
    if done || answers.any() {
        ui.separator();
    }
    if ui
        .button(RichText::new(t.edit_schedule()).color(text))
        .clicked()
    {
        picked = Some(OccurrencePick::Schedule);
    }
    if history
        && ui
            .button(RichText::new(t.history_title()).color(text))
            .clicked()
    {
        picked = Some(OccurrencePick::History);
    }
    // A pick closes the menu, also one by keyboard or screen reader,
    // which no pointer click closes.
    if picked.is_some() {
        ui.close();
    }
    picked
}

/// How many Missed Occurrences of one Routine show to check off.
const MISSED_SHOWN: usize = 3;

/// The Missed Summary: each Routine that Missed something since "Seen",
/// how often, and its latest Missed Occurrences to check off late. It
/// stays until "Seen". The Routine of the Occurrence a click on its
/// notification asked for (`mark`, obf-1039) is outlined in the accent
/// colour, its Occurrence's line in bold where it shows; where the
/// outline lies.
fn missed_card(
    ui: &mut Ui,
    t: &L10n,
    tones: Tones,
    (missed, mark): (&MissedSummary, Option<(&str, Occurrence)>),
    actions: &mut Vec<Action>,
) -> Option<egui::Rect> {
    let mut marked_at = None;
    let text = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    let error = ui.visuals().error_fg_color;
    embossed(ui, tones, true, None, |ui| {
        ui.horizontal(|ui| {
            icons::show(ui, icons::HISTORY, 20.0, error);
            ui.label(
                RichText::new(t.missed_title())
                    .strong()
                    .size(16.0)
                    .color(text),
            );
            ui.add_space((ui.available_width() - 64.0).max(0.0));
            if ui
                .button(RichText::new(t.missed_seen()).color(text))
                .clicked()
            {
                actions.push(Action::Seen);
            }
        });
        for routine in &missed.routines {
            let marked = mark.filter(|(id, _)| *id == routine.routine.id);
            let block = ui.scope(|ui| {
                let what = row_title(t, routine.note.as_ref());
                let first = what.lines().next().unwrap_or_default();
                ui.label(
                    RichText::new(format!(
                        "{first} · {}",
                        t.missed_times(routine.count() as i64)
                    ))
                    .color(text),
                );
                for m in routine.missed.iter().take(MISSED_SHOWN) {
                    ui.horizontal(|ui| {
                        let when = format!(
                            "{}  {}",
                            day_text(t, m.occurrence.day),
                            occurrence_time(t, &m.occurrence)
                        );
                        let label = format!("{}: {when} {first}", t.mark_done());
                        let key = tick_saves::occurrence_key(&routine.routine.id, &m.occurrence);
                        let done = tick_saves::done(ui.ctx(), &key, false);
                        if check(ui, tones, done, &label).clicked() && !done {
                            actions.push(Action::CheckMissed(
                                routine.routine.id.clone(),
                                m.occurrence,
                            ));
                        }
                        let mut when = RichText::new(when).color(text);
                        if marked.is_some_and(|(_, o)| o == m.occurrence) {
                            when = when.strong();
                        }
                        ui.label(when);
                    });
                }
                if routine.count() > MISSED_SHOWN {
                    let more = t.missed_more((routine.count() - MISSED_SHOWN) as i64);
                    ui.label(RichText::new(more).small().color(weak));
                }
            });
            if marked.is_some() {
                let rect = block.response.rect.expand(4.0);
                ui.painter().rect_stroke(
                    rect,
                    8.0,
                    egui::Stroke::new(3.0, tones.accent),
                    egui::StrokeKind::Outside,
                );
                marked_at = Some(rect);
            }
        }
    });
    marked_at
}

/// An Area's stored colour (`RRGGBB`), or `None` when it has none or it
/// cannot be read.
pub fn area_colour(hex: Option<&str>) -> Option<Color32> {
    let value = u32::from_str_radix(hex?, 16).ok()?;
    let [_, r, g, b] = value.to_be_bytes();
    Some(Color32::from_rgb(r, g, b))
}

/// When something was captured, in the app's language and local time:
/// the phone's `yMd` and `Hm`.
pub fn when(t: &L10n, at: DateTime<Utc>) -> String {
    let local = at.with_timezone(&Local);
    match t.locale() {
        "de" => local.format("%-d.%-m.%Y %H:%M").to_string(),
        _ => local.format("%-m/%-d/%Y %H:%M").to_string(),
    }
}

/// A point as the phone shows it, `<latitude>, <longitude>` to four
/// decimals.
fn coordinates_text(at: Coordinates) -> String {
    format!("{:.4}, {:.4}", at.latitude(), at.longitude())
}

/// Where `context` was captured as a compact card shows it, the
/// phone's `whereCaptured`: its Named Place, else its coordinates;
/// `None` while unknown.
fn where_captured(context: &CaptureContext) -> Option<String> {
    match (&context.named_place, context.location) {
        (Some(place), _) => Some(place.name.clone()),
        (None, Some(at)) => Some(coordinates_text(at)),
        (None, None) => None,
    }
}

/// What a Capture Context says beyond the time, line by line with each
/// line's icon, as the phone's `CaptureContextLines`: where, by its
/// Named Place, else its coordinates, the app it was shared in from,
/// the calendar events running and the Bluetooth devices connected;
/// each with the detail it shows.
fn context_lines(t: &L10n, context: &CaptureContext) -> Vec<(char, String, CapturedDetail)> {
    let mut lines = Vec::new();
    if context.location.is_some()
        && let Some(place) = where_captured(context)
    {
        lines.push((icons::CONTEXT_WHERE, place, CapturedDetail::Place));
    }
    if let Some(app) = &context.source_app {
        let line = t.context_source_app(app.name());
        lines.push((icons::CONTEXT_APP, line, CapturedDetail::App));
    }
    if !context.calendar_events.is_empty() {
        let events = context.calendar_events.join(", ");
        let line = t.context_during(&events);
        lines.push((icons::CONTEXT_CALENDAR, line, CapturedDetail::Event));
    }
    if !context.bluetooth_devices.is_empty() {
        let devices = context.bluetooth_devices.join(", ");
        let line = t.context_bluetooth(&devices);
        lines.push((icons::CONTEXT_BLUETOOTH, line, CapturedDetail::Device));
    }
    lines
}

/// One line of a Capture Context: its icon, dimmed, and what it says,
/// wrapped where it is long.
fn context_line(ui: &mut Ui, icon: char, line: &str) {
    let text = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    ui.horizontal_top(|ui| {
        ui.spacing_mut().item_spacing.x = 6.0;
        icons::show(ui, icon, 16.0, weak);
        ui.add(egui::Label::new(RichText::new(line).color(text)).wrap());
    });
}

/// When the text of `section` was last edited and by whom (#183), as
/// the phone's `CaptureContextLines.ofSection` says it: no "by" for a
/// writer not known or a Profile without a name; `None` while it was
/// never edited.
fn section_edited(t: &L10n, section: &Section) -> Option<String> {
    let at = when(t, section.modified?);
    let name = section.edited_by.as_ref().map(|p| p.name.trim());
    Some(match name.filter(|n| !n.is_empty()) {
        Some(name) => t.section_edited_by(&at, name),
        None => t.section_edited(&at),
    })
}

/// The whole Capture Context of a Note or Section `captured` then, line
/// by line, in its Captured dialog, as the phone's `CaptureContextLines`:
/// when, then [`context_lines`]. Each detail `removable` says may go
/// ends in a Remove (ADR 0037), the time in none; the detail whose
/// Remove was clicked. Beside its text the same reads as one
/// [`capture_line`] (#170).
fn capture_context(
    ui: &mut Ui,
    t: &L10n,
    (captured, context): (DateTime<Utc>, &CaptureContext),
    removable: impl Fn(CapturedDetail) -> bool,
) -> Option<CapturedDetail> {
    let mut asked = None;
    ui.vertical(|ui| {
        ui.spacing_mut().item_spacing.y = 4.0;
        context_line(ui, icons::CONTEXT_WHEN, &when(t, captured));
        for (icon, line, detail) in context_lines(t, context) {
            if !removable(detail) {
                context_line(ui, icon, &line);
                continue;
            }
            // The Remove first, at the end of the line, so the line
            // wraps in what is left beside it.
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Min), |ui| {
                let remove = theme::destructive(ui, true, t.remove());
                let label = t.remove_captured_label(detail.name());
                remove.widget_info(|| WidgetInfo::labeled(WidgetType::Button, true, &label));
                if remove.clicked() {
                    asked = Some(detail);
                }
                ui.with_layout(egui::Layout::left_to_right(egui::Align::Min), |ui| {
                    context_line(ui, icon, &line);
                });
            });
        }
    });
    asked
}

/// A Capture Context `captured` then as one line read beside its text
/// (#170), the phone's `captureLine`: when, then where (its Named Place,
/// else its coordinates), the calendar events running, the Bluetooth
/// devices connected and the app it was shared in from, joined by
/// " · ". A part captured the same local day as the one before it
/// (`after`) shows only its time; another day the date too.
fn capture_line(
    t: &L10n,
    (captured, context): (DateTime<Utc>, &CaptureContext),
    after: Option<DateTime<Utc>>,
) -> String {
    let local = captured.with_timezone(&Local);
    let same_day =
        after.is_some_and(|a| a.with_timezone(&Local).date_naive() == local.date_naive());
    let mut parts = vec![if same_day {
        local.format("%H:%M").to_string()
    } else {
        when(t, captured)
    }];
    parts.extend(where_captured(context));
    if !context.calendar_events.is_empty() {
        parts.push(context.calendar_events.join(", "));
    }
    if !context.bluetooth_devices.is_empty() {
        parts.push(context.bluetooth_devices.join(", "));
    }
    if let Some(app) = &context.source_app {
        parts.push(app.name().to_string());
    }
    parts.join(" · ")
}

/// A part's [`capture_line`] under its text, in the background (#170):
/// small and in the weak colour, wrapped only where it must, and a
/// Section's `edited` line (#183, [`section_edited`]) under it the same
/// way. A `clickable` one is a button, read as "Captured: <line>", that
/// opens the details; whether it was clicked.
fn capture_meta(ui: &mut Ui, t: &L10n, line: &str, edited: Option<&str>, clickable: bool) -> bool {
    let weak = ui.visuals().weak_text_color();
    ui.vertical(|ui| {
        ui.spacing_mut().item_spacing.y = 2.0;
        let label = egui::Label::new(RichText::new(line).size(12.0).color(weak)).wrap();
        let clicked = if clickable {
            let shown = ui
                .add(label.sense(Sense::click()))
                .on_hover_cursor(egui::CursorIcon::PointingHand);
            let name = t.setting_badge_label(t.captured_heading(), line);
            shown.widget_info(|| WidgetInfo::labeled(WidgetType::Button, true, &name));
            shown.clicked()
        } else {
            ui.add(label);
            false
        };
        if let Some(edited) = edited {
            ui.add(egui::Label::new(RichText::new(edited).size(12.0).color(weak)).wrap());
        }
        clicked
    })
    .inner
}

/// Where a Note is filed, `Area / Topic`; `None` while it is in no
/// place.
fn place_line(t: &L10n, placed: &Placed) -> Option<String> {
    let area = placed.area.as_ref()?;
    Some(match &placed.topic {
        Some(topic) => format!("{} / {}", area_name(t, area), topic_name(t, topic)),
        None => area_name(t, area),
    })
}

/// A row of the left pane: self-painted so its text reads in every
/// state, with the accent while selected. A `droppable` row is outlined
/// while a card is held over it.
fn row(
    ui: &mut Ui,
    tones: Tones,
    on: bool,
    indent: f32,
    icon: Option<(char, Color32)>,
    label: &str,
    droppable: bool,
) -> egui::Response {
    let font = egui::TextStyle::Body.resolve(ui.style());
    let height = 30.0;
    let width = ui.available_width();
    let (rect, resp) = ui.allocate_exact_size(egui::vec2(width, height), Sense::click());
    resp.widget_info(|| WidgetInfo::selected(WidgetType::SelectableLabel, true, on, label));
    if ui.is_rect_visible(rect) {
        let fg = ui.visuals().text_color();
        if droppable && resp.dnd_hover_payload::<DraggedNotes>().is_some() {
            ui.painter().rect_stroke(
                rect,
                8.0,
                egui::Stroke::new(2.0, tones.accent),
                egui::StrokeKind::Inside,
            );
        }
        let fill = if on {
            tones.accent.gamma_multiply(0.3)
        } else if resp.hovered() {
            tones.card.gamma_multiply(0.7)
        } else {
            Color32::TRANSPARENT
        };
        if fill.a() > 0 {
            ui.painter().rect_filled(rect, 8.0, fill);
        }
        let mut x = rect.left() + 8.0 + indent;
        if let Some((glyph, colour)) = icon {
            let icon_rect = egui::Rect::from_center_size(
                egui::pos2(x + 9.0, rect.center().y),
                egui::vec2(18.0, 18.0),
            );
            icons::paint(ui.painter(), icon_rect, glyph, colour);
            x += 26.0;
        }
        let text = ui.painter().layout(
            label.to_string(),
            font,
            fg,
            (rect.right() - x - 8.0).max(0.0),
        );
        let y = rect.center().y - text.size().y / 2.0;
        ui.painter().galley(egui::pos2(x, y), text, fg);
    }
    resp
}

/// A Note the merge picks as a row, as [`row`] draws one, its tags in the
/// accent colour: a click on one picks the Note, as anywhere on the row
/// (#126).
pub(crate) fn merge_row(ui: &mut Ui, tones: Tones, label: &str) -> egui::Response {
    let height = 30.0;
    let width = ui.available_width();
    let (rect, resp) = ui.allocate_exact_size(egui::vec2(width, height), Sense::click());
    resp.widget_info(|| WidgetInfo::selected(WidgetType::SelectableLabel, true, false, label));
    if ui.is_rect_visible(rect) {
        if resp.hovered() {
            ui.painter()
                .rect_filled(rect, 8.0, tones.card.gamma_multiply(0.7));
        }
        let x = rect.left() + 8.0;
        let colours = (ui.visuals().text_color(), ui.visuals().hyperlink_color);
        let font = egui::TextStyle::Body.resolve(ui.style());
        let mut job = text_marks_view::tag_job(label, (0, label.len()), font, colours);
        job.wrap.max_width = (rect.right() - x - 8.0).max(0.0);
        let text = ui.painter().layout_job(job);
        let y = rect.center().y - text.size().y / 2.0;
        ui.painter().galley(egui::pos2(x, y), text, colours.0);
    }
    resp
}

/// Lays out `content` on a softly embossed card the width of `ui`;
/// `band` runs an Area's colour down its left edge.
pub(crate) fn embossed(
    ui: &mut Ui,
    tones: Tones,
    strong: bool,
    band: Option<Color32>,
    content: impl FnOnce(&mut Ui),
) -> egui::Response {
    embossed_inside(ui, (tones, strong), (band, 14), content)
}

/// An Agenda row's card (#208): as [`embossed`], plain, with less room
/// above and below its content.
pub(crate) fn agenda_card(
    ui: &mut Ui,
    tones: Tones,
    band: Option<Color32>,
    content: impl FnOnce(&mut Ui),
) -> egui::Response {
    embossed_inside(ui, (tones, false), (band, AGENDA_INSIDE), content)
}

/// An embossed card with `inside` room above and below its content.
fn embossed_inside(
    ui: &mut Ui,
    (tones, strong): (Tones, bool),
    (band, inside): (Option<Color32>, i8),
    content: impl FnOnce(&mut Ui),
) -> egui::Response {
    let under = ui.painter().add(egui::Shape::Noop);
    let left = if band.is_some() { 22 } else { 16 };
    let inner = Frame::NONE
        .inner_margin(Margin {
            left,
            right: 16,
            top: inside,
            bottom: inside,
        })
        .show(ui, |ui| {
            ui.set_min_width(ui.available_width());
            ui.style_mut().interaction.selectable_labels = false;
            content(ui);
        });
    let rect = inner.response.rect;
    let mut shapes = theme::embossed(rect, tones, strong);
    if let Some(colour) = band {
        shapes.push(theme::area_band(rect, colour));
    }
    ui.painter().set(under, egui::Shape::Vec(shapes));
    inner.response
}

/// What the Note dialog's badges show (#160): the Note where it is filed,
/// its Routines and Reminders and how many of them a newer version saved,
/// its kind with whether it may go back to a plain Note, Show on the
/// Agenda of a Checklist or a Shopping List and Show ticks where they
/// apply, a Session's setup, what this Device may do to it and whether it
/// has a Frog to show (#259).
struct BadgesShown<'a> {
    placed: &'a Placed,
    routines: &'a [Routine],
    newer: usize,
    kind: &'a KindShown,
    on_agenda: Option<ListOnAgenda>,
    shopping_on_agenda: Option<ShoppingOnAgenda>,
    ticks: Option<bool>,
    /// Its own mark Hidden from AI and whether another hides it, while
    /// the badge is offered (#267).
    hidden: Option<(bool, bool)>,
    /// A Session Note's setup, for its rule and weekdays' badges, and
    /// whether this Device may change them (#191).
    session: Option<(&'a SessionSetup, bool)>,
    may: NoteMay,
    /// Its open Frog, or one eaten today or yesterday (#259).
    frog: Option<&'a NoteFrog>,
    /// Whether Frogs and Sessions are offered under "+": only in
    /// Advanced (#197).
    advanced: bool,
}

/// Where a step of the Note open goes (obf-1051).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Way {
    Undo,
    Redo,
    Revert,
}

/// The kind of the Note open (#188), and the kinds this Device may make
/// it from its kind badge, in the order offered: a plain Note a
/// Checklist, a Shopping List, a Tally or a Session (#191), as it may make
/// it one; a list a plain Note again or the other list; a Session a plain
/// Note again; a Tally none.
#[derive(Debug, Clone, PartialEq)]
struct KindShown {
    kind: NoteKind,
    choices: Vec<NoteKind>,
}

impl KindShown {
    fn of(view: &View) -> KindShown {
        let kind = view.kind.unwrap_or(NoteKind::Plain);
        let Some((placed, _)) = &view.detail else {
            return KindShown {
                kind,
                choices: Vec::new(),
            };
        };
        let note = &placed.note;
        let may = view.may;
        let mut choices = Vec::new();
        if !note.is_trashed() {
            let plain = |list_plain: bool| list_plain.then_some(NoteKind::Plain);
            let switch = |to: NoteKind| view.switches_list.then_some(to);
            match kind {
                // A Code text becomes no other kind (#213).
                NoteKind::Plain if note.text_format == text_format::CODE => {}
                NoteKind::Plain => {
                    // As the card's menu offers them (#145).
                    let tally = may.amends && may.changes && !note.is_merged();
                    choices.extend(view.makes_checklist.then_some(NoteKind::Checklist));
                    choices.extend(view.makes_shopping.then_some(NoteKind::ShoppingList));
                    // Made only in Advanced (#197).
                    choices.extend((tally && view.advanced).then_some(NoteKind::Tally));
                    choices
                        .extend((view.makes_session && view.advanced).then_some(NoteKind::Session));
                }
                NoteKind::Checklist => {
                    choices.extend(plain(view.checklist.as_ref().is_some_and(|l| l.plain)));
                    choices.extend(switch(NoteKind::ShoppingList));
                }
                NoteKind::ShoppingList => {
                    choices.extend(plain(view.shopping.as_ref().is_some_and(|l| l.plain)));
                    choices.extend(switch(NoteKind::Checklist));
                }
                // No way out of a Tally.
                NoteKind::Tally => {}
                NoteKind::Session => {
                    choices.extend(view.makes_session.then_some(NoteKind::Plain));
                }
            }
        }
        KindShown { kind, choices }
    }
}

/// Whether Redo's keys were pressed, Ctrl+Shift+Z or Ctrl+Y (Cmd on
/// macOS), and takes them (obf-1051).
fn redo_keys(i: &mut egui::InputState) -> bool {
    (i.modifiers.shift && i.consume_key(Modifiers::COMMAND | Modifiers::SHIFT, Key::Z))
        || i.consume_key(Modifiers::COMMAND, Key::Y)
}

/// What making the Note `id` of the kind `from` one of the kind `to`
/// asks (#188): the existing ways a Note becomes a list, a Tally or a
/// plain Note again, a list the other list; a Session's setup page, and
/// a Session a plain Note again (#191).
fn kind_action(id: &str, from: NoteKind, to: NoteKind) -> Action {
    let id = id.to_string();
    match to {
        NoteKind::Plain if from == NoteKind::Session => Action::UnmakeSession(id),
        NoteKind::Plain if from == NoteKind::ShoppingList => {
            Action::Shopping(ShoppingAction::ToPlain(id))
        }
        NoteKind::Plain => Action::Checklist(ChecklistAction::ToPlain(id)),
        NoteKind::Checklist => Action::Checklist(ChecklistAction::Make(id)),
        NoteKind::ShoppingList => Action::Shopping(ShoppingAction::Make(id)),
        NoteKind::Tally => Action::Tally(TallyAction::Make(id)),
        NoteKind::Session => Action::MakeSession(id),
    }
}

/// The icon and the name of the kind `kind` (#188), the value of its
/// badge (#192); the phone's `kindIcon` and `kindName`.
/// Under the Note's text after a paste that looks like code (#213): says
/// so and offers to keep the whole text as code; the cross lets it be.
fn code_offer(ui: &mut Ui, t: &L10n, actions: &mut Vec<Action>) {
    let text = ui.visuals().text_color();
    ui.horizontal(|ui| {
        icons::show(ui, icons::CODE, 18.0, text);
        ui.label(RichText::new(t.code_pasted()).color(text));
        if ui
            .button(RichText::new(t.keep_as_code()).color(text))
            .clicked()
        {
            actions.push(Action::KeepAsCode);
        }
        if icon_button(ui, icons::CLOSE, t.close(), text).clicked() {
            actions.push(Action::OfferCode(false, None));
        }
    });
}

/// The value icon of the text format `format` in its badge, and the
/// format in words (#213).
fn text_format_look(t: &L10n, format: &str) -> (char, &'static str) {
    match format {
        text_format::MARKDOWN => (icons::FORMAT_BOLD, t.text_format_formatted()),
        text_format::CODE => (icons::CODE, t.text_format_code()),
        _ => (icons::SHORT_TEXT, t.text_format_plain()),
    }
}

fn kind_look(t: &L10n, kind: NoteKind) -> (char, &'static str) {
    match kind {
        NoteKind::Plain => (icons::ALL_NOTES, t.kind_plain()),
        NoteKind::Checklist => (icons::CHECKLIST, t.checklist_heading()),
        NoteKind::ShoppingList => (icons::SHOPPING_CART, t.shopping_heading()),
        NoteKind::Tally => (icons::TALLY, t.tally_heading()),
        NoteKind::Session => (icons::SESSION, t.session()),
    }
}

/// Room between a group's heading and its buttons and between their
/// rows, and between two buttons side by side (obf-1073).
const GROUP_SPACING: egui::Vec2 = egui::vec2(8.0, 8.0);

/// Room between two groups side by side (obf-1073).
const GROUP_GAP: f32 = 32.0;

/// How tall a group's buttons are at least, as one with its icon is, so
/// a row of them lines up (obf-1073).
const GROUP_BUTTON_HEIGHT: f32 = 26.0;

/// What draws a group's compact buttons (obf-1073), adding what they ask.
type GroupDraw<'a> = Box<dyn FnOnce(&mut Ui, &mut Vec<Action>) + 'a>;

/// One of the Note dialog's groups of actions (obf-1073): its heading
/// and what draws its compact buttons, its width kept by `key`.
struct ActionGroup<'a> {
    key: &'static str,
    heading: &'a str,
    draw: GroupDraw<'a>,
}

impl<'a> ActionGroup<'a> {
    fn new(
        key: &'static str,
        heading: &'a str,
        draw: impl FnOnce(&mut Ui, &mut Vec<Action>) + 'a,
    ) -> ActionGroup<'a> {
        ActionGroup {
            key,
            heading,
            draw: Box::new(draw),
        }
    }
}

/// The groups of the Note `of` (obf-1073), side by side where they fit:
/// each as wide as it was drawn last for that Note, which shows in the
/// dialog or in its own window, one not drawn yet on a line of its own;
/// a group wider than the dialog takes its line alone, its buttons
/// wrapping.
fn action_groups(ui: &mut Ui, of: &str, groups: Vec<ActionGroup<'_>>, actions: &mut Vec<Action>) {
    let room = ui.available_width();
    let mut rows: Vec<Vec<(Id, ActionGroup<'_>)>> = Vec::new();
    let mut used = 0.0;
    for group in groups {
        let id = Id::new(("note group", of, group.key));
        let wide = ui.data(|d| d.get_temp::<f32>(id)).unwrap_or(room);
        match rows.last_mut() {
            Some(row) if used + GROUP_GAP + wide <= room => {
                row.push((id, group));
                used += GROUP_GAP + wide;
            }
            _ => {
                rows.push(vec![(id, group)]);
                used = wide;
            }
        }
    }
    for row in rows {
        ui.horizontal_top(|ui| {
            ui.spacing_mut().item_spacing.x = GROUP_GAP;
            for (id, group) in row {
                let drawn = ui.vertical(|ui| {
                    ui.spacing_mut().item_spacing = GROUP_SPACING;
                    ui.spacing_mut().interact_size.y = GROUP_BUTTON_HEIGHT;
                    group_heading(ui, group.heading);
                    ui.horizontal_wrapped(|ui| (group.draw)(ui, actions));
                });
                // Laid out anew once its width changed.
                let wide = drawn.response.rect.width();
                let was = ui.data(|d| d.get_temp::<f32>(id));
                if was.is_none_or(|was| (was - wide).abs() > 0.5) {
                    ui.data_mut(|d| d.insert_temp(id, wide));
                    ui.ctx().request_repaint();
                }
            }
        });
    }
}

/// A group's heading (obf-1073), small and strong, read as a heading.
fn group_heading(ui: &mut Ui, heading: &str) {
    let text = ui.visuals().text_color();
    let shown = ui.label(RichText::new(heading).strong().color(text));
    ui.ctx().accesskit_node_builder(shown.id, |node| {
        node.set_role(egui::accesskit::Role::Heading);
    });
}

/// A compact button of a group (obf-1073): `icon`, where it has one,
/// before its words.
fn group_button(ui: &mut Ui, icon: Option<char>, label: &str) -> egui::Response {
    let text = ui.visuals().text_color();
    let words = RichText::new(label).color(text);
    let Some(icon) = icon else {
        return ui.button(words);
    };
    let at = Id::new(("group button icon", label));
    let shown =
        egui::Button::new((egui::Atom::custom(at, egui::Vec2::splat(18.0)), words)).atom_ui(ui);
    if let Some(rect) = shown.rect(at) {
        icons::paint(ui.painter(), rect, icon, text);
    }
    shown.response
}

/// The row of badges under the Note's text (#160), each the setting's
/// icon and its value, an icon for a fixed set of values, short text
/// otherwise (#192), in the phone's order: the kind, in words with ▾
/// where it opens (#310); the Importance; Area and Topic in one, opening File into…; Captured,
/// to read its details; each Routine and Reminder with its schedule,
/// opening its editor, and those a newer version saved, only shown; its
/// Frog, open or eaten today or yesterday, offering Eat now and Remove
/// the Frog (#259); a Session's rule and weekdays' counts (#191); Show on the
/// Agenda; Show ticks; and Hidden from AI. "+" ([`add_badge`]) stands in
/// the Add group (obf-1073). A setting that does not apply has no badge;
/// one this Device may not change only shows.
fn note_badges(
    ui: &mut Ui,
    (t, tones): (&L10n, Tones),
    shown: &BadgesShown,
    actions: &mut Vec<Action>,
) {
    let placed = shown.placed;
    let note = &placed.note;
    let trashed = note.is_trashed();
    let changes = shown.may.changes && !trashed;
    let look = (t, tones);
    badge_row(ui, |ui| {
        // Every Note has its kind, a plain Note too (#188), first and in
        // words (#310), with ▾ where there is another to make it.
        let name = kind_look(t, shown.kind.kind).1;
        let choosing = !shown.kind.choices.is_empty();
        let value = Some(if choosing {
            BadgeValue::Choice(name)
        } else {
            BadgeValue::Text(name)
        });
        let kind = (icons::KIND, None);
        let kind = badge(ui, look, kind, t.badge_kind(), value, choosing);
        spotlight::anchor(ui, "note-kind", kind.rect);
        if kind.clicked() {
            actions.push(Action::Badge(Some(NoteBadge::Kind)));
        }
        let importance = match note.importance {
            Importance::Unimportant => (icons::IMPORTANCE_LOW, t.importance_unimportant()),
            Importance::Normal => (icons::IMPORTANCE_NORMAL, t.importance_normal()),
            Importance::Important => (icons::IMPORTANCE_HIGH, t.importance_important()),
        };
        let icon = (icons::IMPORTANCE, None);
        let value = BadgeValue::Icon(importance.0, importance.1);
        if badge(ui, look, icon, t.importance(), Some(value), changes).clicked() {
            actions.push(Action::Badge(Some(NoteBadge::Importance)));
        }
        // Area and Topic in one: File into… picks both at once.
        // The folder for every place, in the Area's colour.
        let area = placed.area.as_ref();
        let colour = area.and_then(|a| area_colour(a.colour.as_deref()));
        let place = place_line(t, placed).unwrap_or_else(|| t.unsorted().to_string());
        let place = badge(
            ui,
            look,
            (icons::NO_AREA_ICON, colour),
            t.badge_place(),
            Some(BadgeValue::Text(&place)),
            changes,
        );
        spotlight::anchor(ui, "note-place", place.rect);
        if place.clicked() {
            actions.push(Action::AskFileInto(vec![note.id.clone()]));
        }
        let captured = when(t, note.captured);
        let icon = (icons::CONTEXT_WHEN, None);
        let value = Some(BadgeValue::Text(&captured));
        if badge(ui, look, icon, t.captured_heading(), value, true).clicked() {
            actions.push(Action::Badge(Some(NoteBadge::Captured)));
        }
        // Who the Pack it came from is from, until removed (#165): its
        // click offers to remove it, which asks nothing (#268).
        if let Some(from) = &placed.pack_from {
            let name = profile_view::display_name(t, &from.name);
            let said = t.pack_from(name);
            let icon = (pack_view::PACK_ICON, None);
            let value = Some(BadgeValue::Text(&said));
            let from_badge = badge(ui, look, icon, t.pack_title(), value, changes);
            if changes {
                let text = ui.visuals().text_color();
                egui::Popup::menu(&from_badge).show(|ui| {
                    if menu_entry(ui, (icons::TRASH, text), &t.remove_pack_from(name)).clicked() {
                        actions.push(Action::RemovePackFrom(note.id.clone()));
                        ui.close();
                    }
                });
            }
        }
        for routine in shown.routines {
            let (icon, setting) = if routine.is_reminder() {
                (icons::REMINDER, t.reminder())
            } else {
                (icons::REPEAT, t.routine())
            };
            let schedule = schedule_text(t, &routine.schedule);
            let value = Some(BadgeValue::Text(&schedule));
            if badge(ui, look, (icon, None), setting, value, true).clicked() {
                actions.push(Action::OpenRoutine(routine.id.clone()));
            }
        }
        for _ in 0..shown.newer {
            let icon = (icons::REPEAT, None);
            let newer = Some(BadgeValue::Text(t.newer_version_needed()));
            badge(ui, look, icon, t.routine(), newer, false);
        }
        if let Some(frog) = shown.frog {
            frog_badge(ui, look, frog, actions);
        }
        // A Plain Note's text is plain, formatted or code (#213).
        if shown.kind.kind == NoteKind::Plain && note.text_editable {
            let (icon, name) = text_format_look(t, &note.text_format);
            let value = Some(BadgeValue::Icon(icon, name));
            let setting = (icons::TEXT_FORMAT, None);
            let format = badge(ui, look, setting, t.badge_text_format(), value, changes);
            // Its small editor picks a Code text's language (obf-1036).
            if changes && note.text_format == text_format::CODE {
                spotlight::anchor(ui, "note-format-code", format.rect);
            }
            if format.clicked() {
                actions.push(Action::Badge(Some(NoteBadge::Format)));
            }
        }
        // A Session's rule and its weekdays' counts (#191).
        if let Some((setup, changes)) = shown.session {
            let rule = session_view::rule_name(t, setup.rule);
            let rule = Some(BadgeValue::Icon(session_view::rule_icon(setup.rule), rule));
            let icon = (icons::SESSION_RULE_BADGE, None);
            if badge(ui, look, icon, t.session_rule(), rule, changes).clicked() {
                actions.push(Action::Badge(Some(NoteBadge::SessionRule)));
            }
            let own = t.session_weekday_counts_summary(setup.counts.len() as i64);
            let icon = (icons::SESSION_WEEKDAYS, None);
            let setting = t.session_weekday_counts();
            let own = Some(BadgeValue::Text(&own));
            if badge(ui, look, icon, setting, own, changes).clicked() {
                actions.push(Action::Badge(Some(NoteBadge::SessionWeekdays)));
            }
        }
        // A Shopping List's (#186) or a Checklist's (#219) three ways.
        let ways = [
            (shown.on_agenda, NoteBadge::OnAgenda),
            (shown.shopping_on_agenda, NoteBadge::ShoppingOnAgenda),
        ];
        for (shows, open) in ways {
            let Some(shows) = shows else {
                continue;
            };
            let value = shopping_view::on_agenda_label(t, shows);
            let value = Some(BadgeValue::Icon(
                shopping_view::on_agenda_icon(shows),
                value,
            ));
            let icon = (icons::ON_AGENDA, None);
            let setting = t.checklist_show_on_agenda();
            if badge(ui, look, icon, setting, value, true).clicked() {
                actions.push(Action::Badge(Some(open)));
            }
        }
        let switches = [(
            shown.ticks,
            icons::SHOW_TICKS,
            t.box_show_ticks(),
            NoteBadge::Ticks,
        )];
        for (on, icon, setting, open) in switches {
            let Some(on) = on else {
                continue;
            };
            let value = if on { t.setting_on() } else { t.setting_off() };
            let value = Some(BadgeValue::Icon(switch_icon(on), value));
            if badge(ui, look, (icon, None), setting, value, true).clicked() {
                actions.push(Action::Badge(Some(open)));
            }
        }
        // Its own mark, or "Off, hidden by its Area" (#267).
        if let Some((own, other)) = shown.hidden {
            let value = match (own, other) {
                (true, _) => t.setting_on(),
                (false, true) => t.hidden_from_ai_by_area(),
                (false, false) => t.setting_off(),
            };
            let value = Some(BadgeValue::Icon(switch_icon(own), value));
            let icon = (icons::HIDDEN_FROM_AI, None);
            if badge(ui, look, icon, t.hidden_from_ai(), value, true).clicked() {
                actions.push(Action::Badge(Some(NoteBadge::HiddenFromAi)));
            }
        }
    });
}

/// The "+" badge (obf-1034), first in the Note dialog's Add group
/// (obf-1073): its menu holds Remind me…, and in Advanced Frog and
/// Session.
fn add_badge(
    ui: &mut Ui,
    (t, tones): (&L10n, Tones),
    shown: &BadgesShown,
    actions: &mut Vec<Action>,
) {
    let note = &shown.placed.note;
    let look = (t, tones);
    let add = badge(
        ui,
        look,
        (icons::ADD, None),
        t.routine_or_reminder(),
        None,
        true,
    );
    // Its menu holds Remind me… (obf-1034).
    spotlight::anchor(ui, "note-add-badge", add.rect);
    let id = note.id.clone();
    let text = ui.visuals().text_color();
    egui::Popup::menu(&add).show(|ui| {
        // One way in for a Routine or Reminder, starting as a
        // Reminder (#344).
        let mut entries = vec![(
            icons::REMINDER,
            t.remind_me(),
            Action::NewRoutine {
                note: Some(id.clone()),
                reminder: true,
            },
        )];
        // A Note has one open Frog at a time; Frogs and Sessions are
        // made only in Advanced (#197).
        let frog_open = shown.frog.is_some_and(|f| !f.frog.is_done());
        if shown.advanced && !frog_open {
            entries.push((icons::FROG, t.frog(), Action::SpawnFrog(id.clone())));
        }
        // Only a plain Note becomes a Session, and no Code text
        // (#213); a Routine of a Session Note runs it already (#191).
        if shown.advanced
            && shown.kind.kind == NoteKind::Plain
            && note.text_format != text_format::CODE
        {
            entries.push((
                icons::SESSION,
                t.spawn_session(),
                Action::NewSession(Some(id.clone())),
            ));
        }
        for (icon, label, action) in entries {
            if menu_entry(ui, (icon, text), label).clicked() {
                actions.push(action);
                ui.close();
            }
        }
    });
}

/// The Frog's badge (#259): the frog, then Open, or Eaten today or
/// yesterday; a click offers Eat now while it is open and this Device may
/// check it off, and Remove the Frog for who may manage it (ADR 0013),
/// which asks nothing, as in the Frog view (#268). It only shows for others.
fn frog_badge(
    ui: &mut Ui,
    (t, tones): (&L10n, Tones),
    shown: &NoteFrog,
    actions: &mut Vec<Action>,
) {
    let frog = &shown.frog;
    let eats = !frog.is_done() && shown.may_check;
    let value = if !frog.is_done() {
        t.frog_open()
    } else if shown.eaten_today {
        t.frog_eaten_today()
    } else {
        t.frog_eaten_yesterday()
    };
    let value = Some(BadgeValue::Text(value));
    let active = eats || shown.manages;
    let icon = (icons::FROG, None);
    let badge = badge(ui, (t, tones), icon, t.frog(), value, active);
    if !active {
        return;
    }
    let text = ui.visuals().text_color();
    egui::Popup::menu(&badge).show(|ui| {
        if eats && menu_entry(ui, (icons::PICK_DONE, text), t.frog_eat_now()).clicked() {
            actions.push(Action::Frog(FrogAction::Toggle(frog.id.clone())));
            ui.close();
        }
        if shown.manages && menu_entry(ui, (icons::TRASH, text), t.move_to_trash()).clicked() {
            actions.push(Action::Frog(FrogAction::Delete(frog.id.clone())));
            ui.close();
        }
    });
}

/// The photos and voice recordings of the Note `id`, or of a Note merged
/// into it, each as `(shown, removed, texts)`.
struct Media<'a> {
    id: &'a str,
    photos: (&'a [String], &'a [String], &'a BTreeMap<String, String>),
    recordings: (&'a [String], &'a [String], &'a BTreeMap<String, String>),
    /// Its Attachments (#267).
    files: (
        &'a [Attachment],
        &'a [Attachment],
        &'a BTreeMap<String, String>,
    ),
}

/// What the editor may offer under the photos and recordings it shows
/// and their texts: the Transcripts are made again by `transcriber`,
/// the Photo Texts by `reader`, each one given only while it can.
struct Offering<'a> {
    view: &'a View,
    transcriber: Option<&'a Enricher>,
    reader: Option<&'a Enricher>,
    /// The Attachment Texts' (#267).
    files: Option<&'a Enricher>,
}

impl Offering<'_> {
    /// What shows under the photo, recording or file `hash` of the Note
    /// or Section `id` (ADR 0020, ADR 0025).
    fn offers(&self, id: &str, hash: &str, made: Made) -> Offers {
        let key = (id.to_string(), hash.to_string());
        let engine = match made {
            Made::Photo => self.reader,
            Made::Recording => self.transcriber,
            Made::File => self.files,
        };
        Offers {
            take_over: self.view.text_changeable.contains(id),
            remove_text: self.view.text_removable.contains(&key),
            again: engine
                .filter(|_| self.view.remakeable.contains(&key))
                .map(|e| e.busy_with(hash)),
            remove_file: self.view.removable.contains(&key),
        }
    }
}

/// What the editor shows of `media`: the photos with their Photo Texts,
/// the recordings with their play buttons and playback `speed` while
/// `can_play`, the texts of those removed where the files were
/// (ADR 0020), and under each text and file the buttons `offering`
/// gives (ADR 0025).
fn editor_media(
    ui: &mut Ui,
    t: &L10n,
    media: Media,
    (cache, store, offering): (&mut PhotoCache, &Store, &Offering),
    (playing, transcribing, can_play, speed): (Option<&str>, Option<&str>, bool, f64),
    actions: &mut Vec<Action>,
) {
    let id = media.id;
    let (photos, removed_photos, photo_texts) = media.photos;
    let (recordings, removed_recordings, transcripts) = media.recordings;
    let ask = |hash: String, made: Made| Action::AskRemoveMedia {
        note: id.to_string(),
        hash,
        made,
    };
    let text = |asked: Generated, made: Made| {
        let note = id.to_string();
        match asked {
            Generated::TakeOver { hash, append } => Action::TakeOver {
                note,
                hash,
                made,
                append,
            },
            Generated::Remove(hash) => Action::RemoveText { note, hash, made },
            Generated::Again(hash) => Action::Again { note, hash, made },
        }
    };
    let photo_offers = |hash: &str| offering.offers(id, hash, Made::Photo);
    match media_view::photos(ui, t, (cache, store), photos, photo_texts, &photo_offers) {
        Some(Photo::View(hash)) => actions.push(Action::ViewPhoto(hash)),
        Some(Photo::Remove(hash)) => actions.push(ask(hash, Made::Photo)),
        Some(Photo::Text(asked)) => actions.push(text(asked, Made::Photo)),
        Some(Photo::Out(hash, out)) => actions.push(Action::PhotoOut(hash, out)),
        None => {}
    }
    let asked = media_view::recordings(
        ui,
        t,
        recordings,
        transcripts,
        (playing, transcribing, speed),
        (can_play, true),
        &|hash| offering.offers(id, hash, Made::Recording),
    );
    match asked {
        Some(Recording::Play(hash)) => actions.push(Action::Play(hash)),
        Some(Recording::Remove(hash)) => actions.push(ask(hash, Made::Recording)),
        Some(Recording::Text(asked)) => actions.push(text(asked, Made::Recording)),
        Some(Recording::Speed(speed)) => actions.push(Action::Speed(speed)),
        None => {}
    }
    if let Some((photo, asked)) = media_view::removed_texts(
        ui,
        t,
        (removed_photos, photo_texts),
        (removed_recordings, transcripts),
        &|hash, photo| offering.offers(id, hash, made_of(photo)),
        true,
    ) {
        actions.push(text(asked, made_of(photo)));
    }
    // Its files after them (#267).
    let file_offers = |hash: &str| offering.offers(id, hash, Made::File);
    match attachment_view::editor_files(ui, t, media.files, id, &file_offers) {
        Some(attachment_view::Asked::Open(hash)) => {
            actions.push(Action::OpenAttachment(id.to_string(), hash));
        }
        Some(attachment_view::Asked::Remove(hash)) => actions.push(ask(hash, Made::File)),
        Some(attachment_view::Asked::Text(asked)) => actions.push(text(asked, Made::File)),
        None => {}
    }
}

/// A photo's (`photo`) or a recording's text.
fn made_of(photo: bool) -> Made {
    if photo { Made::Photo } else { Made::Recording }
}

/// What a card needs to show its photos and recordings.
struct CardMedia<'a> {
    photos: &'a mut PhotoCache,
    pictures: &'a mut profile_view::Pictures,
    store: &'a Store,
    /// The recording being transcribed, by its hash.
    transcribing: Option<&'a str>,
}

/// How a card shows its Note (#114, #189): `full`, its detailed view,
/// the whole Note with its `sections`, or its compact view, by its kind,
/// with the `glance` of its Tally or of the Session it runs; whether it
/// has the view button that switches it (`switches`); its Checklist or
/// Shopping List, if it is one, as it shows now, with whether this Device
/// may check its Lines, and what the card's menu offers of it once read
/// for this Note (#120, #121, #122).
#[derive(Debug, Clone, Copy)]
struct CardLook<'a> {
    full: bool,
    glance: &'a [String],
    switches: bool,
    /// Which of its folds this Device keeps open (#189).
    folds: CardFolds,
    sections: &'a [Section],
    /// The Notes that link to it, at the end of its detailed view
    /// (obf-1035).
    linked_from: &'a [Note],
    checklist: Option<(&'a Checklist, bool)>,
    shopping: Option<(&'a ShoppingList, bool)>,
    /// Whether the Note is a Tally, whose full card shows its name and
    /// description as a list's does (#188).
    tally: bool,
    /// The Tally a full card shows under them: its chart, its entries and
    /// "Add entry" (#190).
    tally_shown: Option<&'a TallyShown>,
    /// Whether the Note is a Session, shown by its name and description as
    /// a Tally is, and what a full card shows under them: its pool, today's
    /// picks and last weeks (#191).
    session: bool,
    session_shown: Option<&'a SessionCardShown>,
    menu: Option<&'a CardMenu>,
    /// What that menu offers of Routines, read as it opens (#281).
    spawns: Option<&'a CardSpawns>,
    /// Whether this Device may change its text, its tables full screen
    /// (#128).
    changes: bool,
    /// Whether this Device may change it: merge, weight, trash or
    /// restore it with the cards selected (#273).
    may: bool,
    /// How the boxes of its text and its Sections' show, by id, those of
    /// them this Device may tick, and whether Show ticks is on for it
    /// (ADR 0035).
    boxes: CardBoxes<'a>,
    /// Today's Occurrences of its Routines and Reminders, a box for each
    /// that ticks it as on the Agenda (#215).
    today: &'a [CardOccurrence],
    /// Whether it is Hidden from AI, by its own mark or another's, which
    /// a shield in its top row shows (#267).
    hidden: bool,
    /// Whether its top row names where it is filed, or Unsorted: not in
    /// the list of the Area or Topic it is in (#330).
    place: bool,
}

/// What a card's menu offers of the Note's Routines (#281): Remind me…
/// (#344) with `schedules`, Frog with `frog` and Session… with
/// `session`; and Add a part (obf-1014).
#[derive(Debug, Clone, PartialEq, Eq)]
struct CardSpawns {
    note: String,
    schedules: bool,
    frog: bool,
    session: bool,
    /// Whether Add a part opens the Note dialog with its Amend box
    /// (obf-1014): where this Device may add a Section.
    amends: bool,
    /// The switch Hidden from AI, ticked while the Note is marked itself;
    /// none while it may not be marked (#267).
    hidden: Option<bool>,
}

/// The folds of a card this Device keeps open (UI laws, "Lists"; #189):
/// a Shopping List's struck Lines and the description of a Note of a
/// kind.
#[derive(Debug, Clone, Copy, Default)]
struct CardFolds {
    struck: bool,
    description: bool,
}

/// How the boxes of the texts listed show, by id, the texts whose boxes
/// this Device may tick and whether the Note has Show ticks on.
#[derive(Debug, Clone, Copy)]
struct CardBoxes<'a> {
    looks: &'a HashMap<String, BoxLook>,
    ticks: &'a HashSet<String>,
    show: bool,
}

impl CardBoxes<'_> {
    /// How the boxes of the text `id` show.
    fn look(&self, id: &str) -> &BoxLook {
        static NONE: std::sync::OnceLock<BoxLook> = std::sync::OnceLock::new();
        self.looks
            .get(id)
            .unwrap_or_else(|| NONE.get_or_init(BoxLook::default))
    }
}

/// What can be clicked on a card: the card, the author's picture on
/// another person's Note, Edit, the photo of a full card clicked, by
/// hash, the Line checked or unchecked on it, whether its menu opened
/// and what was picked in it (#120).
struct CardClicks {
    card: egui::Response,
    author: Option<egui::Response>,
    edit: egui::Response,
    /// The view button, switching the card's view (#189).
    view: egui::Response,
    /// The setting of a fold clicked, a Shopping List's struck Lines or a
    /// description, and whether it is open now (#189).
    folded: Option<(String, bool)>,
    photo: Option<String>,
    /// The file clicked, by the Note or Section holding it and its hash
    /// (#267).
    attachment: Option<(String, String)>,
    check: Option<(String, bool)>,
    /// The box of today's Occurrence clicked, by its Routine (#215).
    occurrence: Option<(String, Occurrence)>,
    /// What a click on a box of the Note's text or a Section's asked,
    /// with that text's id (ADR 0035).
    tick: Option<(String, BoxAsk)>,
    /// The table clicked, to show full screen (#128), or copied from its
    /// ⋮ (obf-1050).
    table: Option<Action>,
    /// The tag clicked, as written (#126).
    tag: Option<String>,
    menu_opened: bool,
    picked: Option<Action>,
    /// What was asked of the Tally on a full card (#190).
    tally: Vec<TallyAction>,
    /// What was asked of the picks on a Session Note's full card (#191).
    session: Vec<SessionAction>,
}

/// The room after the last row of every list (#158): its last card,
/// emboss and shadow included, scrolls fully into view, clear of the
/// window's edge, the list's "+" being at its top.
pub(crate) const LIST_END: f32 = 24.0;

/// How far into and beyond the Note dialog's edge its border grabs.
const EDGE_IN: f32 = 4.0;
const EDGE_OUT: f32 = 6.0;

/// The Note dialog's edges and corners, `shown` around its content of
/// `size` (#278): dragged, they resize it, both sides alike as it stays
/// centred, the pointer staying on the edge. The size wanted while one
/// is dragged, and whether it was let go.
fn note_dialog_edges(
    ui: &mut Ui,
    shown: egui::Rect,
    size: egui::Vec2,
) -> Option<(egui::Vec2, bool)> {
    use egui::CursorIcon;
    let (inner, outer) = (shown.shrink(EDGE_IN), shown.expand(EDGE_OUT));
    let corner = 2.0 * (EDGE_IN + EDGE_OUT);
    let x = |left: bool| {
        if left {
            outer.left()..=inner.left()
        } else {
            inner.right()..=outer.right()
        }
    };
    let y = |top: bool| {
        if top {
            outer.top()..=inner.top()
        } else {
            inner.bottom()..=outer.bottom()
        }
    };
    // Each edge with the way it grows the dialog: -1 left or up, 1 right
    // or down, 0 not.
    let edges: [(&str, egui::Rect, egui::Vec2, CursorIcon); 8] = [
        (
            "left",
            egui::Rect::from_x_y_ranges(x(true), inner.top() + corner..=inner.bottom() - corner),
            egui::vec2(-1.0, 0.0),
            CursorIcon::ResizeHorizontal,
        ),
        (
            "right",
            egui::Rect::from_x_y_ranges(x(false), inner.top() + corner..=inner.bottom() - corner),
            egui::vec2(1.0, 0.0),
            CursorIcon::ResizeHorizontal,
        ),
        (
            "top",
            egui::Rect::from_x_y_ranges(inner.left() + corner..=inner.right() - corner, y(true)),
            egui::vec2(0.0, -1.0),
            CursorIcon::ResizeVertical,
        ),
        (
            "bottom",
            egui::Rect::from_x_y_ranges(inner.left() + corner..=inner.right() - corner, y(false)),
            egui::vec2(0.0, 1.0),
            CursorIcon::ResizeVertical,
        ),
        (
            "top left",
            egui::Rect::from_min_max(outer.min, outer.min + egui::Vec2::splat(corner)),
            egui::vec2(-1.0, -1.0),
            CursorIcon::ResizeNwSe,
        ),
        (
            "bottom right",
            egui::Rect::from_min_max(outer.max - egui::Vec2::splat(corner), outer.max),
            egui::vec2(1.0, 1.0),
            CursorIcon::ResizeNwSe,
        ),
        (
            "top right",
            egui::Rect::from_min_max(
                egui::pos2(outer.right() - corner, outer.top()),
                egui::pos2(outer.right(), outer.top() + corner),
            ),
            egui::vec2(1.0, -1.0),
            CursorIcon::ResizeNeSw,
        ),
        (
            "bottom left",
            egui::Rect::from_min_max(
                egui::pos2(outer.left(), outer.bottom() - corner),
                egui::pos2(outer.left() + corner, outer.bottom()),
            ),
            egui::vec2(-1.0, 1.0),
            CursorIcon::ResizeNeSw,
        ),
    ];
    let mut resized = None;
    for (name, rect, grows, cursor) in edges {
        // Not a stop for Tab: the keyboard has nothing to do there.
        let edge = ui.interact(rect, Id::new("note dialog edge").with(name), Sense::DRAG);
        if edge.hovered() || edge.dragged() {
            ui.ctx().set_cursor_icon(cursor);
        }
        if edge.dragged() || edge.drag_stopped() {
            // Centred, it grows on both sides by what the edge moved.
            let wanted = size + edge.drag_delta() * grows * 2.0;
            resized = Some((wanted, edge.drag_stopped()));
        }
    }
    resized
}

/// Where the window's [`App`] hands the list of the place it reached
/// how far to scroll (#278), with the frames left to try, and where the
/// list drawn tells it how far it is scrolled.
const LIST_RESTORE: &str = "list scroll restore";

/// How far above and below the list's view its cards are still laid
/// out at least (obf-1069), and the height guessed for a card not drawn
/// yet.
const CARDS_NEAR: f32 = 1000.0;
const CARD_GUESS: f32 = 160.0;

/// The least room a card takes, for how many cards around one scrolled
/// to are laid out with it (obf-1069).
const CARD_LEAST: f32 = 48.0;
const LIST_OFFSET: &str = "list scroll offset";

/// The frames a list keeps scrolling to where it was while it is
/// shorter than that, its cards still finding their height (#278).
const RESTORE_FRAMES: u8 = 10;

/// A list's vertical scrolling, as every list of the window has it: the
/// one place its end gets [`LIST_END`] of room (#158), and where a place
/// reached by back or forward scrolls to where it was left (#278).
pub(crate) fn list_scroll<R>(
    ui: &mut Ui,
    id: impl egui::AsIdSalt,
    content: impl FnOnce(&mut Ui) -> R,
) -> egui::scroll_area::ScrollAreaOutput<R> {
    let restore_id = Id::new(LIST_RESTORE);
    let restore: Option<(f32, u8)> = ui.data_mut(|d| d.remove_temp(restore_id));
    let mut area = egui::ScrollArea::vertical()
        .id_salt(id)
        .auto_shrink([false, false]);
    if let Some((offset, _)) = restore {
        area = area.vertical_scroll_offset(offset);
    }
    let output = area.show(ui, |ui| {
        let shown = content(ui);
        ui.add_space(LIST_END);
        shown
    });
    let at = output.state.offset.y;
    // Not as far as it was: tried again while its cards grow.
    if let Some((offset, frames)) = restore
        && at + 0.5 < offset
        && frames > 0
    {
        ui.data_mut(|d| d.insert_temp(restore_id, (offset, frames - 1)));
    }
    ui.data_mut(|d| d.insert_temp(Id::new(LIST_OFFSET), at));
    output
}

/// How narrow the search field of a list's band gets before the buttons
/// beside it go to the line under it (obf-1064).
const BAND_FIELD_MIN: f32 = 200.0;

/// The size of the text typed into a list's search field (obf-1063): a
/// card's text's ([`card_text`]), grown by the text size as it is.
const BAND_FIELD_TEXT: f32 = 16.0;

/// The measures of a list's header band (obf-1064), grown by the text
/// size of this Device (#326): its second row's height, the arrows'
/// side, the icons' size and the path's and title's words.
#[derive(Clone, Copy, Debug)]
struct BandSizes {
    row: f32,
    arrow: f32,
    glyph: f32,
    words: f32,
    title: f32,
}

impl BandSizes {
    fn of(ui: &Ui) -> Self {
        let factor = theme::text_factor(ui.ctx());
        Self {
            row: 36.0 * factor,
            arrow: 28.0 * factor,
            glyph: 20.0 * factor,
            words: 14.0 * factor,
            title: 22.0 * factor,
        }
    }
}

/// "+" at the top of a list (#146, #161): with one kind it makes that at
/// once, with more its menu offers them, Note first, each with its icon
/// and words; the kind picked. In a list's band, of `band`'s sizes, it
/// reads "+ New Note" in a button's frame (obf-1067); the Agenda's is
/// the icon alone.
fn add_button(
    ui: &mut Ui,
    t: &L10n,
    kinds: &[NewKind],
    band: Option<BandSizes>,
) -> Option<NewKind> {
    let text = ui.visuals().text_color();
    let button = |ui: &mut Ui, label: &str| match band {
        Some(sizes) => {
            let resp = band_button(ui, (icons::ADD, t.menu_new_note(), label), sizes, None);
            if label == t.menu_new_note() {
                resp
            } else {
                resp.on_hover_text(label)
            }
        }
        None => sized_icon_button(ui, (icons::ADD, label, text), (24.0, 20.0)),
    };
    if let [kind] = kinds {
        let add = button(ui, t.menu_new_note());
        spotlight::anchor(ui, "add", add.rect);
        return add.clicked().then_some(*kind);
    }
    let add = button(ui, t.add_here());
    spotlight::anchor(ui, "add", add.rect);
    let mut picked = None;
    egui::Popup::menu(&add).show(|ui| {
        for kind in kinds {
            let (icon, label) = match kind {
                NewKind::Note => (icons::NEW_NOTE, t.add_fan_note()),
                NewKind::Checklist => (icons::CHECKLIST, t.checklist_heading()),
                NewKind::Shopping => (icons::SHOPPING_CART, t.shopping_heading()),
                NewKind::Tally => (icons::TALLY, t.tally_heading()),
                NewKind::Session => (icons::SESSION, t.session()),
                NewKind::Frog => (icons::FROG, t.frog()),
                NewKind::Topic => (icons::NO_AREA_ICON, t.new_topic()),
            };
            if menu_entry(ui, (icon, text), label).clicked() {
                picked = Some(*kind);
                ui.close();
            }
        }
    });
    picked
}

/// The bar button of a Note list's compact/detailed switch (#114, #189):
/// its icon and "View" in a button's frame (obf-1067), one height with
/// the band's row (obf-1064); it says what clicking it does to a screen
/// reader and in its tooltip and shows as selected while the list is
/// `compact`; whether it was clicked.
fn compact_button(ui: &mut Ui, tones: Tones, t: &L10n, compact: bool, sizes: BandSizes) -> bool {
    let (icon, label) = if compact {
        (icons::NOTES_COMPACT, t.show_notes_full())
    } else {
        (icons::NOTES_FULL, t.show_notes_compact())
    };
    let selected = Some((compact, tones.accent));
    let resp = band_button(ui, (icon, t.menu_view(), label), sizes, selected);
    spotlight::anchor(ui, "compact", resp.rect);
    resp.on_hover_text(label).clicked()
}

/// How wide [`band_button`] draws `word` with its icon.
fn band_button_width(ui: &Ui, word: &str, sizes: BandSizes) -> f32 {
    let font = FontId::proportional(sizes.words);
    let colour = ui.visuals().text_color();
    let words = ui.painter().layout_no_wrap(word.to_string(), font, colour);
    let pad = ui.spacing().button_padding.x;
    pad + sizes.glyph + ui.spacing().icon_spacing + words.size().x + pad
}

/// A button of the band's second row (obf-1067): `icon` and `word` in
/// the frame "Show Notes by…" has, as tall as the row, `label` to a
/// screen reader; with `selected`, a switch, tinted with its accent
/// while on.
fn band_button(
    ui: &mut Ui,
    (icon, word, label): (char, &str, &str),
    sizes: BandSizes,
    selected: Option<(bool, Color32)>,
) -> egui::Response {
    let width = band_button_width(ui, word, sizes);
    let (rect, resp) = ui.allocate_exact_size(egui::vec2(width, sizes.row), Sense::click());
    // Greyed where the ui is, to a screen reader too.
    let enabled = ui.is_enabled();
    resp.widget_info(|| match selected {
        Some((on, _)) => WidgetInfo::selected(WidgetType::Button, enabled, on, label),
        None => WidgetInfo::labeled(WidgetType::Button, enabled, label),
    });
    if ui.is_rect_visible(rect) {
        // The frame egui's button paints, for this state.
        let look = *ui.style().visuals.widgets.state(resp.widget_state());
        let frame = rect.expand(look.expansion);
        ui.painter().rect(
            frame,
            look.corner_radius,
            look.weak_bg_fill,
            look.bg_stroke,
            egui::StrokeKind::Inside,
        );
        if let Some((true, accent)) = selected {
            let fill = accent.gamma_multiply(0.3);
            ui.painter().rect_filled(frame, look.corner_radius, fill);
        }
        let text = ui.visuals().text_color();
        let pad = ui.spacing().button_padding.x;
        let glyph = egui::vec2(sizes.glyph, sizes.glyph);
        let at = egui::Rect::from_min_size(
            egui::pos2(rect.left() + pad, rect.center().y - sizes.glyph / 2.0),
            glyph,
        );
        icons::paint(ui.painter(), at, icon, text);
        let font = FontId::proportional(sizes.words);
        let words = ui.painter().layout_no_wrap(word.to_string(), font, text);
        let left = at.right() + ui.spacing().icon_spacing;
        let top = rect.center().y - words.size().y / 2.0;
        ui.painter().galley(egui::pos2(left, top), words, text);
    }
    if let Some(cursor) = ui.visuals().interact_cursor
        && resp.hovered()
    {
        ui.ctx().set_cursor_icon(cursor);
    }
    resp
}

/// A text edited in the Note dialog: the Note's, or a Section's (#183)
/// in the same field, with the same format bar and the same rules.
struct EditedText<'a> {
    /// The field's id.
    id: Id,
    /// The Note or Section whose text it is, and whether a Section's.
    of: &'a str,
    section: bool,
    /// Its text as stored, and whether it is a formatted one.
    stored: &'a str,
    formatted: bool,
    /// Whether it is a Code text (#213), the scope of the grammar it is
    /// coloured by (obf-1036), and whether a paste that looks like code
    /// offers it.
    code: bool,
    language: Option<&'a str>,
    offers_code: bool,
    /// Whether the format bar shows above it: only in Advanced (#197);
    /// typed Markdown and Ctrl+B and Ctrl+I format either way.
    bar: bool,
    /// How its boxes show, whether this Device may tick them and which
    /// were ticked (ADR 0035).
    boxes: &'a BoxLook,
    ticks: (bool, &'a dyn Fn(&str) -> bool),
    /// What a screen reader calls the field.
    name: &'a str,
    /// The size and colour of its text: a description's smaller and
    /// weaker (#188).
    look: (f32, Color32),
    /// What it says while empty.
    hint: Option<&'a str>,
}

/// The field of a text of the Note dialog, `edit`, its format bar above
/// it (#127): `edited` as it is being edited, whether it is (a formatted
/// text shows its source meanwhile, as it reads otherwise), and whether
/// it is to take the keyboard, once, with the selection `select`; a Save
/// under it while it changed.
fn edited_text(
    ui: &mut Ui,
    (t, tones): (L10n, Tones),
    edit: EditedText<'_>,
    (edited, editing, focus, select): (
        &mut String,
        &mut bool,
        &mut bool,
        &mut Option<(usize, usize)>,
    ),
    actions: &mut Vec<Action>,
) {
    let text = ui.visuals().text_color();
    let (size, written) = edit.look;
    // Typed at the Device's text size (#326, obf-1019); what reads at
    // `size` grows in its own drawing.
    let typed_size = theme::content(ui, size);
    let (formatted, boxes) = (edit.formatted, edit.boxes);
    // Kept as a formatted text at once: the Note's, or the Section's.
    let format_text = || Action::FormatText(edit.section.then(|| edit.of.to_string()));
    let id = edit.id;
    let of = edit.of;
    let as_code = edit.code;
    let focused = ui.memory(|m| m.has_focus(id));
    // Its tables as grids while it is edited (#257).
    let grids = (formatted && !as_code && (*editing || focused)).then(|| {
        let look = GridLook {
            size,
            colour: written,
            boxes,
        };
        Grids::prepare(ui, (id, of), edited, look)
    });
    let in_cell = grids.as_ref().is_some_and(|g| g.cell_focused(ui));
    if focused || in_cell {
        *editing = true;
        // Not past a dialog over the Note dialog, whose key it is (#277).
        if theme::ctrl_enter(ui) {
            actions.push(Action::SaveText);
        }
    }
    // The format bar above the field (#127), on its
    // selection as the field last had it; Ctrl+B and
    // Ctrl+I as its bold and italic while typing. In a
    // cell of a grid, on the cell's words.
    let selected = format_bar::selection(ui, id, edited);
    let at = match grids.as_ref().and_then(|g| g.cell_selection(ui)) {
        Some((words, chosen)) => format_bar::At::of(&words, chosen, true),
        None => format_bar::At::of(edited, selected, formatted),
    };
    // A Code text has none (#213).
    let mut picked = match as_code || !edit.bar {
        true => None,
        false => format_bar::bar(ui, &t, &at, (text, tones.accent), &Format::ALL),
    };
    if (focused || in_cell) && !as_code {
        ui.input_mut(|i| {
            if i.consume_key(Modifiers::COMMAND, Key::B) {
                picked = Some(Format::Bold);
            } else if i.consume_key(Modifiers::COMMAND, Key::I) {
                picked = Some(Format::Italic);
            }
        });
    }
    let mut took = false;
    if formatted && !*editing {
        // As it reads; a click on it edits its source.
        let all = (0, edited.len());
        let shown = ui.scope(|ui| {
            text_marks_view::formatted_label(
                ui,
                (edited, text_format::MARKDOWN, boxes),
                all,
                (Some(size), written),
                false,
            )
        });
        let read = Id::new(("read", of));
        let open = ui.interact(shown.response.rect, read, Sense::click());
        open.widget_info(|| WidgetInfo::labeled(WidgetType::Button, true, t.edit()));
        if open.on_hover_cursor(egui::CursorIcon::Text).clicked() {
            *editing = true;
            *focus = true;
        }
        let spots = shown.inner;
        let marked = Id::new(("field", of));
        // A click on a table edits the cell clicked in its
        // grid (#257).
        // Its ⋮ copies it, or deletes or moves it in the grids, a step
        // of the Note's Undo there (obf-1050).
        match text_marks_view::table_clicks(ui, &t, marked, &spots.tables, true) {
            Some((at, TableAct::Open)) => {
                let pointer = ui.input(|i| i.pointer.interact_pos());
                let cell = spots.cell_at(at, pointer).unwrap_or((0, 0));
                *editing = true;
                table_grid::edit(ui, (id, of), edited, at, cell);
            }
            Some((at, TableAct::Copy)) => {
                let copy = markdown::table::copy(edited, at, &boxes.states);
                actions.extend(copy.map(Action::CopyTable));
            }
            Some((at, act)) => {
                *editing = true;
                table_grid::act(ui, (id, of), edited, at, act);
            }
            None => {}
        }
        // A tick is no edit: what is typed stays.
        if let Some(asked) = text_marks_view::box_clicks(ui, &t, marked, &spots.boxes, edit.ticks) {
            actions.push(box_action(of.to_string(), asked));
        }
        if let Some(tag) = text_marks_view::tag_clicks(ui, &t, marked, &spots.tags) {
            actions.push(Action::SearchFor(tag));
        }
        text_marks_view::link_clicks(ui, marked, &spots.links);
    } else {
        // Its tags in the accent colour, a formatted text's
        // marks dimmed; a click on a tag places the cursor,
        // as anywhere in the field (#126). Its boxes as they
        // show, their ids not drawn (ADR 0035), with Show
        // ticks room after each for who ticked it.
        let accent = ui.visuals().hyperlink_color;
        let weak = ui.visuals().weak_text_color();
        let code = ui.visuals().code_bg_color;
        let dark = ui.visuals().dark_mode;
        let small = egui::TextStyle::Small.resolve(ui.style());
        let grammars = text_marks_view::grammars(ui.ctx());
        let grammar = grammars.by_scope(edit.language);
        let typed_format = match (as_code, formatted) {
            (true, _) => text_format::CODE,
            (false, true) => text_format::MARKDOWN,
            (false, false) => text_format::PLAIN,
        };
        let mut layouter = |ui: &Ui, typed: &dyn egui::TextBuffer, width: f32| {
            let typed = typed.as_str();
            let font = FontId::proportional(typed_size);
            // A Code text as written in the fixed-width font, unwrapped,
            // coloured by its language (obf-1036).
            if as_code {
                let format = egui::TextFormat::simple(FontId::monospace(typed_size * 0.9), written);
                let mut job = egui::text::LayoutJob::single_section(typed.to_string(), format);
                if let Some(grammar) = grammar {
                    let colours = text_marks_view::code_colours(ui.ctx(), grammar, typed);
                    text_marks_view::paint_code(&mut job, 0, &colours, dark);
                }
                // The places the find bar found (obf-1047).
                find_marks::mark_typed(ui.ctx(), &mut job, (typed, text_format::CODE), dark);
                return ui.fonts_mut(|f| f.layout_job(job));
            }
            let (job, lines) = if formatted {
                let colours = (written, accent, weak, code);
                let (mut job, lines) = text_marks_view::source_job(typed, font.clone(), colours);
                // Its code blocks coloured by the language their fences
                // name (obf-1036).
                let fences = text_marks_view::fence_colours(ui.ctx(), typed);
                text_marks_view::paint_code(&mut job, 0, &fences, dark);
                (job, lines)
            } else {
                let job = text_marks_view::tag_job(
                    typed,
                    (0, typed.len()),
                    font.clone(),
                    (written, accent),
                );
                (job, Vec::new())
            };
            let gap = |after: &str| {
                let said = after.to_string();
                let galley = ui.fonts_mut(|f| f.layout_no_wrap(said, small.clone(), weak));
                galley.size().x + 8.0
            };
            let mut job = text_marks_view::field_job(job, boxes, &gap);
            if let Some(grids) = &grids {
                job = grids.hide(typed, job);
            }
            // The places the find bar found (obf-1047); none in a table's
            // source hidden under its grid.
            find_marks::mark_typed(ui.ctx(), &mut job, (typed, typed_format), dark);
            job.wrap.max_width = width;
            let galley = ui.fonts_mut(|f| f.layout_job(job));
            if !formatted {
                return galley;
            }
            // As far apart as the text reads (#327).
            let extra = text_marks_view::line_extra(ui, &font, text_marks_view::LINE_HEIGHT);
            text_marks_view::source_spread(galley, &lines, typed_size, extra)
        };
        // Pasted, a text that looks like code offers it and formats
        // nothing (#213); else pasted with a format, a plain text
        // becomes a formatted one (ADR 0033).
        // With the language guessed for it (obf-1036).
        let pasted_code = (edit.offers_code && focused)
            .then(|| {
                ui.input(|i| {
                    i.events.iter().find_map(|e| match e {
                        egui::Event::Paste(p)
                            if p.chars().nth(1).is_some() && text_format::looks_like_code(p) =>
                        {
                            Some(grammars.guess(p).map(|g| g.scope.clone()))
                        }
                        _ => None,
                    })
                })
            })
            .flatten();
        let pasted = pasted_code.is_none()
            && focused
            && ui.input(|i| {
                i.events
                    .iter()
                    .any(|e| matches!(e, egui::Event::Paste(p) if markdown::uses(p)))
            });
        let placed = *focus && select.is_some();
        // Not in the dialog's first, sizing pass, which
        // drops a focus.
        if !ui.is_sizing_pass() && std::mem::take(focus) {
            let typed = egui::widgets::text_edit::TextEditState::load(ui.ctx(), id)
                .and_then(|s| s.cursor.char_range())
                .is_some();
            match select.take() {
                Some(range) => format_bar::select(ui, id, edited, range),
                // Never typed into: the cursor at the end.
                None if !typed => {
                    let end = edited.len();
                    format_bar::select(ui, id, edited, (end, end));
                }
                None => ui.memory_mut(|m| m.request_focus(id)),
            }
        }
        // A box goes whole, its id with it, and the cursor
        // stays where it was as a save gives boxes ids.
        let cut = text_marks_view::guard_field(ui, id, edited, !placed);
        // As wide as its longest line, for a Code text, which moves
        // sideways (#213).
        let widest = as_code.then(|| {
            let font = FontId::monospace(typed_size * 0.9);
            let galley = ui.fonts_mut(|f| f.layout_no_wrap(edited.clone(), font, written));
            galley.size().x + 8.0
        });
        let mut field = TextEdit::multiline(edited)
            .id(id)
            .font(FontId::proportional(typed_size))
            .layouter(&mut layouter)
            .desired_rows(1)
            .desired_width(f32::INFINITY)
            .frame(Frame::NONE);
        if let Some(hint) = edit.hint {
            field = field.hint_text(RichText::new(hint).size(typed_size).color(weak));
        }
        let output = match widest {
            None => field.show(ui),
            Some(widest) => {
                Frame::NONE
                    .fill(code)
                    .corner_radius(4.0)
                    .inner_margin(egui::Margin::symmetric(8, 6))
                    .show(ui, |ui| {
                        egui::ScrollArea::horizontal()
                            .id_salt(("code", of))
                            .show(ui, |ui| {
                                let width = widest.max(ui.available_width());
                                let room = egui::vec2(width, ui.available_height());
                                let rect = egui::Rect::from_min_size(ui.cursor().min, room);
                                ui.scope_builder(egui::UiBuilder::new().max_rect(rect), |ui| {
                                    field.show(ui)
                                })
                                .inner
                            })
                            .inner
                    })
                    .inner
            }
        };
        // Its right-click menu, with the bar's formats for a selection
        // in a formatted text (#253).
        let offered: &[Format] = if formatted && edit.bar && !as_code {
            &Format::ALL
        } else {
            &[]
        };
        match text_menu::menu(ui, &t, &output.response.response, edited, offered) {
            Some(MenuPick::Format(format)) => picked = Some(format),
            Some(pick) => text_menu::apply(ui, id, edited, pick),
            None => {}
        }
        text_marks_view::guard_cursor(ui, id, edited);
        if cut {
            ui.ctx().request_repaint();
        }
        let place = (&*output.galley, output.galley_pos);
        text_marks_view::reveal_typed(ui, place, (edited, typed_format));
        name_field(ui, &output.response.response, edit.name);
        // With Show ticks, who ticked each box, after it; a
        // click on a box ticks it, no edit of the text (ADR
        // 0035). The grids take those in their cells.
        let place = (&output.galley, output.galley_pos);
        let mut spots =
            text_marks_view::field_spots(&output.galley, output.galley_pos, edited, boxes);
        let mut grid = table_grid::Outcome::default();
        if let Some(grids) = grids {
            spots = grids.outside(&output, edited, spots);
            let outside = grids.look_outside(edited, boxes);
            text_marks_view::paint_after(ui, place, (edited, &outside), (small.clone(), weak));
            let shown = (&output, &mut *edited);
            grid = grids.show(ui, (&t, tones), shown, (picked, boxes, edit.ticks));
        } else {
            text_marks_view::paint_after(ui, place, (edited, boxes), (small.clone(), weak));
        }
        if grid.took {
            took = true;
        }
        if let Some((start, end, url)) = grid.link.take() {
            actions.push(Action::AskLink {
                start,
                end,
                url,
                amend: false,
                section: edit.section.then(|| of.to_string()),
                pick: false,
            });
        }
        if let Some(asked) = grid.boxes.take() {
            actions.push(box_action(of.to_string(), asked));
        }
        // A menu of a grid changed the text whole: a step of its own
        // (obf-1051).
        if let Some(before) = grid.whole.take() {
            actions.push(Action::WholeStep {
                section: edit.section.then(|| of.to_string()),
                before,
            });
        }
        // A table's ⋮ Copy (obf-1050).
        actions.extend(grid.copy.take().map(Action::CopyTable));
        // A click on the bar keeps the field being edited,
        // and so does the keyboard going into a cell of its
        // grids or back.
        let lost = output.response.response.lost_focus() && picked.is_none() && !grid.holds;
        if lost || grid.left {
            *editing = false;
            actions.push(Action::SaveText);
        }
        if let Some(guess) = pasted_code.filter(|_| output.response.response.changed()) {
            actions.push(Action::OfferCode(true, guess));
        }
        // A shortcut typed makes a plain text a formatted
        // one, as the first format from the bar does.
        if output.response.response.changed() && !formatted && !as_code {
            let cursor = output.cursor_range.map_or(0, |range| range.primary.index.0);
            let byte = edited
                .char_indices()
                .nth(cursor)
                .map_or(edited.len(), |(b, _)| b);
            if pasted || markdown::shortcut_at(edited, byte) {
                actions.push(format_text());
            }
        }
        // A task list item typed or pasted into a formatted text becomes
        // an item with a box (#263), on the lines up to the cursor that
        // the change touched: typed, `- [ ] ` turns into `- ☐ ` at its
        // space.
        if output.response.response.changed() && (formatted || pasted) && !as_code {
            let (_, cursor) = format_bar::selection(ui, id, edited);
            let brought: usize = ui.input(|i| {
                i.events
                    .iter()
                    .map(|e| match e {
                        egui::Event::Paste(p) => p.len(),
                        _ => 0,
                    })
                    .sum()
            });
            let change = markdown::task_boxes(edited, cursor.saturating_sub(brought), cursor);
            if change.text != *edited {
                *edited = change.text;
                // Both glyphs are as many bytes as the marks they replace.
                format_bar::select(ui, id, edited, (cursor, cursor));
                ui.ctx().request_repaint();
            }
        }
        let marked = Id::new(("field", of));
        if let Some(asked) = text_marks_view::box_clicks(ui, &t, marked, &spots, edit.ticks) {
            actions.push(box_action(of.to_string(), asked));
        }
    }
    // What the bar did in a cell of a grid is done.
    let picked = if took { None } else { picked };
    match picked {
        // In a table shown as lines it shows it as a grid;
        // elsewhere it puts a new one in and edits its first
        // cell in its grid (#257), the text formatted from
        // then on.
        Some(Format::Table) => {
            *editing = true;
            match markdown::table::at(edited, selected.0) {
                Some(table) => {
                    let cell = table_grid::cell_at(edited, &table, selected.0);
                    table_grid::edit(ui, (id, of), edited, table.start, cell);
                }
                None => {
                    let change = markdown::table::insert(edited, selected.0);
                    *edited = change.text;
                    actions.push(if formatted {
                        Action::SaveText
                    } else {
                        format_text()
                    });
                    table_grid::edit(ui, (id, of), edited, change.start, (0, 0));
                }
            }
        }
        Some(Format::Link) => {
            *editing = true;
            actions.push(Action::AskLink {
                start: selected.0,
                end: selected.1,
                url: at.url.clone(),
                amend: false,
                section: edit.section.then(|| of.to_string()),
                pick: false,
            });
        }
        Some(Format::LinkTo) => {
            *editing = true;
            actions.push(Action::AskLink {
                start: selected.0,
                end: selected.1,
                url: None,
                amend: false,
                section: edit.section.then(|| of.to_string()),
                pick: true,
            });
        }
        Some(format) => {
            *editing = true;
            match format_bar::change(format, edited, selected) {
                Some(changed) => {
                    *edited = changed.text;
                    let range = (changed.start, changed.end);
                    format_bar::select(ui, id, edited, range);
                    // The first format makes it a formatted
                    // text, kept at once.
                    if format != Format::Mark && !formatted {
                        actions.push(format_text());
                    }
                }
                None => ui.memory_mut(|m| m.request_focus(id)),
            }
        }
        None => {}
    }
    text_marks_view::remember_text(ui, id, edited);
    ui.horizontal(|ui| {
        let changed = edited.trim();
        if !changed.is_empty()
            && changed != edit.stored
            && theme::primary(ui, true, t.save()).clicked()
        {
            actions.push(Action::SaveText);
        }
    });
}

/// The size of the name of a Note of a kind (#188), a heading, and of
/// its description, smaller than a text.
const NAME_SIZE: f32 = 22.0;
const DESCRIPTION_SIZE: f32 = 14.0;

/// The text of a Note of a kind in the Note dialog (#188): the Note,
/// whether this Device may change its text here, how its boxes show,
/// whether it may tick them and which were ticked (ADR 0035).
struct KindedText<'a> {
    note: &'a Note,
    writes: bool,
    /// Whether the description's format bar shows: only in Advanced
    /// (#197).
    bar: bool,
    /// Whether an empty description waits for "Add a description": a
    /// Checklist's, a Shopping List's and a Tally's (obf-1071), not a
    /// Session's.
    asks: bool,
    boxes: &'a BoxLook,
    ticks: (bool, &'a dyn Fn(&str) -> bool),
}

/// What is typed into the text of a Note of a kind: its name, and its
/// description as [`edited_text`] edits it.
type KindedState<'a> = (
    &'a mut String,
    (
        &'a mut String,
        &'a mut bool,
        &'a mut bool,
        &'a mut Option<(usize, usize)>,
    ),
);

/// The text of a Note of a kind as its name, a heading on one line, and
/// its description under it (#188), small and weak, folded to its first
/// line while it is not edited: a click unfolds it, into its field where
/// this Device may change it. An empty one there is "Add a description"
/// on a Checklist, a Shopping List and a Tally (obf-1071), which opens
/// its field until it is left empty, and its field on a Session. Read
/// only, both select to be copied (#183) and a click folds the
/// description again.
fn kinded_text(
    ui: &mut Ui,
    (t, tones): (L10n, Tones),
    shown: KindedText<'_>,
    (name, (edited, editing, focus, select)): KindedState<'_>,
    actions: &mut Vec<Action>,
) {
    let note = shown.note;
    let text = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    let formatted = note.text_format == text_format::MARKDOWN;
    if !shown.writes {
        ui.style_mut().interaction.selectable_labels = true;
        let whole = note.text.as_str();
        let look = (whole, note.text_format.as_str(), shown.boxes);
        // In the offsets of the whole text, as its boxes, tables, tags
        // and links are found.
        let named = note_kinds::name(whole).len();
        let mut spots = Spots::default();
        if note_kinds::name(whole).trim().is_empty() {
            // A list without a name by its kind (#309).
            if let Some(kind) = l10n::untitled_list(&t, note) {
                ui.label(
                    RichText::new(kind)
                        .size(theme::content(ui, NAME_SIZE))
                        .color(text),
                );
            }
        } else if named > 0 {
            let heading = (Some(NAME_SIZE), text);
            let label = read_text::shown(ui, |ui| {
                text_marks_view::formatted_label(ui, look, (0, named), heading, false)
            });
            spots.extend(label);
        }
        let description = note_kinds::description(whole);
        let start = whole.len() - description.len();
        if let Some((from, to)) = first_line(description) {
            let id = Id::new(("description open", &note.id));
            let open = ui.data(|d| d.get_temp::<bool>(id)).unwrap_or(false);
            let range = if open {
                (start, whole.len())
            } else {
                (start + from, start + to)
            };
            let small = (Some(DESCRIPTION_SIZE), weak);
            let drawn = folded_row(ui, open, |ui| {
                read_text::shown(ui, |ui| {
                    text_marks_view::formatted_label(ui, look, range, small, !open)
                })
            });
            if description_fold(ui, &t, (drawn.response.rect, id), open) {
                ui.data_mut(|d| d.insert_temp(id, !open));
            }
            spots.extend(drawn.inner);
        }
        let of = Id::new(("text", &note.id));
        // Its tables open to read (#128).
        if let Some((at, act)) = text_marks_view::table_clicks(ui, &t, of, &spots.tables, false) {
            actions.extend(table_action(
                act,
                Opening {
                    note: None,
                    text: note.text.clone(),
                    at,
                    cell: None,
                    tags: true,
                    boxes: Some(note.id.clone()),
                },
                shown.boxes,
            ));
        }
        // A Member ticks the boxes of a Note not theirs.
        if let Some(asked) = text_marks_view::box_clicks(ui, &t, of, &spots.boxes, shown.ticks) {
            actions.push(box_action(note.id.clone(), asked));
        }
        if let Some(tag) = text_marks_view::tag_clicks(ui, &t, of, &spots.tags) {
            actions.push(Action::SearchFor(tag));
        }
        text_marks_view::link_clicks(ui, of, &spots.links);
        return;
    }
    // Enter in the name goes on at the start of the description.
    if name_edit(ui, &t, (name, &note.id), (formatted, shown.boxes), actions) {
        *editing = true;
        *focus = true;
        *select = Some((0, 0));
    }
    let id = Id::new(("note text", &note.id));
    let open = *editing || ui.memory(|m| m.has_focus(id));
    if open {
        let field = EditedText {
            id,
            of: &note.id,
            section: false,
            stored: note_kinds::description(&note.text),
            formatted,
            code: false,
            language: None,
            offers_code: false,
            bar: shown.bar,
            boxes: shown.boxes,
            ticks: shown.ticks,
            name: t.note_description(),
            look: (DESCRIPTION_SIZE, weak),
            hint: Some(t.note_description()),
        };
        edited_text(
            ui,
            (t, tones),
            field,
            (edited, editing, focus, select),
            actions,
        );
    } else if edited.trim().is_empty() && shown.asks {
        // Empty, only a way into its field (obf-1071), small and weak
        // as the description is.
        let asked = RichText::new(t.desk_add_description())
            .size(theme::content(ui, DESCRIPTION_SIZE))
            .color(weak);
        if ui.add(egui::Button::new(asked).frame(false)).clicked() {
            *editing = true;
            *focus = true;
        }
    } else if edited.trim().is_empty() {
        // Empty, its field with its hint; typed into, it is edited.
        let hint = RichText::new(t.note_description())
            .size(theme::content(ui, DESCRIPTION_SIZE))
            .color(weak);
        let field = ui.add(
            TextEdit::multiline(edited)
                .id(id)
                .font(FontId::proportional(theme::content(ui, DESCRIPTION_SIZE)))
                .text_color(weak)
                .hint_text(hint)
                .desired_rows(1)
                .desired_width(f32::INFINITY)
                .frame(Frame::NONE),
        );
        text_menu::show(ui, &t, &field, edited);
        name_field(ui, &field, t.note_description());
        if field.has_focus() {
            *editing = true;
        }
    } else {
        // Folded to its first line with words, as typed.
        let range = first_line(edited).unwrap_or((0, 0));
        let look = (edited.as_str(), note.text_format.as_str(), shown.boxes);
        let small = (Some(DESCRIPTION_SIZE), weak);
        let drawn = folded_row(ui, false, |ui| {
            text_marks_view::formatted_label(ui, look, range, small, true)
        });
        let fold = Id::new(("description open", &note.id));
        if description_fold(ui, &t, (drawn.response.rect, fold), false) {
            *editing = true;
            *focus = true;
        }
        // Its boxes tick and its tags and links open, folded too.
        let spots = drawn.inner;
        let marked = Id::new(("field", &note.id));
        if let Some(asked) = text_marks_view::box_clicks(ui, &t, marked, &spots.boxes, shown.ticks)
        {
            actions.push(box_action(note.id.clone(), asked));
        }
        if let Some(tag) = text_marks_view::tag_clicks(ui, &t, marked, &spots.tags) {
            actions.push(Action::SearchFor(tag));
        }
        text_marks_view::link_clicks(ui, marked, &spots.links);
    }
}

/// The name of a Note of a kind being edited (#188): one line, as a
/// heading, its tags marked and its boxes as they show (ADR 0035), a
/// formatted text's marks dimmed. Leaving it keeps it; Enter goes on in
/// the description, which `true` says. A line break pasted becomes a
/// space, as in any one-line field.
fn name_edit(
    ui: &mut Ui,
    t: &L10n,
    (name, of): (&mut String, &str),
    (formatted, boxes): (bool, &BoxLook),
    actions: &mut Vec<Action>,
) -> bool {
    let id = Id::new(("note name", of));
    let text = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    let accent = ui.visuals().hyperlink_color;
    let code = ui.visuals().code_bg_color;
    let mut moved = false;
    if ui.memory(|m| m.has_focus(id)) && theme::on_top(ui) {
        ui.input_mut(|i| {
            if i.consume_key(Modifiers::COMMAND, Key::Enter) {
                actions.push(Action::SaveText);
            } else if i.consume_key(Modifiers::NONE, Key::Enter) {
                moved = true;
            }
        });
    }
    let typed_format = if formatted {
        text_format::MARKDOWN
    } else {
        text_format::PLAIN
    };
    let mut layouter = |ui: &Ui, typed: &dyn egui::TextBuffer, width: f32| {
        let typed = typed.as_str();
        let font = FontId::proportional(theme::content(ui, NAME_SIZE));
        let job = if formatted {
            text_marks_view::source_job(typed, font, (text, accent, weak, code)).0
        } else {
            text_marks_view::tag_job(typed, (0, typed.len()), font, (text, accent))
        };
        let mut job = text_marks_view::field_job(job, boxes, &|_: &str| 0.0);
        // The places the find bar found (obf-1047).
        let dark = ui.visuals().dark_mode;
        find_marks::mark_typed(ui.ctx(), &mut job, (typed, typed_format), dark);
        job.wrap.max_width = width;
        ui.fonts_mut(|f| f.layout_job(job))
    };
    let cut = text_marks_view::guard_field(ui, id, name, true);
    let output = TextEdit::singleline(name)
        .id(id)
        .font(FontId::proportional(theme::content(ui, NAME_SIZE)))
        .layouter(&mut layouter)
        .hint_text(
            RichText::new(t.note_name())
                .size(theme::content(ui, NAME_SIZE))
                .color(weak),
        )
        .desired_width(f32::INFINITY)
        .return_key(None)
        .frame(Frame::NONE)
        .show(ui);
    text_menu::show(ui, t, &output.response.response, name);
    text_marks_view::guard_cursor(ui, id, name);
    if cut {
        ui.ctx().request_repaint();
    }
    let place = (&*output.galley, output.galley_pos);
    text_marks_view::reveal_typed(ui, place, (name, typed_format));
    text_marks_view::remember_text(ui, id, name);
    let field = &output.response.response;
    name_field(ui, field, t.note_name());
    if moved {
        ui.memory_mut(|m| m.surrender_focus(id));
    } else if field.lost_focus() {
        actions.push(Action::SaveText);
    }
    moved
}

/// A description of a Note of a kind as `add` draws it, folded or
/// `open`, after the sign of which it is (#188).
fn folded_row<R>(
    ui: &mut Ui,
    open: bool,
    add: impl FnOnce(&mut Ui) -> R,
) -> egui::InnerResponse<R> {
    let weak = ui.visuals().weak_text_color();
    ui.horizontal_top(|ui| {
        let icon = if open {
            icons::EXPAND_LESS
        } else {
            icons::EXPAND_MORE
        };
        icons::show(ui, icon, 16.0, weak);
        ui.vertical(add).inner
    })
}

/// Whether the description drawn at `rect` was clicked to unfold it, or
/// to fold it while `open` (#188); a screen reader reads what the click
/// does.
fn description_fold(ui: &mut Ui, t: &L10n, (rect, id): (egui::Rect, Id), open: bool) -> bool {
    let said = if open {
        t.note_description_fold()
    } else {
        t.note_description_unfold()
    };
    let fold = ui.interact(rect, id.with("fold"), Sense::click());
    fold.widget_info(|| WidgetInfo::labeled(WidgetType::Button, true, said));
    fold.on_hover_cursor(egui::CursorIcon::PointingHand)
        .on_hover_text(said)
        .clicked()
}

/// What was done to a table of a text only read (obf-1050), as an
/// action: a click opens it as `opening` says, its ⋮ Copy puts it on the
/// clipboard, each box as `look` shows it.
fn table_action(act: TableAct, opening: Opening, look: &BoxLook) -> Option<Action> {
    match act {
        TableAct::Open => Some(Action::OpenTable(opening)),
        TableAct::Copy => {
            markdown::table::copy(&opening.text, opening.at, &look.states).map(Action::CopyTable)
        }
        TableAct::Up | TableAct::Down | TableAct::Delete => None,
    }
}

/// What a click on a box of the text `entity` asked, as an action.
fn box_action(entity: String, asked: BoxAsk) -> Action {
    match asked {
        BoxAsk::Tick(id, to) => Action::Tick { entity, id, to },
        BoxAsk::History(id) => Action::BoxHistory { entity, id },
    }
}

/// Whether a box of `look` has been ticked: it offers its History then.
fn ticked_in(boxes: &[ShownBox]) -> impl Fn(&str) -> bool + '_ {
    move |id| boxes.iter().any(|b| b.id == id && b.last.is_some())
}

/// What a find bar over `note` and its `sections` finds in, as one key
/// that changes with any text it finds in (obf-1047); in the reading
/// view, `texts`, a key of its own.
fn found_in(note: &Note, sections: &[Section], texts: bool) -> u64 {
    let names = |files: &[oldbrainfix_core::Attachment]| -> Vec<String> {
        files.iter().map(|f| f.name.clone()).collect()
    };
    let part = |text: &str, media: [&BTreeMap<String, String>; 3], files: Vec<String>| {
        Id::new((text, media, files)).value()
    };
    let mut keys = vec![
        u64::from(texts),
        part(
            &note.text,
            [&note.transcripts, &note.photo_texts, &note.attachment_texts],
            names(&note.attachments),
        ),
    ];
    for s in sections {
        let media = [&s.transcripts, &s.photo_texts, &s.attachment_texts];
        keys.push(part(&s.text, media, names(&s.attachments)));
    }
    Id::new(keys).value()
}

/// Where `finding` lies as [`find_marks::Current`] names it: in the text
/// of `note` or of one of its `sections` as it is drawn, a text's
/// source, a Transcript, a Photo Text, an Attachment Text or a file's
/// name; with `split`, the Note's own text as its name and description
/// are drawn apart (#188).
fn finding_text(
    note: &Note,
    sections: &[Section],
    finding: &Finding,
    split: bool,
) -> Option<find_marks::Current> {
    let at = |text: &str, start: usize| find_marks::Current {
        text: find_marks::text_key(text),
        start,
    };
    if split && finding.part == FindingPart::Text && finding.section.is_none() {
        let whole = note.text.as_str();
        let name = note_kinds::name(whole);
        let description = note_kinds::description(whole);
        let from = whole.len() - description.len();
        // Where the description begins as the whole text shows.
        let shown = find_marks::shown_of(whole.get(..from).unwrap_or_default())
            .0
            .len();
        return Some(match finding.start.checked_sub(shown) {
            Some(start) => at(description, start),
            None => at(name, finding.start),
        });
    }
    let section = match &finding.section {
        Some(id) => Some(sections.iter().find(|s| &s.id == id)?),
        None => None,
    };
    let (text, transcripts, photo_texts, attachment_texts) = match section {
        Some(s) => (&s.text, &s.transcripts, &s.photo_texts, &s.attachment_texts),
        None => (
            &note.text,
            &note.transcripts,
            &note.photo_texts,
            &note.attachment_texts,
        ),
    };
    let files = match section {
        Some(s) => s.attachments.iter(),
        None => note.attachments.iter(),
    };
    let key = finding.key.as_str();
    let said = match finding.part {
        FindingPart::Text => text.as_str(),
        FindingPart::Transcript => transcripts.get(key)?.as_str(),
        FindingPart::PhotoText => photo_texts.get(key)?.as_str(),
        FindingPart::AttachmentText => attachment_texts.get(key)?.as_str(),
        FindingPart::FileName => files.into_iter().find(|f| f.hash == key)?.name.as_str(),
    };
    Some(at(said, finding.start))
}

/// The size of a Note's text as the Note dialog and the reading view show
/// it, before the Device's text size (#326).
pub(crate) const READ_SIZE: f32 = 18.0;

/// What [`read_part`] draws, the text of a Note or Section: its id, its
/// text, its format and the scope of the grammar a Code text is coloured
/// by (obf-1036).
type ReadPart<'a> = (&'a str, &'a str, &'a str, Option<&'a str>);

/// How the boxes of a [`ReadPart`] show and whether this Device may tick
/// them, with which have been ticked.
type PartBoxes<'a> = (&'a BoxLook, (bool, &'a dyn Fn(&str) -> bool));

/// How far from the window's edges a table in the reading view stays.
pub(crate) const READ_EDGE: f32 = 12.0;

/// Draws the bytes `range` of a Note's or Section's text in the reading
/// view (#322) at `size` points, as a text only read reads in the Note
/// dialog: selectable to be copied, its boxes ticking where this Device
/// may, its tags opening their search, its links their pages and its
/// tables full screen to read, each with all its rows and as wide as
/// `wide`, the window's width, allows (obf-1048); a Code text as code.
fn read_part(
    ui: &mut Ui,
    t: &L10n,
    (of, text, format, language): ReadPart<'_>,
    ((range, size), wide): (((usize, usize), f32), egui::Rangef),
    (boxes, ticks): PartBoxes<'_>,
    actions: &mut Vec<Action>,
) {
    ui.scope(|ui| {
        ui.style_mut().interaction.selectable_labels = true;
        let look = (Some(size), ui.visuals().text_color());
        if format == text_format::CODE {
            read_text::shown(ui, |ui| {
                text_marks_view::code_text_label(ui, (text, language), range, look, (false, true))
            });
            return;
        }
        let tables = TableRoom {
            card: None,
            wide: Some(wide),
        };
        let spots = read_text::shown(ui, |ui| {
            let text = (text, format, boxes);
            text_marks_view::room_label(ui, text, None, range, look, false, tables)
        });
        let id = Id::new(("reading", of));
        if let Some((at, act)) = text_marks_view::table_clicks(ui, t, id, &spots.tables, false) {
            actions.extend(table_action(
                act,
                Opening {
                    note: None,
                    text: text.to_string(),
                    at,
                    cell: None,
                    tags: true,
                    boxes: Some(of.to_string()),
                },
                boxes,
            ));
        }
        if let Some(asked) = text_marks_view::box_clicks(ui, t, id, &spots.boxes, ticks) {
            actions.push(box_action(of.to_string(), asked));
        }
        if let Some(tag) = text_marks_view::tag_clicks(ui, t, id, &spots.tags) {
            actions.push(Action::SearchFor(tag));
        }
        text_marks_view::link_clicks(ui, id, &spots.links);
    });
}

/// The photos `hashes` of the Note or Section `of` in the reading view
/// (#322), each as wide as the column as on a full card, a click showing
/// it full screen.
fn read_photos(
    ui: &mut Ui,
    t: &L10n,
    (cache, store): (&mut PhotoCache, &Store),
    of: &str,
    hashes: &[String],
    actions: &mut Vec<Action>,
) {
    for (at, hash) in hashes.iter().enumerate() {
        let Some(rect) = media_view::card_photo(ui, t, (&mut *cache, store), hash) else {
            continue;
        };
        let id = Id::new(("reading photo", of, at));
        if media_view::photo_click(ui, t, rect, id).clicked() {
            actions.push(Action::ViewPhoto(hash.clone()));
        }
    }
}

/// A Section's text being edited in the Note dialog (#183), as the
/// Note's own is: with the ids of its boxes, whether it is being edited
/// (a formatted text shows its source meanwhile), and whether the field
/// is to take the keyboard, once, with the selection `select` in bytes.
#[derive(Debug, Clone, Default)]
struct SectionField {
    text: String,
    editing: bool,
    focus: bool,
    select: Option<(usize, usize)>,
}

/// The text of a Note or Section and its photos and voice recordings,
/// each as `(shown, removed, texts)`.
struct Part<'a> {
    id: &'a str,
    text: &'a str,
    format: &'a str,
    /// The scope of the grammar a Code text is coloured by (obf-1036).
    language: Option<&'a str>,
    photos: (&'a [String], &'a [String], &'a BTreeMap<String, String>),
    recordings: (&'a [String], &'a [String], &'a BTreeMap<String, String>),
}

impl<'a> Part<'a> {
    fn of_note(note: &'a Note) -> Part<'a> {
        Part {
            id: &note.id,
            text: &note.text,
            format: &note.text_format,
            language: note.code_language.as_deref(),
            photos: (&note.photos, &note.removed_photos, &note.photo_texts),
            recordings: (
                &note.recordings,
                &note.removed_recordings,
                &note.transcripts,
            ),
        }
    }

    fn of_section(section: &'a Section) -> Part<'a> {
        Part {
            id: &section.id,
            text: &section.text,
            format: &section.text_format,
            language: None,
            photos: (
                &section.photos,
                &section.removed_photos,
                &section.photo_texts,
            ),
            recordings: (
                &section.recordings,
                &section.removed_recordings,
                &section.transcripts,
            ),
        }
    }
}

/// The text, photos and recordings of a Note or Section in full on a
/// card (#114), with their Transcripts and Photo Texts; the photos shown
/// with where they lie.
fn whole(
    ui: &mut Ui,
    t: &L10n,
    part: Part,
    (cache, store, transcribing): ShownMedia,
    (look, marks): (&BoxLook, &mut Spots),
) -> Vec<(String, egui::Rect)> {
    card_text(
        ui,
        (part.id, part.text, part.format, look),
        part.language,
        marks,
    );
    media_view::whole_media(
        ui,
        t,
        (cache, store),
        part.photos,
        part.recordings,
        transcribing,
    )
}

/// The whole text `text` of the Note or Section `id` in `format` on a
/// full card, its boxes as `look` says, where its boxes (ADR 0035), tags
/// (#126) and links (#127) lie added to `marks`; a Code text coloured by
/// `language` (obf-1036); its tables folded to their first rows
/// (obf-1048).
fn card_text(
    ui: &mut Ui,
    (id, text, format, look): (&str, &str, &str, &BoxLook),
    language: Option<&str>,
    marks: &mut Spots,
) {
    if !text.is_empty() {
        let colour = ui.visuals().text_color();
        let shown = (0, text.len());
        marks.extend(text_marks_view::room_label(
            ui,
            (text, format, look),
            language,
            shown,
            (Some(16.0), colour),
            false,
            card_tables(id),
        ));
    }
}

/// Whether `note`, without words, goes by a Photo Text of a photo it
/// still shows (obf-1049), which its compact card shows nowhere else; the
/// Texts of its recordings and of its removed photos show on it already.
/// The phone's `_namedByPhoto`.
fn named_by_photo(note: &Note) -> bool {
    let words = |text: Option<&String>| text.is_some_and(|t| !t.trim().is_empty());
    let heard = |hashes: &[String]| hashes.iter().any(|h| words(note.transcripts.get(h)));
    note.visible_text().trim().is_empty()
        && !heard(&note.recordings)
        && !heard(&note.removed_recordings)
        && note.photos.iter().any(|h| words(note.photo_texts.get(h)))
}

/// How the tables of the Note or Section `id` show on its card
/// (obf-1048): folded to their first rows, under the id its card takes
/// their clicks with.
fn card_tables(id: &str) -> TableRoom {
    TableRoom {
        card: Some(Id::new(("card", id))),
        wide: None,
    }
}

/// How many places a search found a card's Note by show under its card
/// (obf-1047, C7b); "+n more" stands for the others.
const CARD_FINDINGS: usize = 3;

/// The places the search found in a card's Note `id` (obf-1047, C7b),
/// under its card: the first [`CARD_FINDINGS`], each its context line
/// with the words found on their tint, a Transcript's, Photo Text's,
/// Attachment Text's or file name's after what it is, then "+n more"
/// for the others. A click on one opens the Note at it, "+n more" at the
/// first not shown.
fn card_findings(ui: &mut Ui, t: &L10n, id: &str, found: &[Finding]) -> Option<Action> {
    if found.is_empty() {
        return None;
    }
    let mut asked = None;
    let open =
        |finding: &Finding| Action::OpenFinding(id.to_string(), Some(Box::new(finding.clone())));
    ui.horizontal(|ui| {
        ui.add_space(20.0);
        ui.vertical(|ui| {
            ui.spacing_mut().item_spacing.y = 4.0;
            for (at, finding) in found.iter().take(CARD_FINDINGS).enumerate() {
                let job = finding_job(ui, t, finding);
                let said = t.desk_finding_open(&job.text);
                let shown = ui.add(egui::Label::new(job).truncate());
                let click = ui.interact(shown.rect, Id::new(("finding", id, at)), Sense::click());
                click.widget_info(|| WidgetInfo::labeled(WidgetType::Button, true, &said));
                if click
                    .on_hover_cursor(egui::CursorIcon::PointingHand)
                    .clicked()
                {
                    asked = Some(open(finding));
                }
            }
            if let Some(next) = found.get(CARD_FINDINGS) {
                let more = (found.len() - CARD_FINDINGS) as i64;
                let accent = theme::tones(ui.visuals()).accent;
                let label = RichText::new(t.desk_find_more(more)).color(accent);
                let button = ui.add(egui::Button::new(label).frame(false));
                if button
                    .on_hover_cursor(egui::CursorIcon::PointingHand)
                    .clicked()
                {
                    asked = Some(open(next));
                }
            }
        });
    });
    asked
}

/// A place found under its card (obf-1047): what it lies in, but for a
/// text, then its context line, the words found on their tint.
fn finding_job(ui: &Ui, t: &L10n, finding: &Finding) -> egui::text::LayoutJob {
    let text = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    let font = FontId::proportional(theme::content(ui, 14.0));
    let plain = egui::TextFormat::simple(font.clone(), text);
    let mut job = egui::text::LayoutJob::default();
    let what = match finding.part {
        FindingPart::Text => None,
        FindingPart::Transcript => Some(t.transcript_label()),
        FindingPart::PhotoText => Some(t.photo_text_label()),
        FindingPart::FileName => Some(t.attachment()),
        FindingPart::AttachmentText => Some(t.attachment_text_label()),
    };
    if let Some(what) = what {
        let small = FontId::proportional(theme::content(ui, 12.0));
        job.append(
            &format!("{what}: "),
            0.0,
            egui::TextFormat::simple(small, weak),
        );
    }
    let context = &finding.context;
    let (a, b) = (finding.context_start, finding.context_end);
    job.append(context.get(..a).unwrap_or_default(), 0.0, plain.clone());
    let found = find_marks::marked(&plain, ui.visuals().dark_mode, false);
    job.append(context.get(a..b).unwrap_or_default(), 0.0, found);
    job.append(context.get(b..).unwrap_or_default(), 0.0, plain);
    job
}

/// Unfolds on a card each table of `note` or of its `sections` the
/// search `found` a place in under its first rows (obf-1047), so that
/// the place shows on the card.
fn show_found_rows(ctx: &egui::Context, note: &Note, sections: &[Section], found: &[Finding]) {
    for finding in found {
        let Some(cell) = finding.cell.filter(|c| c.row > text_marks_view::CARD_ROWS) else {
            continue;
        };
        let (of, text) = match &finding.section {
            None => (note.id.as_str(), note.text.as_str()),
            Some(id) => match sections.iter().find(|s| &s.id == id) {
                Some(s) => (s.id.as_str(), s.text.as_str()),
                None => continue,
            },
        };
        let (_, cuts) = find_marks::shown_of(text);
        let at = find_marks::source_at(&cuts, cell.table_start);
        text_marks_view::show_all_rows(ctx, Id::new(("card", of)), at);
    }
}

/// The text `text` of the Note `id` of a kind in `format` on its full
/// card (#188): its name as the card's title, its description under it,
/// small, folded to its first line with words unless `unfolded`, its
/// tables to their first rows (obf-1048); where its boxes, tags and
/// links lie added to `marks`, and where the description shows.
fn card_kinded_text(
    ui: &mut Ui,
    (id, text, format, look): (&str, &str, &str, &BoxLook),
    (unfolded, untitled): (bool, Option<String>),
    marks: &mut Spots,
) -> Option<egui::Rect> {
    let colour = ui.visuals().text_color();
    let weak = ui.visuals().weak_text_color();
    let named = note_kinds::name(text).len();
    if let Some(kind) = untitled.filter(|_| note_kinds::name(text).trim().is_empty()) {
        // A list without a name by its kind (#309).
        ui.label(
            RichText::new(kind)
                .size(theme::content(ui, 20.0))
                .color(colour),
        );
    } else if named > 0 {
        let heading = (Some(20.0), colour);
        let label =
            text_marks_view::formatted_label(ui, (text, format, look), (0, named), heading, false);
        marks.extend(label);
    }
    let description = note_kinds::description(text);
    let start = text.len() - description.len();
    let (from, to) = first_line(description)?;
    let range = if unfolded {
        (start, text.len())
    } else {
        (start + from, start + to)
    };
    let small = (Some(13.0), weak);
    let drawn = folded_row(ui, unfolded, |ui| {
        let text = (text, format, look);
        let tables = card_tables(id);
        text_marks_view::room_label(ui, text, None, range, small, !unfolded, tables)
    });
    marks.extend(drawn.inner);
    Some(drawn.response.rect)
}

/// The photo cache, the store the photos are read from and the
/// recording being transcribed, for [`whole`].
type ShownMedia<'a, 'b> = (&'b mut PhotoCache, &'a Store, Option<&'a str>);

/// A Note as a card (UI laws, "Cards"): Edit, ⋮ (but in the trash) and,
/// in a list with its switch, the view button top right (#189), and where
/// it is filed, its Area's colour down the left edge and icon before the
/// place; then, as `look` says, its detailed view: the whole Note with its
/// Capture Context as one line under its text (#170), a Checklist's or a
/// Shopping List's Lines under its name and description (#188), checkable,
/// a Shopping List's struck ones folded under its open ones, with every
/// Section oldest first, each with its own line, its photos opening full
/// screen on a click, then the Notes that link to it (obf-1035), a click
/// on one opening it; or its compact view, a glance by its kind (#189): a
/// plain Note's first line and the two lines after it or the `glance` of
/// the Session it runs, a list's or a Tally's name with how many of its
/// Lines are open or the Tally's `glance`, a Note without words its
/// media; no Capture Context. ⋮ and a right-click open
/// the same menu: Edit, then making it a Checklist, "Uncheck all", "Back
/// to a plain Note" and making it a Shopping List as this Device may
/// (#120, #122). Important cards carry the accent marker and a stronger
/// emboss; unimportant ones are dimmed. A `draggable` card can be
/// dropped onto an Area or Topic, its drag started by the list; a
/// `selected` one is outlined while its editor shows; a `chosen` one,
/// among the cards selected (#148), carries a check mark and a thicker
/// outline, and says so to a screen reader.
fn note_card(
    ui: &mut Ui,
    t: &L10n,
    tones: Tones,
    placed: &Placed,
    (selected, chosen, draggable): (bool, bool, bool),
    look: CardLook,
    media: CardMedia,
) -> CardClicks {
    let note = &placed.note;
    let important = note.importance == Importance::Important;
    let unimportant = note.importance == Importance::Unimportant;
    let colour = placed
        .area
        .as_ref()
        .and_then(|a| area_colour(a.colour.as_deref()));
    let mut author_rect = None;
    let mut edit_rect = egui::Rect::NOTHING;
    let mut more_rect = None;
    let mut view_rect = None;
    let mut hidden_rect = None;
    // Where the fold of a Shopping List's struck Lines shows in the
    // detailed view, how many, and whether it is open (#189).
    let struck_id = Id::new(("card struck", &note.id));
    let struck_open = look.folds.struck;
    let mut struck_rect = None;
    // Where the description of a Note of a kind shows on a full card, and
    // whether it is unfolded (#188).
    let fold_id = Id::new(("card description", &note.id));
    let unfolded = look.folds.description;
    let mut description_rect = None;
    // The photos shown in full, where they lie, the checkboxes of its
    // Lines and the status marks and tags of its text and of its
    // Sections'.
    let mut shown = Vec::new();
    // Its files and its Sections', by the Note or Section holding them,
    // with where their rows lie (#267).
    let mut files_shown: Vec<(String, Attachment, egui::Rect)> = Vec::new();
    let alone = note.alone_file().is_some();
    let mut boxes = Vec::new();
    let mut marks = Spots::default();
    let mut section_marks: Vec<(&Section, Spots)> = Vec::new();
    // The rows of "Linked from" on a full card (obf-1035).
    let mut linked_rows = Vec::new();
    // Where the Tally or the Session of a full card lies, out of the
    // card's own click, and what was asked of it (#190, #191).
    let mut tally_rect = None;
    let mut tally_asked = Vec::new();
    let mut session_asked = Vec::new();
    // Where the boxes of today's Occurrences lie (#215).
    let mut today_rects = Vec::new();
    let CardMedia {
        photos,
        pictures,
        store,
        transcribing,
    } = media;
    let inner = ui.scope(|ui| {
        if unimportant {
            ui.multiply_opacity(theme::UNIMPORTANT_OPACITY);
        }
        let text = ui.visuals().text_color();
        let weak = ui.visuals().weak_text_color();
        let card = embossed(ui, tones, important, colour, |ui| {
            if important {
                // Room for the marker on the right.
                ui.set_max_width(ui.available_width() - 36.0);
            }
            // The card's buttons stand in a column of their own on the
            // right, its first row (#330): in front of them a place for
            // the check mark of a card selected along, kept while it is
            // not, so selecting one moves nothing.
            let gap = ui.spacing().item_spacing.x;
            let count = 2 + [!note.is_trashed(), look.switches, look.hidden]
                .into_iter()
                .filter(|b| *b)
                .count();
            let buttons = count as f32 * 24.0 + (count - 1) as f32 * gap;
            ui.horizontal_top(|ui| {
                let width = (ui.available_width() - buttons - gap).max(0.0);
                ui.vertical(|ui| {
                    ui.set_width(width);
                    // Another person's Note shows their picture (ADR
                    // 0017), the user's own none, then where it is filed
                    // where the list is not of it (#330). A Note that
                    // spawned a Routine is not Unsorted, though not filed.
                    let place = match place_line(t, placed) {
                        _ if !look.place => None,
                        Some(line) => Some(line),
                        None if note.spawned => None,
                        None => Some(t.unsorted().to_string()),
                    };
                    if place.is_some() || placed.author.is_some() {
                        ui.horizontal(|ui| {
                            ui.set_min_height(24.0);
                            if let Some(author) = &placed.author {
                                let name = profile_view::display_name(t, &author.name);
                                let picture = profile_view::person_picture(
                                    ui,
                                    pictures,
                                    author,
                                    20.0,
                                    &t.author_picture(name),
                                );
                                author_rect = Some(picture.rect);
                            }
                            if let Some(place) = place {
                                if let Some(icon) = placed
                                    .area
                                    .as_ref()
                                    .and_then(|a| icons::area_icon(a.icon.as_deref()))
                                {
                                    icons::show(ui, icon, 16.0, colour.unwrap_or(weak));
                                }
                                ui.label(RichText::new(place).color(text));
                            }
                        });
                    }
                    // Who the Pack it came from unclaimed is from, until
                    // removed (#165).
                    if let Some(from) = &placed.pack_from {
                        ui.horizontal(|ui| {
                            icons::show(ui, pack_view::PACK_ICON, 16.0, weak);
                            let said = t.pack_from(profile_view::display_name(t, &from.name));
                            ui.label(RichText::new(said).small().color(weak));
                        });
                    }
                    // Under where it is filed, over its text (#215).
                    today_rects = card_occurrences::card_rows(ui, t, tones, look.today);
                    if look.full {
                        ui.vertical(|ui| {
                            ui.spacing_mut().item_spacing.y = 8.0;
                            let part = Part::of_note(note);
                            let lines = match (look.checklist, look.shopping) {
                                (Some((list, _)), _) => Some(checklist_view::shown_lines(list)),
                                (None, Some((list, _))) => {
                                    Some(shopping_view::shown_lines(t, list))
                                }
                                (None, None) => None,
                            };
                            if lines.is_some() || look.tally || look.session {
                                // Its name as its title, its description folded
                                // under it (#188), its Lines right under them.
                                let text =
                                    (part.id, part.text, part.format, look.boxes.look(part.id));
                                let untitled = l10n::untitled_list(t, note);
                                description_rect =
                                    card_kinded_text(ui, text, (unfolded, untitled), &mut marks);
                                if let Some(lines) = &lines {
                                    // A Shopping List's struck Lines fold under its
                                    // open ones (#189).
                                    let (open, struck): (Vec<_>, Vec<_>) = lines
                                        .iter()
                                        .cloned()
                                        .partition(|l| look.shopping.is_none() || !l.checked);
                                    // As clicked while the saves wait, where
                                    // they lie (#338).
                                    let on = look.checklist.and_then(|(l, _)| l.on.as_ref());
                                    let open = checklist_view::as_clicked(ui.ctx(), &open, on);
                                    let struck = checklist_view::as_clicked(ui.ctx(), &struck, on);
                                    boxes = checklist_view::card_lines(ui, tones, &open);
                                    if !struck.is_empty() {
                                        let said = t.shopping_struck_count(struck.len() as i64);
                                        let row = folded_row(ui, struck_open, |ui| {
                                            ui.label(RichText::new(&said).small().color(weak));
                                        });
                                        struck_rect = Some((row.response.rect, said));
                                        if struck_open {
                                            boxes.extend(checklist_view::card_lines(
                                                ui, tones, &struck,
                                            ));
                                        }
                                    }
                                }
                                if let Some(shown) = look.tally_shown {
                                    let drawn = ui.scope(|ui| {
                                        tally_view::card(ui, t, shown, &mut tally_asked)
                                    });
                                    tally_rect = Some(drawn.response.rect);
                                }
                                if let Some(shown) = look.session_shown {
                                    let drawn = ui.scope(|ui| {
                                        session_view::card(ui, t, shown, &mut session_asked)
                                    });
                                    tally_rect = Some(drawn.response.rect);
                                }
                                shown.extend(media_view::whole_media(
                                    ui,
                                    t,
                                    (&mut *photos, store),
                                    part.photos,
                                    part.recordings,
                                    transcribing,
                                ));
                            } else {
                                let media = (&mut *photos, store, transcribing);
                                let boxes = look.boxes.look(part.id);
                                shown.extend(whole(ui, t, part, media, (boxes, &mut marks)));
                            }
                            let files = (
                                note.attachments.as_slice(),
                                note.removed_attachments.as_slice(),
                                &note.attachment_texts,
                            );
                            let drawn = attachment_view::card_files(ui, t, files, false, alone);
                            files_shown
                                .extend(drawn.into_iter().map(|(f, r)| (note.id.clone(), f, r)));
                            // Each part's Capture Context under its text (#170).
                            let line = capture_line(t, (note.captured, &note.context), None);
                            capture_meta(ui, t, &line, None, false);
                            let mut before = note.captured;
                            // Each Section reads on under a tear line (#307).
                            for section in look.sections {
                                theme::tear_line(ui);
                                let part = Part::of_section(section);
                                let mut spots = Spots::default();
                                let media = (&mut *photos, store, transcribing);
                                let boxes = look.boxes.look(part.id);
                                shown.extend(whole(ui, t, part, media, (boxes, &mut spots)));
                                let files = (
                                    section.attachments.as_slice(),
                                    section.removed_attachments.as_slice(),
                                    &section.attachment_texts,
                                );
                                let drawn = attachment_view::card_files(ui, t, files, false, false);
                                files_shown.extend(
                                    drawn.into_iter().map(|(f, r)| (section.id.clone(), f, r)),
                                );
                                section_marks.push((section, spots));
                                let line = capture_line(
                                    t,
                                    (section.captured, &section.context),
                                    Some(before),
                                );
                                let edited = section_edited(t, section);
                                capture_meta(ui, t, &line, edited.as_deref(), false);
                                before = section.captured;
                            }
                            // At its end, after the Sections (obf-1035).
                            linked_rows = app_links::linked_from_rows(ui, t, look.linked_from);
                        });
                        return;
                    }
                    // The compact view, by the Note's kind (#189).
                    let text_of = (
                        note.text.as_str(),
                        note.text_format.as_str(),
                        look.boxes.look(&note.id),
                    );
                    // A Code text coloured by its language (obf-1036).
                    let language = note.code_language.as_deref();
                    if look.checklist.is_some()
                        || look.shopping.is_some()
                        || look.tally
                        || look.session
                    {
                        // Its name, then how many Lines are open, or the Tally's
                        // totals today, or the Session's next run and week (#191).
                        let named = note_kinds::name(&note.text).len();
                        let untitled = l10n::untitled_list(t, note)
                            .filter(|_| note_kinds::name(&note.text).trim().is_empty());
                        if let Some(kind) = untitled {
                            // A list without a name by its kind (#309).
                            ui.label(RichText::new(kind).size(20.0).color(text));
                        } else if named > 0 {
                            marks = text_marks_view::note_label(
                                ui,
                                text_of,
                                language,
                                (0, named),
                                (Some(20.0), text),
                                true,
                            );
                        }
                        if let Some((list, _)) = look.checklist {
                            checklist_view::card_count(ui, t, list);
                        } else if let Some((list, _)) = look.shopping {
                            shopping_view::card_count(ui, t, list);
                        }
                        card_glance_lines(ui, look.glance);
                        return;
                    }
                    // A plain Note: its first line and the two after it, or, running
                    // a Session, its next run and this week (#189).
                    if let Some(line) =
                        card_first_line(&note.text, note.text_format == text_format::MARKDOWN)
                    {
                        marks = text_marks_view::note_label(
                            ui,
                            text_of,
                            language,
                            line,
                            (Some(16.0), text),
                            true,
                        );
                        if look.glance.is_empty() {
                            if let Some(next) = next_lines(&note.text, line.1) {
                                let more = text_marks_view::note_label(
                                    ui,
                                    text_of,
                                    language,
                                    next,
                                    (Some(14.0), text),
                                    false,
                                );
                                marks.extend(more);
                            }
                        } else {
                            card_glance_lines(ui, look.glance);
                        }
                        return;
                    }
                    card_glance_lines(ui, look.glance);
                    // Without words it shows what it holds instead, named by
                    // the first line of a photo's text when it has one
                    // (obf-1049).
                    if named_by_photo(note) {
                        let name = RichText::new(note.shown_name()).size(16.0).color(text);
                        ui.add(egui::Label::new(name).truncate());
                    }
                    if !note.photos.is_empty() {
                        media_view::thumbnails(ui, t, photos, store, &note.photos, 64.0, 3);
                    }
                    media_view::recordings(
                        ui,
                        t,
                        &note.recordings,
                        &note.transcripts,
                        (None, transcribing, 1.0),
                        (false, false),
                        &|_| Offers::default(),
                    );
                    media_view::removed_texts(
                        ui,
                        t,
                        (&note.removed_photos, &note.photo_texts),
                        (&note.removed_recordings, &note.transcripts),
                        &|_, _| Offers::default(),
                        false,
                    );
                    // Its files (#267): one alone is the card, titled by its name.
                    let files = (
                        note.attachments.as_slice(),
                        note.removed_attachments.as_slice(),
                        &note.attachment_texts,
                    );
                    let drawn = attachment_view::card_files(ui, t, files, true, alone);
                    files_shown.extend(drawn.into_iter().map(|(f, r)| (note.id.clone(), f, r)));
                });
                ui.allocate_ui_with_layout(
                    egui::vec2(buttons, 24.0),
                    egui::Layout::right_to_left(egui::Align::Center),
                    |ui| {
                        edit_rect = ui
                            .allocate_exact_size(egui::vec2(24.0, 24.0), Sense::hover())
                            .0;
                        // A Note in the trash is restored, not changed.
                        if !note.is_trashed() {
                            more_rect = Some(
                                ui.allocate_exact_size(egui::vec2(24.0, 24.0), Sense::hover())
                                    .0,
                            );
                        }
                        // Its view shows under the Note's text, its time
                        // and place in the detailed view (#170, #189).
                        if look.switches {
                            view_rect = Some(
                                ui.allocate_exact_size(egui::vec2(24.0, 24.0), Sense::hover())
                                    .0,
                            );
                        }
                        // Hidden from AI, by its own mark or another's
                        // (#267).
                        if look.hidden {
                            hidden_rect = Some(
                                ui.allocate_exact_size(egui::vec2(24.0, 24.0), Sense::hover())
                                    .0,
                            );
                        }
                        let mark = ui
                            .allocate_exact_size(egui::vec2(24.0, 24.0), Sense::hover())
                            .0;
                        if chosen {
                            icons::paint(
                                ui.painter(),
                                mark.shrink(3.0),
                                icons::STATUS_DONE,
                                tones.accent,
                            );
                        }
                    },
                );
            });
        });
        let rect = card.rect;
        if important {
            let marker = egui::Rect::from_center_size(
                egui::pos2(rect.right() - 28.0, rect.top() + 28.0),
                egui::vec2(24.0, 24.0),
            );
            icons::paint(ui.painter(), marker, icons::IMPORTANT, tones.accent);
        }
        if chosen {
            ui.painter().rect_stroke(
                rect,
                theme::CARD_RADIUS,
                egui::Stroke::new(3.0, tones.accent),
                egui::StrokeKind::Inside,
            );
        } else if selected {
            ui.painter().rect_stroke(
                rect,
                theme::CARD_RADIUS,
                egui::Stroke::new(2.0, tones.accent),
                egui::StrokeKind::Outside,
            );
        }
        rect
    });
    let rect = inner.inner;
    let sense = if draggable {
        Sense::click_and_drag()
    } else {
        Sense::click()
    };
    // Around the Tally or the Session of a full card, whose own buttons
    // take its clicks (#190, #191).
    let resp = match tally_rect {
        Some(hole) => {
            let above = egui::Rect::from_min_max(rect.min, egui::pos2(rect.max.x, hole.min.y));
            let below = egui::Rect::from_min_max(egui::pos2(rect.min.x, hole.max.y), rect.max);
            let top = ui.interact(above, Id::new(("card", &note.id)), sense);
            top.union(ui.interact(below, Id::new(("card below", &note.id)), sense))
        }
        None => ui.interact(rect, Id::new(("card", &note.id)), sense),
    };
    let label = note.shown_name();
    resp.widget_info(|| WidgetInfo::selected(WidgetType::Button, true, chosen, &label));
    // The author's picture and Edit lie over the card: registered after
    // it, so they take the click.
    let author = author_rect
        .zip(placed.author.as_ref())
        .map(|(rect, author)| {
            let label = t.person_open(profile_view::display_name(t, &author.name));
            let picture = ui.interact(rect, Id::new(("author", &note.id)), Sense::click());
            picture.widget_info(|| WidgetInfo::labeled(WidgetType::Button, true, &label));
            picture
                .on_hover_cursor(egui::CursorIcon::PointingHand)
                .on_hover_text(label)
        });
    let edit = ui.interact(edit_rect, Id::new(("edit", &note.id)), Sense::click());
    if let Some(rect) = hidden_rect {
        hidden_mark(ui, t, rect.shrink(2.0), Id::new(("hidden", &note.id)));
    }
    edit.widget_info(|| WidgetInfo::labeled(WidgetType::Button, true, t.edit()));
    // A fold clicked open or closed, kept per Note on this Device (#189).
    let mut folded = None;
    // The view button over the card, switching its view (#189).
    let view_said = if look.full {
        t.card_show_compact()
    } else {
        t.card_show_detailed()
    };
    let view = ui.interact(
        view_rect.unwrap_or(egui::Rect::NOTHING),
        Id::new(("view", &note.id)),
        Sense::click(),
    );
    if let Some(view_rect) = view_rect {
        view.widget_info(|| WidgetInfo::labeled(WidgetType::Button, true, view_said));
        if ui.is_rect_visible(view_rect) {
            if view.hovered() {
                let fill = ui.visuals().widgets.hovered.weak_bg_fill;
                ui.painter().rect_filled(view_rect, 6.0, fill);
            }
            let icon = if look.full {
                icons::EXPAND_LESS
            } else {
                icons::EXPAND_MORE
            };
            icons::paint(
                ui.painter(),
                view_rect.shrink(2.0),
                icon,
                ui.visuals().weak_text_color(),
            );
        }
    }
    // A click on the struck Lines' fold shows or hides them (#189).
    if let Some((rect, said)) = &struck_rect {
        let fold = ui.interact(*rect, struck_id.with("fold"), Sense::click());
        fold.widget_info(|| WidgetInfo::labeled(WidgetType::Button, true, said));
        if fold
            .on_hover_cursor(egui::CursorIcon::PointingHand)
            .clicked()
        {
            folded = Some((struck_shown_setting(&note.id), !struck_open));
        }
    }
    // Over the card too: a click on the description folds or unfolds it,
    // not the card's own (#188).
    if let Some(rect) = description_rect
        && description_fold(ui, t, (rect, fold_id), unfolded)
    {
        folded = Some((description_unfolded_setting(&note.id), !unfolded));
    }
    if ui.is_rect_visible(edit_rect) {
        let dim = |c: Color32| {
            if unimportant {
                c.gamma_multiply(theme::UNIMPORTANT_OPACITY)
            } else {
                c
            }
        };
        if edit.hovered() {
            let fill = dim(ui.visuals().widgets.hovered.weak_bg_fill);
            ui.painter().rect_filled(edit_rect, 6.0, fill);
        }
        let fg = dim(ui.visuals().text_color());
        icons::paint(ui.painter(), edit_rect.shrink(2.0), icons::EDIT, fg);
    }
    // ⋮ and a right-click on the card open the same menu, read as it
    // opens (#120).
    let mut menu_opened = resp.secondary_clicked();
    let mut picked = None;
    let menu = look.menu.filter(|m| m.note == note.id);
    let spawns = look.spawns.filter(|s| s.note == note.id);
    let has_boxes = !note.boxes.is_empty() || look.sections.iter().any(|s| !s.boxes.is_empty());
    let mut entries = |ui: &mut Ui| {
        let text = ui.visuals().text_color();
        let entry =
            |ui: &mut Ui, label: &str| ui.button(RichText::new(label).color(text)).clicked();
        // Edit, then the Note dialog's groups (obf-1014): This Note ▸,
        // Add ▸, Share ▸ and Tidy ▸, each only with something in it.
        if entry(ui, t.edit()) {
            picked = Some(Action::SelectNote(note.id.clone()));
        }
        // Beside the list (#287), for this card alone.
        if !note.is_trashed() && entry(ui, t.note_window_open()) {
            picked = Some(Action::OpenWindow(note.id.clone()));
        }
        // These with the cards selected along (#148, #273).
        let one = || vec![note.id.clone()];
        let pack_from = placed.pack_from.as_ref().filter(|_| look.changes);
        let hidden = spawns.and_then(|s| s.hidden);
        let kinds = menu.is_some_and(|m| m.make || m.make_shopping || m.to_plain);
        let on_agenda =
            menu.is_some_and(|m| m.on_agenda.is_some() || m.shopping_on_agenda.is_some());
        let this_note = look.changes
            || look.may
            || kinds
            || on_agenda
            || pack_from.is_some()
            || has_boxes
            || hidden.is_some();
        if this_note {
            ui.menu_button(
                RichText::new(t.editor_group_this_note()).color(text),
                |ui| {
                    if look.changes && entry(ui, t.file_into()) {
                        picked = Some(Action::AskFileInto(one()));
                    }
                    if look.may {
                        ui.menu_button(RichText::new(t.importance()).color(text), |ui| {
                            if let Some(importance) = importance_entries(ui, t, false) {
                                picked = Some(Action::ImportanceOf(one(), importance));
                            }
                        });
                    }
                    // Its kind as the Kind badge changes it, then how a list
                    // shows on the Agenda (#186, #219).
                    if let Some(menu) = menu.filter(|_| kinds) {
                        ui.menu_button(RichText::new(t.badge_kind()).color(text), |ui| {
                            if let Some(asked) = checklist_view::card_make(ui, t, menu) {
                                picked = Some(Action::Checklist(asked));
                            }
                            if let Some(asked) = shopping_view::card_menu_entry(ui, t, menu) {
                                picked = Some(Action::Shopping(asked));
                            }
                            if let Some(asked) = checklist_view::card_to_plain(ui, t, menu) {
                                picked = Some(Action::Checklist(asked));
                            }
                        });
                    }
                    if let Some(asked) = menu.and_then(|m| shopping_view::card_on_agenda(ui, t, m))
                    {
                        picked = Some(Action::Shopping(asked));
                    }
                    if let Some(asked) = menu.and_then(|m| checklist_view::card_on_agenda(ui, t, m))
                    {
                        picked = Some(Action::Checklist(asked));
                    }
                    // Who they came from (#165).
                    if let Some(from) = pack_from {
                        let name = profile_view::display_name(t, &from.name);
                        let label = t.remove_pack_from(name);
                        if ui.button(RichText::new(label).color(text)).clicked() {
                            picked = Some(Action::RemovePackFrom(note.id.clone()));
                        }
                    }
                    // Who ticked each box last and when (ADR 0035), where it
                    // has any.
                    if has_boxes {
                        let mut on = look.boxes.show;
                        let label = RichText::new(t.box_show_ticks()).color(text);
                        if theme::checkbox(ui, &mut on, label).clicked() {
                            picked = Some(Action::ShowTicks {
                                note: note.id.clone(),
                                on,
                            });
                        }
                    }
                    // Read as the menu opens, in no Shared Area or to take it
                    // off (#267).
                    if let Some(on) = hidden
                        && let Some(asked) = hidden_switch(ui, t, &note.id, on)
                    {
                        picked = Some(asked);
                    }
                },
            );
        }
        // Its Routines as the "+" badge sets them up (#281), for this card
        // alone; files of any kind and a part as the dialog adds them
        // (obf-1014).
        let spawned = spawns.map(|s| (s.schedules, s.frog, s.session, s.amends));
        let (schedules, frog, session, amends) = spawned.unwrap_or_default();
        if schedules || look.may || amends {
            ui.menu_button(RichText::new(t.add()).color(text), |ui| {
                let id = || Some(note.id.clone());
                if schedules {
                    // One way in for a Routine or Reminder, starting as a
                    // Reminder (#344).
                    let reminder = Action::NewRoutine {
                        note: id(),
                        reminder: true,
                    };
                    if entry(ui, t.remind_me()) {
                        picked = Some(reminder);
                    }
                }
                if frog && entry(ui, t.frog()) {
                    picked = Some(Action::SpawnFrog(note.id.clone()));
                }
                if session && entry(ui, t.spawn_session()) {
                    picked = Some(Action::NewSession(id()));
                }
                if look.may && entry(ui, t.attach_file()) {
                    picked = Some(Action::AttachFilesTo(note.id.clone()));
                }
                // Opens the Note dialog with the Amend box open.
                if amends && entry(ui, t.add_a_part()) {
                    picked = Some(Action::AddPartTo(note.id.clone()));
                }
            });
        }
        // To a person as a Sent Item, or to another app (#129), and copies
        // for another person (#165).
        ui.menu_button(RichText::new(t.share()).color(text), |ui| {
            if entry(ui, t.send_to_person()) {
                picked = Some(Action::StartSend(note.id.clone()));
            }
            if entry(ui, t.copy_text()) {
                picked = Some(Action::CopyAsText(note.id.clone()));
            }
            let markdown = Action::SaveAsMarkdown(note.id.clone());
            if entry(ui, t.save_as_markdown()) {
                picked = Some(markdown);
            }
            if entry(ui, t.export_as_pack()) {
                picked = Some(Action::ExportPack(note.id.clone()));
            }
        });
        let unchecks = menu.is_some_and(|m| m.uncheck_all);
        if look.may || unchecks {
            ui.menu_button(RichText::new(t.editor_group_tidy()).color(text), |ui| {
                // On an Unsorted Note's card the Merge is picked as a
                // capture picks its Note (#308).
                if look.may {
                    let merge = if note.is_unsorted() {
                        Action::AskAddToNote(one())
                    } else {
                        Action::AskMergeNotes(one())
                    };
                    if entry(ui, t.merge_into()) {
                        picked = Some(merge);
                    }
                }
                if let Some(asked) = menu.and_then(|m| checklist_view::card_uncheck_all(ui, t, m)) {
                    picked = Some(Action::Checklist(asked));
                }
                if look.may {
                    let error = ui.visuals().error_fg_color;
                    if ui
                        .button(RichText::new(t.move_to_trash()).color(error))
                        .clicked()
                    {
                        picked = Some(Action::TrashNotes(one()));
                    }
                }
            });
        }
        // A pick closes the menu, also one made with the keyboard or a
        // screen reader, which no pointer click closes.
        if picked.is_some() {
            ui.close();
        }
    };
    if let Some(more_rect) = more_rect {
        let title = row_title(t, Some(note));
        let label = checklist_view::menu_label(t, title.lines().next().unwrap_or_default());
        let more = ui.interact(more_rect, Id::new(("more", &note.id)), Sense::click());
        more.widget_info(|| WidgetInfo::labeled(WidgetType::Button, true, &label));
        if ui.is_rect_visible(more_rect) {
            if more.hovered() {
                let fill = ui.visuals().widgets.hovered.weak_bg_fill;
                ui.painter().rect_filled(more_rect, 6.0, fill);
            }
            let fg = ui.visuals().weak_text_color();
            icons::paint(ui.painter(), more_rect.shrink(2.0), icons::MORE_VERT, fg);
        }
        menu_opened |= more.clicked();
        let more = more.on_hover_text(&label);
        egui::Popup::menu(&more).show(&mut entries);
        resp.context_menu(&mut entries);
    } else if note.is_trashed() && look.may {
        // In the trash a right-click restores it, with the cards selected
        // along (#273); it has no ⋮.
        resp.context_menu(|ui| {
            let text = ui.visuals().text_color();
            if ui.button(RichText::new(t.restore()).color(text)).clicked() {
                picked = Some(Action::RestoreNotes(vec![note.id.clone()]));
                ui.close();
            }
        });
    }
    if menu_opened {
        ui.ctx().request_repaint();
    }
    // A click on a photo opens it full screen (UI laws, "Cards").
    let mut photo = None;
    for (i, (hash, rect)) in shown.into_iter().enumerate() {
        let id = Id::new(("photo", &note.id, i));
        if media_view::photo_click(ui, t, rect, id).clicked() {
            photo = Some(hash);
        }
    }
    // A click on a file opens it with the system's program (#267).
    let mut attachment = None;
    for (of, file, rect) in files_shown {
        let id = Id::new(("card file", &of, &file.hash));
        if attachment_view::open_click(ui, t, &file, rect, id) {
            attachment = Some((of, file.hash));
        }
    }
    let checks = look.checklist.is_some_and(|(_, checks)| checks)
        || look.shopping.is_some_and(|(_, checks)| checks);
    let check = checklist_view::card_checks(ui, tones, &note.id, &boxes, checks);
    let occurrence =
        card_occurrences::card_clicks(ui, (t, tones), &note.id, look.today, &today_rects);
    // Sections have no edit of their text: their marks only show. A
    // table opens full screen, to edit where its marks may change (#128);
    // taken first, its marks, tags and links keep their clicks.
    let of = Id::new(("card", &note.id));
    let mut table =
        text_marks_view::table_clicks(ui, t, of, &marks.tables, false).and_then(|(at, act)| {
            let opening = Opening {
                note: look.changes.then(|| note.id.clone()),
                text: note.text.clone(),
                at,
                cell: None,
                tags: true,
                boxes: Some(note.id.clone()),
            };
            table_action(act, opening, look.boxes.look(&note.id))
        });
    for (section, spots) in &section_marks {
        let of = Id::new(("card", &section.id));
        if let Some((at, act)) = text_marks_view::table_clicks(ui, t, of, &spots.tables, false) {
            let opening = Opening {
                note: None,
                text: section.text.clone(),
                at,
                cell: None,
                tags: true,
                boxes: Some(section.id.clone()),
            };
            table = table_action(act, opening, look.boxes.look(&section.id)).or(table);
        }
    }
    // A box of its text, or of a Section's, ticks where this Device may
    // (ADR 0035).
    let ticks = look.boxes.ticks.contains(&note.id);
    let mut tick =
        text_marks_view::box_clicks(ui, t, of, &marks.boxes, (ticks, &ticked_in(&note.boxes)))
            .map(|asked| (note.id.clone(), asked));
    // A click on a tag searches for it, and opens no card (#126).
    let mut tag = text_marks_view::tag_clicks(ui, t, of, &marks.tags);
    // A click on a link opens it, and no card (#127).
    text_marks_view::link_clicks(ui, of, &marks.links);
    for (section, spots) in &section_marks {
        let of = Id::new(("card", &section.id));
        let ticks = look.boxes.ticks.contains(&section.id);
        let ticked = ticked_in(&section.boxes);
        if let Some(asked) = text_marks_view::box_clicks(ui, t, of, &spots.boxes, (ticks, &ticked))
        {
            tick = Some((section.id.clone(), asked));
        }
        tag = text_marks_view::tag_clicks(ui, t, of, &spots.tags).or(tag);
        text_marks_view::link_clicks(ui, of, &spots.links);
    }
    // A click on a Note linking to it opens that Note, and no card
    // (obf-1035).
    for row in &linked_rows {
        app_links::linked_row_clicks(ui, &note.id, row);
    }
    CardClicks {
        card: resp.on_hover_cursor(egui::CursorIcon::PointingHand),
        author,
        edit: edit.on_hover_text(t.edit()),
        view: view.on_hover_text(view_said),
        folded,
        photo,
        attachment,
        check,
        occurrence,
        tick,
        table,
        tag,
        menu_opened,
        picked,
        tally: tally_asked,
        session: session_asked,
    }
}

/// Where the table beginning at the byte `at` of `from` begins in `to`:
/// the table in the same place among the tables there, for `to` the same
/// text written again (its ends trimmed, say).
fn same_table((from, at): (&str, usize), to: &str) -> Option<usize> {
    let index = markdown::table::all(from)
        .iter()
        .position(|t| t.start == at)?;
    markdown::table::all(to).get(index).map(|t| t.start)
}

/// Where the `2` lines after the byte `from` of `text` lie in it, from the
/// first with words, without the spaces around them, as a compact card
/// shows them under a plain Note's first line (#189); none when no words
/// follow.
fn next_lines(text: &str, from: usize) -> Option<(usize, usize)> {
    let rest = text.get(from..)?;
    let start = from + rest.len() - rest.trim_start().len();
    let after = text.get(start..)?;
    if after.is_empty() {
        return None;
    }
    let end = match after.match_indices('\n').nth(1) {
        Some((at, _)) => start + at,
        None => text.len(),
    };
    let lines = text.get(start..end)?.trim_end();
    Some((start, start + lines.len()))
}

/// Where the first line a compact card shows of `text` lies, in bytes:
/// [`first_line`], or, a formatted text opening with a code block, the
/// first line with words after its opening fence, which shows nothing
/// (#212).
fn card_first_line(text: &str, formatted: bool) -> Option<(usize, usize)> {
    let line = first_line(text)?;
    if formatted
        && let Some(block) = markdown::parse(text).get(markdown::line_at(text, line.0))
        && block
            .code
            .as_ref()
            .is_some_and(|c| c.first_line == block.line)
        && let Some((a, b)) = text.get(block.end..).and_then(first_line)
    {
        return Some((block.end + a, block.end + b));
    }
    Some(line)
}

/// The lines the compact view says of a Tally or of a Session (#189).
fn card_glance_lines(ui: &mut Ui, glance: &[String]) {
    let text = ui.visuals().text_color();
    for line in glance {
        ui.label(RichText::new(line).size(14.0).color(text));
    }
}

/// Where the first line of `text` that a compact card shows lies in it,
/// in bytes: the text's first line with words, none for a text without
/// any.
fn first_line(text: &str) -> Option<(usize, usize)> {
    let start = text.len() - text.trim_start().len();
    let rest = text.get(start..)?;
    let line = rest.trim_end().lines().next()?;
    Some((start, start + line.len()))
}

